	$buttonOK_Click = {
	    $script:InputFormResult = @()
	    $InvalidFound = $false
	    $ErrMsg = "The following entries are invalid format and will be ignored:`r`n" | Out-String
	    
	    switch ($InputType) {
	        "ComputerName"
	        {
	            foreach ($Row in $datagridviewInputForm.Rows) {
	                If ($Row.Cells[0].Value -notin @("", $null)) {
	                    $Data = $Row.Cells[0].Value.ToString().Trim()
	                    If ($Data -match "\s") {
	                        $InvalidFound = $true
	                        $ErrMsg += $Data | Out-String
	                    }
	                    Else {
	                        $script:InputFormResult += $Row.Cells[0].Value.ToString().Trim()
	                    }
	                }
	            }
	        }
	        "VulnID"
	        {
	            $Pattern = "^V{0,1}-{0,1}\d{4,6}$"
	            foreach ($Row in $datagridviewInputForm.Rows) {
	                If ($Row.Cells[0].Value -notin @("", $null)) {
	                    $Data = $Row.Cells[0].Value.ToString().Trim()
	                    If ($Data -notmatch $Pattern) {
	                        $InvalidFound = $true
	                        $ErrMsg += $Data | Out-String
	                    }
	                    Else {
	                        If ($Row.Cells[0].Value -match "\d+") {
	                            $VulnNum = $Matches[0]
	                        }
	                        $script:InputFormResult += "V-$($VulnNum)"
	                    }
	                }
	            }
	        }
	        default {
	            foreach ($Row in $datagridviewInputForm.Rows) {
	                If ($Row.Cells[0].Value -notin @("", $null)) {
	                    $script:InputFormResult += $Row.Cells[0].Value.ToString().Trim()
	                }
	            }
	        }
	    }
	    
	    If ($InvalidFound) {
	        [System.Windows.Forms.MessageBox]::Show($ErrMsg, 'Warning', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning)
	    }
	}
	
