	$formEvaluateSTIG_Load = {
	    $labelCopy.Text = [Char]0x29C9
	    $GUI_Version = "2.6"
	    $script:ESPath = $ScriptDirectory
	
	    # Test STIGList.xml against schema
	    if ((Test-XmlAgainstSchema -XmlFile (Join-Path -Path $script:ESPath -ChildPath xml | Join-Path -ChildPath STIGList.xml) -SchemaInput (Join-Path -Path $script:ESPath -ChildPath xml | Join-Path -ChildPath Schema_STIGList.xsd)) -ne $true) {
	        [System.Windows.Forms.MessageBox]::Show("'STIGList.xml' failed schema validation.  Please update with -Update option.", 'Error', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
	        $formEvaluateSTIG.Close()
	    }
	    else {
	        $script:STIGListXML = [XML](Get-Content (Join-Path -Path $script:ESPath -ChildPath xml | Join-Path -ChildPath STIGList.xml))
	        $script:STIGListObj = [System.Collections.Generic.List[System.Object]]::new()
	        foreach ($Item in ($STIGListXML.List.STIG | Sort-Object ShortName)) {
	            $NewObj = [PSCustomObject]@{
	                Name        = $Item.Name
	                ShortName   = $Item.ShortName
	                StigContent = $Item.StigContent
	                DisaStatus  = $Item.DisaStatus
	                AssetType   = $Item.AssetType
	                Support     = "EvalSTIG"
	            }
	            $script:STIGListObj.Add($NewObj)
	        }
	        
	        # Check for Manual STIGs
	        $ManualSTIGs = [System.Collections.Generic.List[System.Object]]::new()
	        if (Test-Path (Join-Path -Path $script:ESPath -ChildPath StigContent | Join-Path -ChildPath Manual)) {
	            foreach ($Item in ((Get-ChildItem (Join-Path -Path $script:ESPath -ChildPath StigContent | Join-Path -ChildPath Manual) | Where-Object Extension -eq ".xml"))) {
	                [xml]$ManualSTIGContent = Get-Content $Item.FullName
	                $STIGName = $ManualSTIGContent.Benchmark.ID
	                $NewObj = [PSCustomObject]@{
	                    Name        = $(($ManualSTIGContent.Benchmark.title -replace "_", " " -replace "STIG" -replace "Security Technical Implementation Guide").Trim())
	                    Shortname   = "M_" + $(($ManualSTIGContent.Benchmark.ID -replace "_" -replace "STIG").Trim())
	                    StigContent = $Item.Name
	                    DisaStatus  = ""
	                    AssetType   = ""
	                    Support     = "Manual"
	                }
	                $ManualSTIGs.Add($NewObj)
	            }
	        }
	        foreach ($Item in ($ManualSTIGs | Sort-Object ShortName)) {
	            $script:STIGListObj.Add($Item)
	        }
	    }
	    
	    # Test Preferences.xml against schema
	    if ((Test-XmlAgainstSchema -XmlFile (Join-Path -Path $script:ESPath -ChildPath Preferences.xml) -SchemaInput (Join-Path -Path $script:ESPath -ChildPath xml | Join-Path -ChildPath Schema_Preferences.xsd)) -ne $true) {
	        if ([System.Windows.Forms.MessageBox]::Show("'Preferences.xml' failed schema validation.  Will not be imported.", 'Warning', [System.Windows.Forms.MessageBoxButtons]::OKCancel, [System.Windows.Forms.MessageBoxIcon]::Warning) -ne "OK") {
	            $formEvaluateSTIG.Close()
	        }
	    }
	    else {
	        $script:PrefsObj = Convert-PreferencesToObject
	    }
	    
	    # Enable $buttonListApplicableProducts
	    if (Test-IsAdministrator) {
	        $buttonListApplicableProducts.Enabled = $true
	        $checkboxIncludeDeprecated.Enabled = $true
	    }
	    
	    # Get Evaluate-STIG version
	    $script:evalSTIGVersionNumber = ((Get-Content $(Join-Path -Path $script:ESPath -ChildPath Evaluate-STIG.ps1) | Select-String -Pattern ('\$EvaluateStigVersion = ')) -split ("="))[1]
	    $script:evalSTIGReleaseDate = ((Get-Content $(Join-Path -Path $script:ESPath -ChildPath Evaluate-STIG.ps1) | Select-String -Pattern ('\$ReleaseDate = ')) -split ("="))[1]
	    
	    # Initialize bottom banner labels
	    $labelEvaluateSTIGVersion.Text = "Evaluate-STIG Version:  $($script:evalSTIGVersionNumber.Trim() -replace '"')   |   Released:  $($script:evalSTIGReleaseDate.Trim() -replace '"')"
	    $labelGUIState.Text = "Idle"; $labelGUIState.ForeColor = 'White'
	    $labelGUIVersion.Text = "GUI Version: $($GUI_Version)"
	    
	    # Update controls from Preferences.xml
	    Set-ControlsFromPreferences
	    
	    # ==========================================================
	    # Begin Initialize Scan tab
	    # ==========================================================
	    # Set default ThrottleLimit to 10
	    $numericupdownThrottleLimit.Value = 10
		
		# Populate SelectDeviceType
		$comboboxSelectDeviceType.Items.Clear()
		foreach ($Type in @("", "Router", "Switch", "Router,Switch"))
		{
			Update-ComboBox -ComboBox $comboboxSelectDeviceType $Type -Append
		}
	
		# Set additional depenedent parameters
	    Test-OutputTypes
	    
	    # Update $comboboxAnswerKey.Items
	    Update-AnswerKeys
	    
	    # Build initial command line
	    Get-Arguments
	    
	    # ==========================================================
	    # End Initialize Scan tab
	    # ==========================================================
	    
	    
	    # ==========================================================
	    # Begin Initialize Answer File Tools tab
	    # ==========================================================
	    $script:AFReportPath = $([Environment]::GetFolderPath("MyDocuments"))
	
	    # Set background color for $VulnData_AF_RichTextBox - Default is red so that it can be found in the editor
	    $VulnData_AF_RichTextBox.BackColor = [System.Drawing.Color]::FromArgb(255, 235, 235, 235)
	
	    # Set ValidStatus
	    $script:ValidStatus = @("NR", "NF", "O", "NA")
	    
