	    $script:IsModified = $false
	    
	    # Initialize attribute imports
	    $script:AFImportExpectedStatus = $false
	    $script:AFImportInstance = $false
	    $script:AFImportDatabase = $false
	    $script:AFImportSite = $false
	    $script:AFImportResultHash = $false
	    
	    # Create legacy answer file schema
	    $script:LegacyAFSchema = @'
