	function Receive-NormalizedArray {
	    # Function to normalize each item within an array
	    param (
	        [Parameter(Mandatory = $true)]
	        [Array]$Array,
	        [Parameter(Mandatory = $true)]
	        [ValidateSet("Quoted", "Unquoted")]
	        [String]$Action
	    )
	    
	    switch ($Action) {
	        "Quoted" {
	            $NormalizedArray = $Array | ForEach-Object {
	                $s = $_.Trim()
	                
	                # If the item is wrapped in a single or double quote, remove those outer quotes
	                if ($s.Length -ge 2 -and ($s[0] -eq '"' -or $s[0] -eq "'") -and ($s[$s.Length - 1] -eq '"' -or $s[$s.Length - 1] -eq "'")) {
	                    $s = $s.Substring(1, $s.Length - 2)
	                }
	                
	                # Escape any internal double-quotes by doubling them (safe for many command-line consumers)
	                $s = $s -replace '"', '""'
	                
	                # Put one pair of double quotes around the cleaned value
	                if ($s -match "\s") {
	                    '"{0}"' -f $s
	                }
	                else {
	                    '{0}' -f $s
	                }
	            }
	        }
	        "Unquoted" {
	            $NormalizedArray = $Array | ForEach-Object {
	                $s = $_.Trim()
	                
	                if ($s.Length -ge 2) {
	                    $first = $s[0]
	                    $last = $s[$s.Length - 1]
	                    
	                    if ((($first -eq '"') -and ($last -eq '"')) -or (($first -eq "'") -and ($last -eq "'"))) {
	                        # Remove exactly the outermost pair of matching quotes
	                        $s = $s.Substring(1, $s.Length - 2)
	                    }
	                }
	                
	                $s
	            }
	        }
	    }
	    
	    return $NormalizedArray
	}
	
	function Convert-PreferencesToObject {
	    param (
	        [switch]$ResetToDefault
	    )
	    
	    if ($ResetToDefault) {
	        $PrefsXML = [XML](Get-Content (Join-Path -Path $script:ESPath -ChildPath xml | Join-Path -ChildPath Preferences.default.xml))
	    }
	    else {
	        $PrefsXML = [XML](Get-Content (Join-Path -Path $script:ESPath -ChildPath Preferences.xml))
	    }
	    
	    if ($PrefsXML) {
	        $ResultObj = [ordered]@{
	            EvaluateSTIG = [ordered]@{ }
	            OutputPayload = [ordered]@{ }
	            STIGManager  = [ordered]@{ }
	            Splunk       = [ordered]@{ }
	            ManageAnswerFiles = [ordered]@{ }
	        }
	        
	        # Build EvaluateSTIG object
	        foreach ($Item in ($PrefsXML.Preferences.EvaluateSTIG.ChildNodes.Name | Where-Object { $_ -ne "#comment" })) {
	            $ResultObj.EvaluateSTIG.Add($Item, $PrefsXML.Preferences.EvaluateSTIG.$Item)
	        }
	        
	        # Build OutputPayload object
	        foreach ($Item in ($PrefsXML.Preferences.OutputPayload.ChildNodes.Name | Where-Object { $_ -ne "#comment" })) {
	            $ResultObj.OutputPayload.Add($Item, $PrefsXML.Preferences.OutputPayload.$Item)
	        }
	        
	        # Build STIGManager object
	        foreach ($Item in ($PrefsXML.Preferences.STIGManager.ChildNodes.Name | Where-Object { $_ -in @("SMImport_API_BASE", "SMImport_AUTHORITY") -and $_ -ne "#comment" })) {
	            $ResultObj.STIGManager.Add($Item, $PrefsXML.Preferences.STIGManager.$Item)
	        }
	        # Build STIGManager Collection subobjects
	        foreach ($Item in $PrefsXML.Preferences.STIGManager.SMImport_COLLECTION) {
	            $SMCollectionObj = [ordered]@{
	                Name = $Item.Name
	                Data = [ordered]@{ }
	            }
	            foreach ($SubItem in @("SMImport_CLIENT_ID", "SMImport_CLIENT_CERT", "SMImport_CLIENT_CERT_KEY", "SMImport_COLLECTION_ID")) {
	                $SMCollectionObj.Data.Add($SubItem, $Item.$SubItem)
	            }
	            $ResultObj.STIGManager.Add($Item.Name, $SMCollectionObj.Data)
	        }
	        
	        # Build Splunk object
	        foreach ($Item in ($PrefsXML.Preferences.Splunk.ChildNodes.Name | Where-Object { $_ -in @("Splunk_URI") -and $_ -ne "#comment" })) {
	            $ResultObj.Splunk.Add($Item, $PrefsXML.Preferences.Splunk.$Item)
	        }
	        # Build Splunk Collection subobjects
	        foreach ($Item in $PrefsXML.Preferences.Splunk.Splunk_HECName) {
	            $SplunkHECObj = [ordered]@{
	                Name = $Item.Name
	                Data = [ordered]@{ }
	            }
	            foreach ($SubItem in @("Splunk_token", "Splunk_index", "Splunk_source", "Splunk_sourcetype")) {
	                $SplunkHECObj.Data.Add($SubItem, $Item.$SubItem)
	            }
	            $ResultObj.Splunk.Add($Item.Name, $SplunkHECObj.Data)
	        }
	        
	        # Build ManageAnswerFiles object
	        foreach ($Item in ($PrefsXML.Preferences.ManageAnswerFiles.ChildNodes.Name | Where-Object { $_ -ne "#comment" })) {
	            $ResultObj.ManageAnswerFiles.Add($Item, $PrefsXML.Preferences.ManageAnswerFiles.$Item)
	        }
	    }
	    
	    return $ResultObj
	}
	
	function Update-PreferencesObject {
	    param (
	        [Parameter(Mandatory = $true)]
	        [psobject]$Section = "",
	        
	        [Parameter(Mandatory = $true)]
	        [String]$Setting = "",
	        
	        [Parameter(Mandatory = $true)]
	        [psobject]$Value = ""
	    )
	    
	    $script:PrefsObj.$($Section).$($Setting) = $Value
	}
	
	function Set-ControlsFromPreferences {
	    if ($script:PrefsObj) {
	        # ScanType CheckBox and ComboBox
	        if ($script:PrefsObj.EvaluateSTIG.ScanType) {
	            $checkboxScanType.Checked = $true
	            Update-ComboBox -ComboBox $comboboxScanType -Items "Unclassified", "Classified"
	            $comboboxScanType.SelectedItem = $script:PrefsObj.EvaluateSTIG.ScanType
	            if (-Not ($comboboxScanType.SelectedItem)) {
	                $comboboxScanType.SelectedItem = $comboboxScanType.Items[0]
	            }
	        }
	        
	        # VulnTimeout CheckBox and NumericValue
	        if ($script:PrefsObj.EvaluateSTIG.VulnTimeout) {
	            $checkboxVulnTimeout.Checked = $true
	            $numericupdownVulnTimeout.Value = $script:PrefsObj.EvaluateSTIG.VulnTimeout
	        }
	        
	        # FileSearchTimeout CheckBox and NumericValue
	        if ($script:PrefsObj.EvaluateSTIG.FileSearchTimeout) {
	            $checkboxFileSearchTimeout.Checked = $true
	            $numericupdownFileSearchTimeout.Value = $script:PrefsObj.EvaluateSTIG.FileSearchTimeout
	        }
	        
	        # Marking CheckBox and TextBox
	        if ($script:PrefsObj.EvaluateSTIG.Marking) {
	            $checkboxMarking.Checked = $true
	            $textboxMarking.Text = $script:PrefsObj.EvaluateSTIG.Marking
	        }
	        
	        # TargetComments CheckBox and TextBox
	        if ($script:PrefsObj.EvaluateSTIG.TargetComments) {
	            $checkboxTargetComments.Checked = $true
	            $textboxTargetComments.Text = $script:PrefsObj.EvaluateSTIG.TargetComments
	        }
	        
	        # ApplyTattoo CheckBox
	        if ($script:PrefsObj.EvaluateSTIG.ApplyTattoo -eq $true) {
	            $checkboxApplyTattoo.Checked = $true
	        }
	        
	        # AFPath CheckBox and TextBox
	        if ($script:PrefsObj.EvaluateSTIG.AFPath) {
	            $checkboxAFPath.Checked = $true
	            $textboxAFPath.Text = $script:PrefsObj.EvaluateSTIG.AFPath
	        }
	        else {
	            $textboxAFPath.Text = $(Join-Path -Path $script:ESPath -ChildPath AnswerFiles)
	        }
	        
	        # AnswerKey CheckBox and ComboBox
	        Update-ComboBox -ComboBox $comboboxAnswerKey -Items "DEFAULT"
	        $comboboxAnswerKey.SelectedItem = $script:PrefsObj.EvaluateSTIG.AnswerKey
	        if (-Not ($comboboxAnswerKey.SelectedItem)) {
	            $comboboxAnswerKey.SelectedItem = $comboboxAnswerKey.Items[0]
	        }
	        
	        # Output CheckBox and ListBox
	        $DisplayOutputTypes = @()
	        $script:OutputTypes = @("CKL", "CKLB", "CSV", "XCCDF", "ARF", "CombinedCKL", "CombinedCKLB", "CombinedCSV", "OQE", "Summary", "STIGManager", "Splunk")
	        if ($script:PrefsObj.EvaluateSTIG.Output -notin @($null, "")) {
	            foreach ($Item in ($script:PrefsObj.EvaluateSTIG.Output -split ",").Trim()) {
	                if ($Item -in $script:OutputTypes) {
	                    $checkboxOutput.Checked = $true
	                    $DisplayOutputTypes += $Item
	                }
	            }
	            $textboxOutput.Text = $DisplayOutputTypes -join ","
	        }
	        
	        # TruncateOutput CheckBox and NumericValue
	        if ($script:PrefsObj.EvaluateSTIG.TruncateOutput -notin @($null, "")) {
	            $numericupdownTruncateOutput.Value = $script:PrefsObj.EvaluateSTIG.TruncateOutput
	            if ($textboxOutput.Text -notin @($null, "")) {
	                if (($textboxOutput.Text -split ",") -match "(^CKL$|^CKLB$|^CSV$|^XCCDF$|^ARF$|^CombinedCKL$|^CombinedCKLB$|^CombinedCSV$|^STIGManager$|^Splunk$)") {
	                    $checkboxTruncateOutput.Checked = $true
	                }
	            }
	        }
	        
	        # OutputPayload
	        $Payloads = @()
	        foreach ($Key in $script:PrefsObj.OutputPayload.Keys) {
	            $DefaultConfig = $true # All payloads enabled is default
	            if ($script:PrefsObj.OutputPayload.$Key -eq $true) {
	                $Payloads += $Key.Trim()
	            }
	            else {
	                $DefaultConfig = $false
	            }
	            
	            # Check OutputPayloads box if Preferences differ from default
	            if (-Not ($DefaultConfig)) {
	                $checkboxOutputPayload.Checked = $true
	            }
	        }
	        $textboxOutputPayload.Text = $Payloads -join ","
	        
	        # PreviousToKeep CheckBox and NumericValue
	        if ($script:PrefsObj.EvaluateSTIG.PreviousToKeep -notin @($null, "")) {
	            $numericupdownPreviousToKeep.Value = $script:PrefsObj.EvaluateSTIG.PreviousToKeep
	            if ($textboxOutput.Text -notin @($null, "")) {
	                if (($textboxOutput.Text -split ",") -match "(^CKL$|^CKLB$|^CSV$|^XCCDF$|^ARF$|^CombinedCKL$|^CombinedCKLB$|^CombinedCSV$|^OQE$|^Summary$)") {
	                    $checkboxPreviousToKeep.Checked = $true
	                }
	            }
	        }
	        
	        # OutputPath CheckBox and TextBox
	        if ($script:PrefsObj.EvaluateSTIG.OutputPath) {
	            $checkboxOutputPath.Checked = $true
	            $textboxOutputPath.Text = $script:PrefsObj.EvaluateSTIG.OutputPath
	        }
	        else {
	            $textboxOutputPath.Text = $(Join-Path -Path $env:PUBLIC -ChildPath Documents | Join-Path -ChildPath STIG_Compliance)
	        }
	        
	        # SMCollection CheckBox and ComboBox
	        $comboboxSMCollection.Items.Clear()
	        Update-ComboBox -ComboBox $comboboxSMCollection -Items ""
	        foreach ($Item in $script:PrefsObj.STIGManager.Keys | Where-Object { $_ -notin @("SMImport_API_BASE", "SMImport_AUTHORITY") }) {
	            if ($Item -notin @($null, "")) {
	                Update-ComboBox -ComboBox $comboboxSMCollection -Items $Item -Append
	            }
	        }
	        if ($script:PrefsObj.EvaluateSTIG.SMCollection -notin @($null, "") -and $script:PrefsObj.EvaluateSTIG.SMCollection -in $comboboxSMCollection.Items) {
	            $checkboxSMCollection.Checked = $true
	            $comboboxSMCollection.SelectedItem = $script:PrefsObj.EvaluateSTIG.SMCollection
	        }
	        else {
	            $comboboxSMCollection.SelectedItem = $comboboxSMCollection.Items[0]
	        }
	        
	        # SplunkHECName CheckBox and ComboBox
	        $comboboxSplunkHECName.Items.Clear()
	        Update-ComboBox -ComboBox $comboboxSplunkHECName -Items ""
	        foreach ($Item in $script:PrefsObj.Splunk.Keys | Where-Object { $_ -notin @("Splunk_URI") }) {
	            if ($Item -notin @($null, "")) {
	                Update-ComboBox -ComboBox $comboboxSplunkHECName -Items $Item -Append
	            }
	        }
	        if ($script:PrefsObj.EvaluateSTIG.SplunkHECName -notin @($null, "") -and $script:PrefsObj.EvaluateSTIG.SplunkHECName -in $comboboxSplunkHECName.Items) {
	            $checkboxSplunkHECName.Checked = $true
	            $comboboxSplunkHECName.SelectedItem = $script:PrefsObj.EvaluateSTIG.SplunkHECName
	        }
	        else {
	            $comboboxSplunkHECName.SelectedItem = $comboboxSplunkHECName.Items[0]
	        }
	        
	        # AllowDeprecated CheckBox and STIG ShortName list
	        if ($script:PrefsObj.EvaluateSTIG.AllowDeprecated -eq $true) {
	            $checkboxAllowDeprecated.Checked = $true
	        }
	        
	        # ExcludeVuln TextBox
	        if ($script:PrefsObj.EvaluateSTIG.ExcludeVuln) {
	            $checkboxExcludeVuln.Checked = $true
	            $PrefsExcludeVuln = ($script:PrefsObj.EvaluateSTIG.ExcludeVuln -split ",").Trim() | Where-Object { $_ -notin @($null, "") }
	            $textboxExcludeVuln.Text = ($PrefsExcludeVuln | Select-Object -Unique | Sort-Object) -join ","
	        }
	        
	        # ExcludeSTIG CheckBox and ListBox
	        if ($script:PrefsObj.EvaluateSTIG.ExcludeSTIG -notin @($null, "")) {
	            $DisplayExcludeSTIGs = @()
	            foreach ($Item in ($script:PrefsObj.EvaluateSTIG.ExcludeSTIG -split ",").Trim()) {
	                if ($Item -notin ($script:STIGListObj | Where-Object AssetType -eq "Cisco").ShortName -and ($Item -in ($script:STIGListObj | Where-Object DisaStatus -ne "Deprecated").ShortName -or ($Item -in ($script:STIGListObj | Where-Object DisaStatus -eq "Deprecated").ShortName -and $checkboxAllowDeprecated.Checked))) {
	                    $DisplayExcludeSTIGs += $Item
	                }
	            }
	            $textboxExcludeSTIG.Text = ($DisplayExcludeSTIGs | Sort-Object) -join ","
	        }
	        if ($textboxExcludeSTIG.Text -notin @($null, "")) {
	            $checkboxExcludeSTIG.Checked = $true
	            Set-ParamControlState -ParamControl ExcludeSTIG -Enabled $true
	        }
	        
	        # AllowSeverityOverride CheckBox
	        if ($script:PrefsObj.EvaluateSTIG.AllowSeverityOverride -eq $true) {
	            $checkboxAllowSeverityOverride.Checked = $true
	        }
	        
	        # Set $ESResultsPath
	        if ($script:PrefsObj.ManageAnswerFiles.EvaluateSTIG_Results -notin @($null, "") -and (Test-Path ($script:PrefsObj.ManageAnswerFiles.EvaluateSTIG_Results -replace '(^"|"$)'))) {
	            $script:ESResultsPath = $script:PrefsObj.ManageAnswerFiles.EvaluateSTIG_Results -replace '(^"|"$)'
	        }
	        elseif (Test-Path "$env:PUBLIC\Documents\STIG_Compliance") {
	            $script:ESResultsPath = "$env:PUBLIC\Documents\STIG_Compliance"
	        }
	        else {
	            $script:ESResultsPath = [System.Environment]::GetFolderPath([System.Environment+SpecialFolder]::Desktop)
	        }
	        
	        # Set AFPath
	        if ($script:PrefsObj.ManageAnswerFiles.AnswerFileDirectory -notin @($null, "") -and (Test-Path ($script:PrefsObj.ManageAnswerFiles.AnswerFileDirectory -replace '(^"|"$)'))) {
	            $textboxAF_AFPath.Text = $script:PrefsObj.ManageAnswerFiles.AnswerFileDirectory -replace '(^"|"$)'
	        }
	        else {
	            # Pull AFPath from Scan tab
	            $textboxAF_AFPath.Text = $textboxAFPath.Text
	        }
	        
	        # Set Status format list and select format configured in preferences
	        foreach ($Status in @("EvalSTIG", "CKL", "CKLB", "XCCDF")) {
	            Update-ComboBox -ComboBox $comboboxAF_FormatStatus -Items $Status -Append
	        }
	        $comboboxAF_FormatStatus.SelectedItem = $script:PrefsObj.ManageAnswerFiles.StatusFormat
	        if ($comboboxAF_FormatStatus.SelectedItem -in @($null, "")) {
	            # Invalid entry in preferences - default to EvalSTIG
	            $comboboxAF_FormatStatus.SelectedItem = "EvalSTIG"
	        }
	        
	        # Set $DefaultAFKey
	        if ($script:PrefsObj.ManageAnswerFiles.DefaultAFKey -notin @($null, "")) {
	            $textboxAF_DefaultAFKey.Text = ($script:PrefsObj.ManageAnswerFiles.DefaultAFKey).Trim()
	        }
	        else {
	            $textboxAF_DefaultAFKey.Text = "DEFAULT"
	        }
	        $script:DefaultAFKey = $textboxAF_DefaultAFKey.Text
	        
	        # Set BackupOnSave
	        if ($script:PrefsObj.ManageAnswerFiles.BackupOnSave -eq $true) {
	            $comboboxAF_BackupOnSave.SelectedItem = "True"
	        }
	        else {
	            $comboboxAF_BackupOnSave.SelectedItem = "False"
	        }
	        
	        # Set $IDEPath
	        if ($script:PrefsObj.ManageAnswerFiles.PowerShell_IDE -notin @($null, "") -and (Test-Path ($script:PrefsObj.ManageAnswerFiles.PowerShell_IDE -replace '(^"|"$)'))) {
	            $script:IDEPath = $script:PrefsObj.ManageAnswerFiles.PowerShell_IDE -replace '(^"|"$)'
	        }
	        else {
	            $script:IDEPath = "$env:windir\system32\WindowsPowerShell\v1.0\PowerShell_ISE.exe"
	        }
	    }
	}
	
	function Test-PrefsModified {
	    if ($script:PrefsModified) {
	        $labelPref_SavedTrueFalse.Text = "True"; $labelPref_SavedTrueFalse.ForeColor = 'Yellow'
	        $buttonPref_Save.Enabled = $true; $buttonPref_Save.BackColor = 'LightGreen'
	        $buttonPref_Discard.Enabled = $true; $buttonPref_Discard.BackColor = 'LightPink'
	    }
	    else {
	        $labelPref_SavedTrueFalse.Text = "False"; $labelPref_SavedTrueFalse.ForeColor = 'White'
	        $buttonPref_Save.Enabled = $false; $buttonPref_Save.BackColor = 'Transparent'
	        $buttonPref_Discard.Enabled = $false; $buttonPref_Discard.BackColor = 'Transparent'
	    }
	}
	
	Function Test-IsAdministrator {
		[CmdletBinding()]
		Param ()
		
		$identity = [System.Security.Principal.WindowsIdentity]::GetCurrent()
		$principal = [System.Security.Principal.WindowsPrincipal]::new($identity)
		return $principal.IsInRole([System.Security.Principal.WindowsBuiltInRole]::Administrator)
	}
	
	function Invoke-FolderBrowser {
	    param (
	        [Parameter(Mandatory = $false)]
	        [String]$Description = "Select a folder:",
	        
	        [Parameter(Mandatory = $false)]
	        [String]$SelectedPath = $ScriptDirectory
	    )
	    
	    $FolderBrowserDialog = New-Object System.Windows.Forms.FolderBrowserDialog
	    $FolderBrowserDialog.Description = $Description
	    $FolderBrowserDialog.SelectedPath = $SelectedPath
	    $FolderBrowserDialog.ShowNewFolderButton = $false
	    
	    if ($FolderBrowserDialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
	        return $FolderBrowserDialog.SelectedPath
	    }
	}
	
	function Invoke-FileBrowser {
	    param (
	        [Parameter(Mandatory = $false)]
	        [ValidateSet("Open", "Save")]
	        [String]$Action = "Open",
	        
	        [Parameter(Mandatory = $false)]
	        [String]$Title = "Select file:",
	        
	        [Parameter(Mandatory = $false)]
	        [String]$InitialDirectory = $ScriptDirectory,
	        
	        [Parameter(Mandatory = $false)]
	        [Switch]$AllowMultiSelect,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$Filter = "Text files (*.txt)|*.txt",
	        
	        [Parameter(Mandatory = $false)]
	        [String]$FileName
	    )
	    
	    switch ($Action) {
	        "Open" {
	            $OpenFileDialog = New-Object System.Windows.Forms.OpenFileDialog
	            $OpenFileDialog.Filter = $Filter
	            if ($AllowMultiSelect) {
	                $OpenFileDialog.Multiselect = $true
	            }
	            else {
	                $OpenFileDialog.Multiselect = $false
	            }
	            $OpenFileDialog.InitialDirectory = $InitialDirectory
	            $OpenFileDialog.Title = $Title
	            
	            if ($OpenFileDialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
	                return $OpenFileDialog.FileNames
	            }
	        }
	        "Save" {
	            $SaveFileDialog = New-Object System.Windows.Forms.SaveFileDialog
	            $SaveFileDialog.Filter = $Filter
	            $SaveFileDialog.FileName = $FileName
	            $SaveFileDialog.InitialDirectory = $InitialDirectory
	            $SaveFileDialog.Title = $Title
	            
	            if ($SaveFileDialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
	                return $SaveFileDialog.FileNames
	            }
	        }
	    }
	}
	
	function Set-ParamControlState {
	    param (
	        [Parameter(Mandatory = $true)]
	        [ValidateSet("ScanType", "VulnTimeout", "FileSearchTimeout", "Marking", "TargetComments", "ApplyTattoo", "AFPath", "AnswerKey", "Output", "TruncateOutput", "OutputPayload", "PreviousToKeep", "OutputPath", "SMCollection", "SMPassphrase", "SplunkHECName", "SelectSTIG", "SelectVuln", "ExcludeVuln", "ExcludeSTIG", "ForceSTIG", "SelectInstance", "ExcludeInstance", "SelectDatabase", "ExcludeDatabase", "SelectSite", "ExcludeSite", "RemoteDevice", "ThrottleLimit", "SelectDeviceType", "LocalSource", "Proxy", "Update")]
	        [String]$ParamControl,
	        
	        [boolean]$Enabled
	    )
	    
	    # List of parameters and their control objects
	    $ControlList = @{
	        ScanType          = @($comboboxScanType)
	        VulnTimeout       = @($numericupdownVulnTimeout)
	        FileSearchTimeout = @($numericupdownFileSearchTimeout)
	        Marking           = @($textboxMarking)
	        TargetComments    = @($textboxTargetComments)
	        ApplyTattoo       = @($checkboxApplyTattoo)
	        AFPath            = @($textboxAFPath, $buttonAFPathBrowse)
	        AnswerKey         = @($comboboxAnswerKey)
	        Output            = @($textboxOutput, $buttonOutputEdit)
	        TruncateOutput    = @($numericupdownTruncateOutput)
	        OutputPayload     = @($textboxOutputPayload, $buttonOutputPayloadEdit)
	        PreviousToKeep    = @($numericupdownPreviousToKeep)
	        OutputPath        = @($textboxOutputPath, $buttonOutputPathBrowse)
	        SMCollection      = @($comboboxSMCollection)
	        SMPassphrase      = @($textboxSMPassphrase)
	        SplunkHECName     = @($comboboxSplunkHECName)
	        SelectSTIG        = @($textboxSelectSTIG, $buttonSelectEdit)
	        SelectVuln        = @($textboxSelectVuln, $buttonSelectVulnEdit)
	        ExcludeVuln       = @($textboxExcludeVuln, $buttonExcludeVulnEdit)
	        ExcludeSTIG       = @($textboxExcludeSTIG, $buttonExcludeSTIGEdit)
	        ForceSTIG         = @($textboxForceSTIG, $buttonForceSTIGEdit)
	        SelectInstance    = @($textboxSelectInstance, $buttonSelectInstanceEdit)
	        ExcludeInstance   = @($textboxExcludeInstance, $buttonExcludeInstanceEdit)
	        SelectDatabase    = @($textboxSelectDatabase, $buttonSelectDatabaseEdit)
	        ExcludeDatabase   = @($textboxExcludeDatabase, $buttonExcludeDatabaseEdit)
	        SelectSite        = @($textboxSelectSite, $buttonSelectSiteEdit)
	        ExcludeSite       = @($textboxExcludeSite, $buttonExcludeSiteEdit)
	        RemoteDevice      = @($radiobuttonComputerName, $radiobuttonCiscoConfig, $listboxRemote)
			ThrottleLimit	  = @($numericupdownThrottleLimit)
			SelectDeviceType  = @($comboboxSelectDeviceType)
	        LocalSource       = @($textboxLocalSource)
	        Proxy             = @($textboxProxy)
	        update            = @($buttonUpdate)
	    }
	    
	    # Set the state of the parameter's control objects
	    foreach ($Item in $ControlList.$ParamControl) {
	        $Item.Enabled = $Enabled
	    }
	}
	
	function Test-OutputTypes {
	    # Enable depenedent parameters based on selected Output items
	    
	    # OutputPayload
	    if ($checkboxOutput.Checked -and ($textboxOutput.Text -split ",") -match "(^CSV$|^CombinedCSV$|^Splunk$)") {
	        $checkboxOutputPayload.Enabled = $true
	        if ($checkboxOutputPayload.Checked) {
	            Set-ParamControlState -ParamControl OutputPayload -Enabled $true
	        }
	    }
	    else {
	        $checkboxOutputPayload.Enabled = $false
	        Set-ParamControlState -ParamControl OutputPayload -Enabled $false
	    }
	    
	    # TruncateOutput
	    if ($checkboxOutput.Checked -and ($textboxOutput.Text -split ",") -match "(^CKL$|^CKLB$|^CSV$|^XCCDF$|^ARF$|^CombinedCKL$|^CombinedCKLB$|^CombinedCSV$|^STIGManager$|^Splunk$)") {
	        $checkboxTruncateOutput.Enabled = $true
	        
	        # Set TruncateOutput state
	        if ($checkboxTruncateOutput.Checked) {
	            Set-ParamControlState -ParamControl TruncateOutput -Enabled $true
	        }
	    }
	    else {
	        $checkboxTruncateOutput.Enabled = $false
	        Set-ParamControlState -ParamControl TruncateOutput -Enabled $false
	    }
	    
	    # PreviousToKeep and OutputPath
	    if ($checkboxOutput.Checked -and ($textboxOutput.Text -split ",") -match "(^CKL$|^CKLB$|^CSV$|^XCCDF$|^ARF$|^CombinedCKL$|^CombinedCKLB$|^CombinedCSV$|^Summary$|^OQE$)") {
	        $checkboxPreviousToKeep.Enabled = $true
	        $checkboxOutputPath.Enabled = $true
	        
	        # Set PreviousToKeep state
	        if ($checkboxPreviousToKeep.Checked) {
	            Set-ParamControlState -ParamControl PreviousToKeep -Enabled $true
	        }
	        
	        # Set OutputPath state
	        if ($checkboxOutputPath.Checked) {
	            Set-ParamControlState -ParamControl OutputPath -Enabled $true
	        }
	    }
	    else {
	        $checkboxPreviousToKeep.Enabled = $false
	        Set-ParamControlState -ParamControl PreviousToKeep -Enabled $false
	        
	        $checkboxOutputPath.Enabled = $false
	        Set-ParamControlState -ParamControl OutputPath -Enabled $false
	    }
	    
	    # SMCollection and SMPassphrase
	    if ($checkboxOutput.Checked -and ($textboxOutput.Text -split ",") -match "(^STIGManager$)") {
	        $checkboxSMCollection.Enabled = $true
	        if ($checkboxSMCollection.Checked) {
	            Set-ParamControlState -ParamControl SMCollection -Enabled $true
	        }
	        
	        if ($comboboxSMCollection.SelectedItem -notin @($null, "")) {
	            $checkboxSMPassphrase.Enabled = $true
	            if ($checkboxSMPassphrase.Checked) {
	                Set-ParamControlState -ParamControl SMPassphrase -Enabled $true
	            }
	        }
	        else {
	            $checkboxSMPassphrase.Enabled = $false
	            Set-ParamControlState -ParamControl SMPassphrase -Enabled $false
	        }
	    }
	    else {
	        $checkboxSMCollection.Enabled = $false
	        Set-ParamControlState -ParamControl SMCollection -Enabled $false
	        
	        $checkboxSMPassphrase.Checked = $false
	        $checkboxSMPassphrase.Enabled = $false
	        Set-ParamControlState -ParamControl SMPassphrase -Enabled $false
	    }
	    
	    # SplunkHECName
	    if ($checkboxOutput.Checked -and ($textboxOutput.Text -split ",") -match "(^Splunk$)") {
	        $checkboxSplunkHECName.Enabled = $true
	        if ($checkboxSplunkHECName.Checked) {
	            Set-ParamControlState -ParamControl SplunkHECName -Enabled $true
	        }
	    }
	    else {
	        $checkboxSplunkHECName.Enabled = $false
	        Set-ParamControlState -ParamControl SplunkHECName -Enabled $false
	    }
	}
	
	function Test-XmlAgainstSchema {
	    # Validate XML against a schema file or a multiline schema string
	    param (
	        [Parameter(Mandatory = $true)]
	        [String]$XmlFile,
	        
	        [Parameter(Mandatory = $true)]
	        [String]$SchemaInput,
	        
	        # Can be a file path or a multiline string
	        
	        [Parameter(Mandatory = $false)]
	        [Switch]$IsSchemaString # Set if $SchemaInput is a string, not a file
	    )
	    
	    Try {
	        Get-ChildItem $XmlFile -ErrorAction Stop | Out-Null
	        
	        $XmlErrors = New-Object System.Collections.Generic.List[System.Object]
	        [Scriptblock]$ValidationEventHandler = {
	            if ($_.Exception.LineNumber) {
	                $Message = "$($_.Exception.Message) Line $($_.Exception.LineNumber), position $($_.Exception.LinePosition)."
	            }
	            else {
	                $Message = ($_.Exception.Message)
	            }
	            
	            $NewObj = [PSCustomObject]@{
	                Message = $Message
	            }
	            $XmlErrors.Add($NewObj)
	        }
	        
	        $ReaderSettings = New-Object -TypeName System.Xml.XmlReaderSettings
	        $ReaderSettings.ValidationType = [System.Xml.ValidationType]::Schema
	        $ReaderSettings.ValidationFlags = [System.Xml.Schema.XmlSchemaValidationFlags]::ProcessIdentityConstraints -bor [System.Xml.Schema.XmlSchemaValidationFlags]::ProcessSchemaLocation -bor [System.Xml.Schema.XmlSchemaValidationFlags]::ReportValidationWarnings
	        
	        if ($IsSchemaString) {
	            $schemaReader = [System.IO.StringReader]::new($SchemaInput)
	            $xmlSchema = [System.Xml.Schema.XmlSchema]::Read($schemaReader, $null)
	            $schemaSet = New-Object System.Xml.Schema.XmlSchemaSet
	            $schemaSet.Add($xmlSchema) | Out-Null
	            $ReaderSettings.Schemas.Add($schemaSet) | Out-Null
	        }
	        else {
	            Get-ChildItem $SchemaInput -ErrorAction Stop | Out-Null
	            if ((Split-Path $SchemaInput -Leaf) -eq "xccdf_1.2.xsd") {
	                $ReaderSettings.Schemas.Add("http://checklists.nist.gov/xccdf/1.2", $SchemaInput) | Out-Null
	            }
	            else {
	                $ReaderSettings.Schemas.Add($null, $SchemaInput) | Out-Null
	            }
	        }
	        $ReaderSettings.add_ValidationEventHandler($ValidationEventHandler)
	        
	        Try {
	            $Reader = [System.Xml.XmlReader]::Create($XmlFile, $ReaderSettings)
	            While ($Reader.Read()) {
	            }
	        }
	        Catch {
	            $NewObj = [PSCustomObject]@{
	                Message = ($_.Exception.Message)
	            }
	            $XmlErrors.Add($NewObj)
	        }
	        Finally {
	            if ($Reader) { $Reader.Close() }
	        }
	        
	        if ($XmlErrors) {
	            return $XmlErrors
	        }
	        else {
	            return $true
	        }
	    }
	    Catch {
	        return $_.Exception.Message
	    }
	}
	
	function Update-AnswerKeys {
	    # Clear current items and initialize with a blank item
	    $comboboxAnswerKey.Items.Clear()
	    Update-ComboBox -ComboBox $comboboxAnswerKey -Items ""
	    
	    # Add additional valid items from AFPath
	    if ($textboxAFPath.Text -notin @($null, "")) {
	        $XmlFiles = Get-ChildItem -Path $textboxAFPath.Text -Filter "*.xml"
	        $ValidFiles = @()
	        foreach ($File in $XmlFiles) {
	            if ((Test-XmlAgainstSchema -XmlFile $File.FullName -SchemaInput (Join-Path -Path $script:ESPath -ChildPath xml | Join-Path -ChildPath Schema_AnswerFile.xsd)) -eq $true) {
	                $ValidFiles += $File.FullName
	            }
	        }
	        
	        if (($ValidFiles | Measure-Object).Count -gt 0) {
	            foreach ($File in $ValidFiles) {
	                $XmlContent = [XML](Get-Content -Path $File)
	                if (($XmlContent.STIGComments.Name -in @($script:STIGListObj.Name) -or ($XmlContent.STIGComments.Name -in @($script:STIGListObj.ShortName)))) {
	                    foreach ($Item in ($XmlContent.STIGComments.Vuln.AnswerKey.Name | Select-Object -Unique | Sort-Object)) {
	                        if ($Item -notin @($comboboxAnswerKey.Items)) {
	                            Update-ComboBox -ComboBox $comboboxAnswerKey -Items $Item -Append
	                        }
	                    }
	                }                
	            }
	        }
	        $comboboxAnswerKey.Sorted = $true
	        
	        if ($script:PrefsObj.EvaluateSTIG.AnswerKey -in @($comboboxAnswerKey.Items)) {
	            $comboboxAnswerKey.SelectedItem = $script:PrefsObj.EvaluateSTIG.AnswerKey
	            if ($script:PrefsObj.EvaluateSTIG.AnswerKey -notin @($null, "", "DEFAULT")) {
	                $checkboxAnswerKey.Checked = $true
	            }
	        }
	        elseif ("DEFAULT" -in @($comboboxAnswerKey.Items)) {
	            $comboboxAnswerKey.SelectedItem = "DEFAULT"
	        }
	        else {
	            $comboboxAnswerKey.SelectedItem = $comboboxAnswerKey.Items[0]
	        }
	    }
	}
	
	function Get-Arguments {
	    # Initialize hashtable of arguments for splatting
	    $Arguments = [ordered]@{ }
	    
	    # -ComputerName and -CiscoConfig
	    if ($checkboxPerformRemoteScan.Enabled -and $checkboxPerformRemoteScan.Checked -and ($radiobuttonComputerName.Checked -or $radiobuttonCiscoConfig.Checked) -and $listboxRemote.SelectedItems -notin @($null, "")) {
	        if ($radiobuttonComputerName.Checked) {
	            $Arguments.Add("ComputerName", $($listboxRemote.SelectedItems -join ','))
	            $CommandLine += " -ComputerName $($listboxRemote.SelectedItems -join ',')"
	        }
	        elseif ($radiobuttonCiscoConfig.Checked) {
	            $Arguments.Add("CiscoConfig", $($listboxRemote.SelectedItems -join ','))
	            
	            $arrCiscoConfig = @()
	            foreach ($Item in $listboxRemote.SelectedItems) {
	                if ($Item -match "\s") {
	                    if ($Item -match "^['`"].{0,}['`"]$") {
	                        $arrCiscoConfig += $Item
	                    }
	                    else {
	                        $arrCiscoConfig += '"' + $Item + '"'
	                    }
	                }
	                else {
	                    $arrCiscoConfig += $Item
	                }
	            }
	            
	            $CommandLine += " -CiscoConfig $($arrCiscoConfig -join ',')"
	        }
	    }
	    
	    # -AltCredential
	    if ($checkboxAltCredential.Enabled -and $checkboxAltCredential.Checked) {
	        $Arguments.Add("AltCredential", $true)
	        $CommandLine += " -AltCredential"
	    }
	    
	    # -ThrottleLimit
	    if ($checkboxThrottleLimit.Enabled -and $checkboxThrottleLimit.Checked) {
	        $Arguments.Add("ThrottleLimit", $($numericupdownThrottleLimit.Value))
	        $CommandLine += " -ThrottleLimit $($numericupdownThrottleLimit.Value)"
	    }
	    
	    # -SelectDeviceType
	    if ($checkboxSelectDeviceType.Enabled -and $checkboxSelectDeviceType.Checked -and $comboboxSelectDeviceType.SelectedItem -notin @($null, "")) {
	        $Arguments.Add("SelectDeviceType", $($comboboxSelectDeviceType.SelectedItem))
