	    if ($checkboxSelectVuln.Enabled -and $checkboxSelectVuln.Checked -and $textboxSelectVuln.Text -notin @($null, "")) {
	        $Arguments.Add("SelectVuln", $($textboxSelectVuln.Text))
	        $CommandLine += " -SelectVuln $($textboxSelectVuln.Text)"
	    }
	    
	    # -ExcludeVuln
	    if ($checkboxExcludeVuln.Enabled -and $checkboxExcludeVuln.Checked -and $textboxExcludeVuln.Text -notin @($null, "")) {
	        $Arguments.Add("ExcludeVuln", $($textboxExcludeVuln.Text))
	        $CommandLine += " -ExcludeVuln $($textboxExcludeVuln.Text)"
	    }
	    
	    # -ExcludeSTIG
	    if ($checkboxExcludeSTIG.Enabled -and $checkboxExcludeSTIG.Checked -and $textboxExcludeSTIG.Text -notin @($null, "")) {
	        $Arguments.Add("ExcludeSTIG", $textboxExcludeSTIG.Text)
	        $CommandLine += " -ExcludeSTIG $($textboxExcludeSTIG.Text)"
	    }
	    
	    # -ForceSTIG
	    if ($checkboxForceSTIG.Enabled -and $checkboxForceSTIG.Checked -and $textboxForceSTIG.Text -notin @($null, "")) {
	        $Arguments.Add("ForceSTIG", $textboxForceSTIG.Text)
	        $CommandLine += " -ForceSTIG $($textboxForceSTIG.Text)"
	    }
	    
	    # -SelectInstance
	    if ($checkboxSelectInstance.Enabled -and $checkboxSelectInstance.Checked -and $textboxSelectInstance.Text -notin @($null, "")) {
	        $Arguments.Add("SelectInstance", $($textboxSelectInstance.Text))
	        $CommandLine += " -SelectInstance $($textboxSelectInstance.Text)"
	    }
	    
	    # -ExcludeInstance
	    if ($checkboxExcludeInstance.Enabled -and $checkboxExcludeInstance.Checked -and $textboxExcludeInstance.Text -notin @($null, "")) {
	        $Arguments.Add("ExcludeInstance", $($textboxExcludeInstance.Text))
	        $CommandLine += " -ExcludeInstance $($textboxExcludeInstance.Text)"
	    }
	    
	    # -SelectDatabase
	    if ($checkboxSelectDatabase.Enabled -and $checkboxSelectDatabase.Checked -and $textboxSelectDatabase.Text -notin @($null, "")) {
	        $Arguments.Add("SelectDatabase", $($textboxSelectDatabase.Text))
	        $CommandLine += " -SelectDatabase $($textboxSelectDatabase.Text)"
	    }
	    
	    # -ExcludeDatabase
	    if ($checkboxExcludeDatabase.Enabled -and $checkboxExcludeDatabase.Checked -and $textboxExcludeDatabase.Text -notin @($null, "")) {
	        $Arguments.Add("ExcludeDatabase", $($textboxExcludeDatabase.Text))
	        $CommandLine += " -ExcludeDatabase $($textboxExcludeDatabase.Text)"
	    }
	    
	    # -SelectSite
	    if ($checkboxSelectSite.Enabled -and $checkboxSelectSite.Checked -and $textboxSelectSite.Text -notin @($null, "")) {
	        $Arguments.Add("SelectSite", $($textboxSelectSite.Text))
	        $CommandLine += " -SelectSite $($textboxSelectSite.Text)"
	    }
	    
	    # -ExcludeSite
	    if ($checkboxExcludeSite.Enabled -and $checkboxExcludeSite.Checked -and $textboxExcludeSite.Text -notin @($null, "")) {
	        $Arguments.Add("ExcludeSite", $($textboxExcludeSite.Text))
	        $CommandLine += " -ExcludeSite $($textboxExcludeSite.Text)"
	    }
	    
	    # -AllowSeverityOverride
	    if ($checkboxAllowSeverityOverride.Enabled -and $checkboxAllowSeverityOverride.Checked) {
	        $Arguments.Add("AllowSeverityOverride", $true)
	        $CommandLine += " -AllowSeverityOverride"
	    }
	    
	    # -AllowIntegrityViolations
	    if ($checkboxAllowIntegrityViolations.Enabled -and $checkboxAllowIntegrityViolations.Checked) {
	        $Arguments.Add("AllowIntegrityViolations", $true)
	        $CommandLine += " -AllowIntegrityViolations"
	    }
	    
		# Update command line
	    $richtextboxCommandLine.Text = '& "' + (Join-Path -Path $script:ESPath -ChildPath Evaluate-STIG.ps1) + '"' + $Commandline
	    
	    return $Arguments
	}
	
	function Convert-AnswerFileToObject {
	    param (
	        [Parameter(Mandatory = $true)]
	        [String]$XmlFile,
	        
	        [Parameter(Mandatory = $false)]
	        [Switch]$IsLegacy,
	        
	        [Parameter(Mandatory = $true)]
	        [String]$StatusFormat
	    )
	    
	    [XML]$XMLContent = (Get-Content $XmlFile -Raw)
	    
	    $Result = [ordered]@{ }
	    foreach ($Node in $XMLContent.SelectNodes("//STIGComments")) {
	        # STIGComment Name attribute
	        $Result.Add($Node.Name, [ordered]@{ '_Comment' = ($Node.'#Comment' | Out-String).Trim() })
	        foreach ($Vuln in $Node.Vuln) {
	            $VulnObj = [ordered]@{
	                # Comment if it exists
	                _Comment = ($Vuln.'#comment' | Out-String).Trim()
	            }
	            foreach ($KeyName in ($Node.Vuln | Where-Object { $_ -eq $Vuln }).AnswerKey) {
	                $KeyNameObj = [ordered]@{
	                    # Comment if it exists
	                    _Comment = ($KeyName.'#comment' | Out-String).Trim()
	                }
	                if ($IsLegacy) {
	                    # Collect data from legacy answer file format
	                    $KeyNameObj.Add("ExpectedStatus", (Convert-Status -InputObject $KeyName.ExpectedStatus -Output $StatusFormat))
	                    
	                    # Format ValidationCode
	                    $KeyNameObj.Add("ValidationCode", $KeyName.ValidationCode.Trim())
	                    
	                    # Format ValidTrueStatus
	                    if ($KeyName.ValidTrueStatus -notin @($null, "")) {
	                        $KeyNameObj.Add("ValidTrueStatus", (Convert-Status -InputObject $KeyName.ValidTrueStatus -Output $StatusFormat))
	                    }
	                    else {
	                        $KeyNameObj.Add("ValidTrueStatus", "")
	                    }
	                    
	                    # Format ValidFalseStatus
	                    $KeyNameObj.Add("ValidTrueComment", $KeyName.ValidTrueComment)
	                    if ($KeyName.ValidFalseStatus -notin @($null, "")) {
	                        $KeyNameObj.Add("ValidFalseStatus", (Convert-Status -InputObject $KeyName.ValidFalseStatus -Output $StatusFormat))
	                    }
	                    else {
	                        $KeyNameObj.Add("ValidFalseStatus", "")
	                    }
	                    $KeyNameObj.Add("ValidFalseComment", $KeyName.ValidFalseComment)
	                }
	                else {
	                    foreach ($Index in $KeyName.Answer.Index) {
	                        foreach ($Item in ($KeyName.Answer | Where-Object Index -eq $Index)) {                          
	                            # Format ValidTrueStatus element
	                            if ($Item.ValidTrueStatus -notin @($null, "")) {
	                                $ObjValidTrueStatus = Convert-Status -InputObject $Item.ValidTrueStatus -Output $StatusFormat
	                            }
	                            else {
	                                $ObjValidTrueStatus = ""
	                            }
	                            
	                            # Format ValidFalseStatus element
	                            if ($Item.ValidFalseStatus -notin @($null, "")) {
	                                $ObjValidFalseStatus = Convert-Status -InputObject $Item.ValidFalseStatus -Output $StatusFormat
	                            }
	                            else {
	                                $ObjValidFalseStatus = ""
	                            }
	                            
	                            $IndexObj = [ordered]@{
	                                _Comment = ($Item.'#comment' | Out-String).Trim() # Comment if it exists
	                                ExpectedStatus = (Convert-Status -InputObject $Item.ExpectedStatus -Output $StatusFormat) # ExpectedStatus attribute
	                                Hostname = (($Item.Hostname -split ",").Trim() -join ",") # Hostname attribute
	                                Instance = (($Item.Instance -split ",").Trim() -join ",") # Instance attribute
	                                Database = (($Item.Database -split ",").Trim() -join ",") # Database attribute
	                                Site     = (($Item.Site -split ",").Trim() -join ",") # Site attribute
	                                ResultHash = (($Item.ResultHash -split ",").Trim() -join ",")
	                                ValidationCode = $Item.ValidationCode.Trim() # ValidationCode element
	                                ValidTrueStatus = $ObjValidTrueStatus # Formatted ValidTrueStatus element
	                                ValidTrueComment = $Item.ValidTrueComment # ValidTrueComment element
	                                ValidFalseStatus = $ObjValidFalseStatus # Formatted ValidFalseStatus element
	                                ValidFalseComment = $Item.ValidFalseComment # ValidFalseComment element
	                            }
	                        }
	                        $KeyNameObj.Add($Index, $IndexObj) # Create Index subobject for Answer element
	                    }
	                }
	                $VulnObj.Add($KeyName.Name, $KeyNameObj) # Create Name subobject for AnsweKey element
	            }
	            $Result.($Node.Name).Add($Vuln.ID, $VulnObj) # Create ID subobject for Vuln element
	        }
	    }
	    
	    return $Result
	}
	
	function Convert-ChecklistToHashTable {
	    param
	    (
	        [Parameter(Mandatory = $true)]
	        [psobject]$InputObject,
	        
	        [Parameter(Mandatory = $true)]
	        [ValidateSet("CKL", "CKLB")]
	        [String]$InputType
	    )
	    
	    $Output = [ordered]@{ }
	    
	    switch ($InputType) {
	        "CKL" {
	            foreach ($iSTIG in $InputObject.CHECKLIST.STIGS.iSTIG) {
	                $STIGID = ($iSTIG.STIG_INFO.SI_DATA | Where-Object { $_.SID_Name -eq "stigid" }).SID_DATA
	                $STIGObject = [ordered]@{
	                    ReleaseInfo = ($iSTIG.STIG_INFO.SI_DATA | Where-Object { $_.SID_Name -eq "releaseinfo" }).SID_DATA
	                }
	                
	                $GroupIDs = [ordered]@{ }
	                foreach ($Vuln in $iSTIG.VULN) {
	                    $GroupID = ($Vuln.STIG_DATA | Where-Object { $_.VULN_ATTRIBUTE -eq "Vuln_Num" }).ATTRIBUTE_DATA
	                    
	                    $VulnObject = [ordered]@{
	                        GroupID = $GroupID
	                        RuleID  = ($Vuln.STIG_DATA | Where-Object { $_.VULN_ATTRIBUTE -eq "Rule_ID" }).ATTRIBUTE_DATA
	                        RuleTitle = ($Vuln.STIG_DATA | Where-Object { $_.VULN_ATTRIBUTE -eq "Rule_Title" }).ATTRIBUTE_DATA
	                        DiscussionText = ($Vuln.STIG_DATA | Where-Object { $_.VULN_ATTRIBUTE -eq "Vuln_Discuss" }).ATTRIBUTE_DATA
	                        CheckText = ($Vuln.STIG_DATA | Where-Object { $_.VULN_ATTRIBUTE -eq "Check_Content" }).ATTRIBUTE_DATA
	                        FixText = ($Vuln.STIG_DATA | Where-Object { $_.VULN_ATTRIBUTE -eq "Fix_Text" }).ATTRIBUTE_DATA
	                        LEGACY_GroupID = ($Vuln.STIG_DATA | Where-Object { $_.VULN_ATTRIBUTE -eq "LEGACY_ID" -and $_.ATTRIBUTE_DATA -match "^V-" }).ATTRIBUTE_DATA
	                        LEGACY_RuleID = ($Vuln.STIG_DATA | Where-Object { $_.VULN_ATTRIBUTE -eq "LEGACY_ID" -and $_.ATTRIBUTE_DATA -match "^SV-" }).ATTRIBUTE_DATA
	                        Status  = ($Vuln).STATUS
	                        FindingDetails = ($Vuln).FINDING_DETAILS
	                        Comments = ($Vuln).COMMENTS
	                        SeverityOverride = ($Vuln).SEVERITY_OVERRIDE
	                        SeverityJustification = ($Vuln).SEVERITY_JUSTIFICATION
	                    }
	                    
	                    $GroupIDs.Add($GroupID, $VulnObject)
	                }
	                
	                $STIGObject.Add("GroupIDs", $GroupIDs)
	                $Output.Add($STIGID, $STIGObject)
	            }
	        }
	        "CKLB" {
	            foreach ($ID in $InputObject.stigs) {
	                $STIGID = $ID.stig_id
	                $STIGObject = [ordered]@{
	                    ReleaseInfo = $ID.release_info
	                }
	                
	                $GroupIDs = [ordered]@{ }
	                foreach ($Rule in $ID.rules) {
	                    $GroupID = $Rule.group_id
	                    
	                    $VulnObject = [ordered]@{
	                        GroupID        = $GroupID
	                        RuleID         = $Rule.rule_id_src
	                        RuleTitle      = $Rule.group_title
	                        DiscussionText = $Rule.discussion
	                        CheckText      = $Rule.check_content
	                        FixText        = $Rule.fix_text
	                        LEGACY_GroupID = $Rule.legacy_ids | Where-Object { $_ -match "^V-" }
	                        LEGACY_RuleID  = $Rule.legacy_ids | Where-Object { $_ -match "^SV-" }
	                        Status         = $Rule.status
	                        FindingDetails = $Rule.finding_details
	                        Comments       = $Rule.comments
	                        SeverityOverride = $Rule.overrides.severity.severity
	                        SeverityJustification = $Rule.overrides.severity.reason
	                    }
	                    
	                    $GroupIDs.Add($GroupID, $VulnObject)
	                }
	                
	                $STIGObject.Add("GroupIDs", $GroupIDs)
	                $Output.Add($STIGID, $STIGObject)
	            }
	        }
	    }
	    
	    return $Output
	}
	
	function Convert-Status {
	    # Super simple function to save space. Converts freely between Status for Evaluate-STIG, CKL, CKLB, XCCDF.
	    [cmdletbinding()]
	    param (
	        [Parameter(ValueFromPipeline)]
	        [ValidateSet(
	                     'NR', 'NF', 'NA', 'O', # Evaluate-STIG
	                     'Not_Reviewed', 'NotAFinding', 'Not_Applicable', 'Open', # CKL/CKLB (except 'NotAFinding')
	                     'not_a_finding', # CKLB only
	                     'notchecked', 'pass', 'notapplicable', 'fail' # STIG Manager
	                     )]
	        $InputObject,
	        
	        [ValidateSet('EvalSTIG', 'CKL', 'CKLB', 'XCCDF')]
	        [String]$Output
	    )
	    
	    $SortingHat = @{
	        'EvalSTIG' = @{
	            # Input = CKL
	            'Not_Reviewed'   = 'NR'
	            'NotAFinding'    = 'NF'
	            'Not_Applicable' = 'NA'
	            'Open'           = 'O'
	            # Input = CKLB
	            'not_a_finding'  = 'NF'
	            # Input = STIGMAN
	            'notchecked'     = 'NR'
	            'pass'           = 'NF'
	            'notapplicable'  = 'NA'
	            'fail'           = 'O'
	        }
	        'CKL' = @{
	            # Input = Evaluate-STIG
	            'NR'            = 'Not_Reviewed'
	            'NF'            = 'NotAFinding'
	            'NA'            = 'Not_Applicable'
	            'O'             = 'Open'
	            # Input = CKLB
	            'not_a_finding' = 'NotAFinding'
	            # Input = STIGMAN
	            'notchecked'    = 'Not_Reviewed'
	            'pass'          = 'NotAFinding'
	            'notapplicable' = 'Not_Applicable'
	            'fail'          = 'Open'
	        }
	        'CKLB' = @{
	            # Input = Evaluate-STIG
	            'NR'            = 'Not_Reviewed'
	            'NF'            = 'not_a_finding'
	            'NA'            = 'Not_Applicable'
	            'O'             = 'Open'
	            # Input = CKLB
	            'NotAFinding'   = 'not_a_finding'
	            # Input = STIGMAN
	            'notchecked'    = 'Not_Reviewed'
	            'pass'          = 'not_a_finding'
	            'notapplicable' = 'Not_Applicable'
	            'fail'          = 'Open'
	        }
	        'XCCDF' = @{
	            # Input = Evaluate-STIG
	            'NR'             = 'notchecked'
	            'NF'             = 'pass'
	            'NA'             = 'notapplicable'
	            'O'              = 'fail'
	            # Input = CKL
	            'Not_Reviewed'   = 'notchecked'
	            'NotAFinding'    = 'pass'
	            'Not_Applicable' = 'notapplicable'
	            'Open'           = 'fail'
	            # Input = CKLB
	            'not_a_finding'  = 'pass'
	        }
	    }
	    
	    $result = $SortingHat[$Output][$InputObject]
	    if (-not ($result)) {
	        $result = $InputObject
	    }
	    return $result
	    
	}
	
	function Convert-XccdfToHashTable {
	    param
	    (
	        [Parameter(Mandatory = $true)]
	        [psobject]$InputObject
	    )
	    
	    $Output = [ordered]@{
	        STIGID      = $InputObject.Benchmark.id
	        ReleaseInfo = ($InputObject.Benchmark.'plain-text' | Where-Object id -eq "release-info").'#text'
	    }
	    
	    $GroupIDs = [ordered]@{ }
	    foreach ($Vuln in $InputObject.Benchmark.Group) {
	        $GroupID = $Vuln.id
	        
	        $VulnObject = [ordered]@{
	            GroupID        = $GroupID
	            RuleID         = $Vuln.Rule.id
	            RuleTitle      = $Vuln.Rule.title
	            DiscussionText = [String](Get-InnerXml -InnerXml $Vuln.Rule.description -Tag "VulnDiscussion")
	            CheckText      = $Vuln.Rule.check.'check-content'
	            FixText        = $Vuln.Rule.fixtext.'#text'
	            LEGACY_GroupID = $Vuln.Rule.ident.'#text' | Where-Object { $_ -match "^V-" }
	            LEGACY_RuleID  = $Vuln.Rule.ident.'#text' | Where-Object { $_ -match "^SV-" }
	        }
	        
	        $GroupIDs.Add($GroupID, $VulnObject)
	    }
	    
	    $Output.Add("GroupIDs", $GroupIDs)
	    
	    return $Output
	}
	
	Function Get-InnerXml {
	    # Function to extract data from InnerXml objects (e.g. Benchmark.Group.Rule.Description from STIG XCCDF).
	    param
	    (
	        [Parameter(Mandatory)]
	        [string]$InnerXml,
	        
	        [Parameter(Mandatory)]
	        [psobject]$Tag
	    )
	    
	    $Value = ""
	    $MatchString = "(?sm)<$Tag>.{0,}</$Tag>"
	    if ($InnerXml -match $MatchString) {
	        $Value = $Matches[0] -replace "</{0,}$Tag>", ""
	    }
	    
	    return $Value
	}
	
	function Save-AnswerFileObject {
	    param (
	        [Parameter(Mandatory = $true)]
	        [psobject]$AFObject,
	        
	        [Parameter(Mandatory = $true)]
	        [string]$Path,
	        
	        [Parameter(Mandatory = $false)]
	        [switch]$CreateBackup
	    )
	    
	    if ($CreateBackup) {
	        # Create a backup of the XML file before proceeding
	        $BAKFile = $Path -replace ([System.IO.Path]::GetExtension($Path), ".bak")
	        Copy-Item -Path $Path -Destination $BAKFile -Force
	    }
	    
	    # ==========================================================
	    # Begin Write XML
	    # ==========================================================
	    $STIG = $AFObject.Keys | Select-Object -First 1
	    $Encoding = [System.Text.Encoding]::UTF8
	    $XmlWriter = New-Object System.Xml.XmlTextWriter($Path, $Encoding)
	    $XmlWriter.Formatting = "Indented"
	    $XmlWriter.Indentation = 2
	    
	    $XmlWriter.WriteStartDocument()
	    
	    # Add Comment section
	    $XmlWriter.WriteComment('**************************************************************************************
This file contains answers for known opens and findings that cannot be evaluated through technical means.
<STIGComments>      - Top element.  May only occur once.
      "Name"           : Required.  Must match the STIG ShortName in -ListSupportedProducts.  When a match is found, this answer file will automatically be used for the STIG.
<Vuln>              - Multiple <Vuln> sections may be configured in a single answer file provided the "ID" attribute is unique.
      "ID"             : Required.  The STIG VulnID or RuleID.
<AnswerKey>         - Multiple <AnswerKey> sections may be configured within a single <Vuln> section provided the "Name" attribute is unique.
      "Name"           : Required.  The name of the key to be called by "-AnswerKey".  "DEFAULT" may be used in lieu of using "-AnswerKey".
<Answer>            - Multiple <Answer> sections may be configured within an <AnswerKey> section provided the "Index" attribute is unique AND the combination of the other attributes is unique.
      "Index"          : Required.  Identifier for the answer.
      "ExpectedStatus" : Required.  The initial status that Evaluate-STIG determined.  Refer to "Valid Status formats" below.
      "Hostname"       : Optional.  Hostname(s) that the answer is applicable to.  Use comma separation for multiple.
      "Instance"       : Optional.  Instance name(s) (e.g. for SQL) that the answer is applicable to.  Use comma separation for multiple.  Reference FindingDetails for appropriate Instance value.
      "Database"       : Optional.  Database name(s) (e.g. for SQL) that the answer is applicable to.  Use comma separation for multiple.  Reference FindingDetails for appropriate Database value.
      "Site"           : Optional.  Site names (e.g. for IIS) that the answer is applicable to.  Use comma separation for multiple.  Reference FindingDetails for appropriate Site value.
      "ResultHash"     : Optional.  Hash of FindingDetails text after "~~~~~" bar.  Use comma separation for multiple.  Reference FindingDetails for calculated ResultHash.
<ValidationCode>    - Powershell code that returns a boolean value or Hashtable.  If blank, "true" is assumed.
                      *Note: If Validation Code returns a Hashtable, the Object MUST contain both [String]"Results" and [Boolean]"Valid" keys.  "Results" will be written to the Comments field of the STIG check.
                      The following Evaluate-STIG variables are also available to be called within validation code:
      $ESPath          : [String]  Path that Evaluate-STIG.ps1 was executed from.
      $ExpectedStatus  : [String]  Status that Evaluate-STIG determined.  Will be in CKL format (refer to "Valid Status formats" below).
      $ResultHash      : [String]  SHA1 hash of ResultData.  Reference FindingDetails for calculated ResultHash.
      $ResultData      : [Array]   FindingDetails content after "~~~~~" bar.
      $Username        : [String]  User name processed for HKCU check.  Reference to FindingDetails for appropriate Username value.
      $UserSID         : [String]  User SID processed for HKCU check.  Reference to FindingDetails for appropriate UserSID value.
      $Instance        : [String]  Instance name processed.  Reference FindingDetails for appropriate Instance value.
      $Database        : [String]  Database name processed.  Reference FindingDetails for appropriate Database value.
      $Site            : [String]  Site name processed.  Reference FindingDetails for appropriate Site value.
      $ShowRun         : [Array]   Show-RunningConfig section from Cisco Show-TechSupport.
<ValidTrueStatus>   - The status the check should be set to if ValidationCode returns "true".  Refer to "Valid Status formats" below.  If blank, Status is unchanged.
<ValidTrueComment>  - The verbiage to add to the Comments section if ValidationCode returns "true".
<ValidFalseStatus>  - The status the check should be set to if ValidationCode DOES NOT return "true".  Refer to "Valid Status formats" below.  If blank, Status is unchanged
<ValidFalseComment> - The verbiage to add to the Comments section if ValidationCode DOES NOT return "true".

* Valid Status formats:
    |     Status     | EvalSTIG |       CKL        |       CKLB       |      XCCDF      |
    |================|==========|==================|==================|=================|
    | Not Reviewed   | "NR"     | "Not_Reviewed"   | "Not_Reviewed"   | "notchecked"    |
    | Not A Finding  | "NF"     | "NotAFinding"    | "not_a_finding"  | "pass"          |
    | Open           | "O"      | "Open"           | "Open"           | "fail"          |
    | Not Applicable | "NA"     | "Not_Applicable" | "Not_Applicable" | "notapplicable" |
    |================|==========|==================|==================|=================|

* Answer Weighting:
  Evaluate-STIG adds the weights for all "applicable" attributes configured in an <Answer>.  If an attribute is configured but not applicable to the STIG (e.g. configuring the "Database" attribute for an IIS Site STIG) then the weight for that attribute is not included in the calculation.
    |    Attribute     | Weight |
    |==================|========|
    | ExpectedStatus   |   0 *  |  * ExpectedStatus is a hard requirement.  If not a match, the answer is ignored.
    | Hostname         |   5    |
    | Instance         |   4    |
    | Database         |   3    |
    | Site             |   2    |
    | ResultHash       |   1    |
    | <AnswerKey Name> |   16   |
    |==================|========|
**************************************************************************************')
	    
	    # Create STIGComments node
	    $XmlWriter.WriteStartElement("STIGComments")
	    $XmlWriter.WriteAttributeString("Name", $STIG)
	    if ($AFObject.$($STIG)._Comment -notin @($null, "")) {
	        $XmlWriter.WriteComment($AFObject.$($STIG)._Comment) # Write the comment for STIGComments node
	    }
	    
	    # Create Vuln nodes
	    foreach ($Vuln in ($AFObject.$($STIG).Keys | Where-Object { $_ -ne "_Comment" })) {
	        $XmlWriter.WriteStartElement("Vuln")
	        $XmlWriter.WriteAttributeString("ID", $Vuln)
	        if ($AFObject.$($STIG).$($Vuln)._Comment -notin @($null, "")) {
	            $XmlWriter.WriteComment($AFObject.$($STIG).$($Vuln)._Comment) # Write the comment for Vuln node
	        }
	        
	        # Create AnswerKey nodes
	        foreach ($KeyName in ($AFObject.$($STIG).$($Vuln).Keys | Where-Object { $_ -ne "_Comment" })) {
	            $XmlWriter.WriteStartElement("AnswerKey")
	            $XmlWriter.WriteAttributeString("Name", $KeyName)
	            if ($AFObject.$($STIG).$($Vuln).$($KeyName)._Comment -notin @($null, "")) {
	                $XmlWriter.WriteComment($AFObject.$($STIG).$($Vuln).$($KeyName)._Comment) # Write the comment for AnswerKey node
	            }
	            
	            # Create Answer nodes
	            foreach ($Index in ($AFObject.$($STIG).$($Vuln).$($KeyName).Keys | Where-Object { $_ -ne "_Comment" })) {
	                $XmlWriter.WriteStartElement("Answer")
	                $XmlWriter.WriteAttributeString("Index", $Index)
	                foreach ($Attribute in @("ExpectedStatus", "Hostname", "Instance", "Database", "Site", "ResultHash")) {
	                    # Add the Index attributes
	                    switch ($Attribute) {
	                        "ExpectedStatus" {
	                            if ($AFObject.$($STIG).$($Vuln).$($KeyName).$($Index).$($Attribute) -notin @($null, "")) {
	                                $FormattedStatus = Convert-Status -InputObject $AFObject.$($STIG).$($Vuln).$($KeyName).$($Index).$($Attribute) -Output $comboboxAF_FormatStatus.SelectedItem
	                            }
	                            else {
	                                $FormattedStatus = ""
	                            }
	                            $XmlWriter.WriteAttributeString($Attribute, $FormattedStatus)
	                        }
	                        default {
	                            $XmlWriter.WriteAttributeString($Attribute, $AFObject.$($STIG).$($Vuln).$($KeyName).$($Index).$($Attribute))
	                        }
	                    }
	                }
	                if ($AFObject.$($STIG).$($Vuln).$($KeyName).$($Index)._Comment -notin @($null, "")) {
	                    $XmlWriter.WriteComment($AFObject.$($STIG).$($Vuln).$($KeyName).$($Index)._Comment) # Write the comment for the Index
	                }
	                
	                # Create sub nodes
	                foreach ($SubNode in @("ValidationCode", "ValidTrueStatus", "ValidTrueComment", "ValidFalseStatus", "ValidFalseComment")) {
	                    $XmlWriter.WriteStartElement($SubNode)
	                    if ($AFObject.$($STIG).$($Vuln).$($KeyName).$($Index).$($SubNode) -notin @($null, "")) {
	                        switch ($SubNode) {
	                            "ValidationCode" {
	                                $XmlWriter.WriteString("`r`n")
	                                $XmlWriter.WriteString($AFObject.$($STIG).$($Vuln).$($KeyName).$($Index).$($SubNode))
	                                $XmlWriter.WriteString("`r`n        ")
	                            }
	                            { $_ -in @("ValidTrueStatus", "ValidFalseStatus") } {
	                                $FormattedStatus = Convert-Status -InputObject $AFObject.$($STIG).$($Vuln).$($KeyName).$($Index).$($SubNode) -Output $comboboxAF_FormatStatus.SelectedItem
	                                $XmlWriter.WriteString($FormattedStatus)
	                            }
	                            default {
	                                $XmlWriter.WriteString($AFObject.$($STIG).$($Vuln).$($KeyName).$($Index).$($SubNode))
	                            }
	                        }
	                    }
	                    else {
	                        $XmlWriter.WriteWhitespace("")
	                    }
	                    $XmlWriter.WriteFullEndElement()
	                }
	                
	                # Close Answer node
	                $XmlWriter.WriteEndElement()
	            }
	            # Close AnswerKey node
	            $XmlWriter.WriteEndElement()
	        }
	        # Close Vuln node
	        $XmlWriter.WriteEndElement()
	    }
	    # Close STIGComments node
	    $XmlWriter.WriteEndElement()
	    
	    $XmlWriter.WriteEnddocument()
	    $XmlWriter.Flush()
	    $XmlWriter.Close()
	}
	
	function Create-AnswerFileExport {
	    param (
	        [Parameter(Mandatory = $true)]
	        [psobject]$SelectedItems,
	        
	        [Parameter(Mandatory = $true)]
	        [string]$AFPath,
	    
	        [Parameter(Mandatory = $true)]
	        [ValidateSet("HTML", "CSV", "JSON")]
	        [string]$ExportType,
	        
	        [Parameter(Mandatory = $true)]
	        [string]$OutFile
	    )
	    
	    try {
	        $Log = [ordered]@{
	            Info = [ordered]@{
	                Result = "Info"
	                Message = "Validate selected files..."
	            }
	        }
	        
	        # Build inventory of valid selected files
	        $ValidFiles = @()
	        
	        foreach ($Item in $SelectedItems) {
	            $Content = [ordered]@{
	                Result  = ""
	                Message = ""
	            }
	            # Check legacy schema first
	            $LegacyResult = Test-XmlAgainstSchema -XmlFile (Join-Path -Path $AFPath -ChildPath $Item) -SchemaInput $script:LegacyAFSchema -IsSchemaString
	            if ($LegacyResult -eq $true) {
	                $Content.Result = "Failed"
	                $Content.Message = @("Legacy answer file.  Please migrate with the 'Maintain' button.")
	                $Content.Message += "** Excluded from export **"
	            }
	            else {
	                $Result = Test-XmlAgainstSchema -XmlFile (Join-Path -Path $AFPath -ChildPath $Item) -SchemaInput (Join-Path -Path $script:ESPath -ChildPath xml | Join-Path -ChildPath Schema_AnswerFile.xsd)
	                if ($Result -eq $true) {
	                    $ValidFiles += $Item
	                    $Content.Result = "Passed"
	                    $Content.Message = $Result.Message
	                }
	                else {
	                    $Content.Result = "Failed"
	                    $Content.Message = $Result.Message
	                    $Content.Message += "** Excluded from export **"
	                }
	            }
	            $Log.Add($Item, $Content)
	        }
	        
	        # Create temp export XML file
	        $TempFile = Join-Path -Path $env:TEMP -ChildPath ES_AFExport_tmp.xml
	        
	        $Encoding = [System.Text.Encoding]::UTF8
	        $XmlWriter = New-Object System.Xml.XmlTextWriter($TempFile, $Encoding)
	        $XmlWriter.Formatting = "Indented"
	        $XmlWriter.Indentation = 2
	        
	        $XmlWriter.WriteStartDocument()
	        
	        # Create AnswerFiles node
	        $XmlWriter.WriteStartElement("AnswerFiles")
	        $XmlWriter.WriteAttributeString("Created", (Get-Date -Format "dd-MMM-yyyy HH:mm:ss").ToUpper())
	        
	        foreach ($ValidFile in $ValidFiles) {
	            $File = Get-ChildItem -Path $(Join-Path -Path $AFPath -ChildPath $ValidFile)
	            $AFContent = [XML](Get-Content $File.FullName -Raw)
	            
	            # Create AnswerFile node
	            $XmlWriter.WriteStartElement("AnswerFile")
	            $XmlWriter.WriteAttributeString("FileName", $File.Name)
	            
	            # Create AnswerFile/Comment element
	            $XmlWriter.WriteStartElement("Comment")
	            if ($AFContent.STIGComments.'#comment' -notin @($null, "")) {
	                $XmlWriter.WriteString($AFContent.STIGComments.'#comment')
	            }
	            else {
	                $XmlWriter.WriteWhitespace("")
	            }
	            $XmlWriter.WriteFullEndElement()
	            
	            # Create AnswerFile/Path element
	            $XmlWriter.WriteStartElement("Path")
	            $XmlWriter.WriteString($AFPath)
	            $XmlWriter.WriteFullEndElement()
	            
	            # Create AnswerFile/Modified element
	            $XmlWriter.WriteStartElement("Modified")
	            $XmlWriter.WriteString($(Get-Date $($File.LastWriteTime) -Format yyyy-MM-ddTHH:mm:ssK))
	            $XmlWriter.WriteFullEndElement()
	            
	            # Create AnswerFile/ShortName element
	            $XmlWriter.WriteStartElement("ShortName")
	            $XmlWriter.WriteString($AFContent.STIGComments.Name)
	            $XmlWriter.WriteFullEndElement()
	            
	            # Create Vuln nodes
	            foreach ($Vuln in $AFContent.STIGComments.Vuln) {
	                # Create AnswerFile/Vuln node
	                $XmlWriter.WriteStartElement("Vuln")
	                $XmlWriter.WriteAttributeString("ID", $Vuln.ID)
	                
	                # Create AnswerFile/Vuln/Comment element
	                $XmlWriter.WriteStartElement("Comment")
	                if ($Vuln.'#comment' -notin @($null, "")) {
	                    $XmlWriter.WriteString($Vuln.'#comment')
	                }
	                else {
	                    $XmlWriter.WriteWhitespace("")
	                }
	                $XmlWriter.WriteFullEndElement()
	                
	                # Create AnswerKey nodes
	                foreach ($AnswerKey in $Vuln.AnswerKey) {
	                    # Create AnswerFile/Vuln/AnswerKey node
	                    $XmlWriter.WriteStartElement("AnswerKey")
	                    $XmlWriter.WriteAttributeString("Name", $AnswerKey.Name)
	                    
	                    # Create AnswerFile/Vuln/AnswerKey/Comment element
	                    $XmlWriter.WriteStartElement("Comment")
	                    if ($AnswerKey.'#comment' -notin @($null, "")) {
	                        $XmlWriter.WriteString($AnswerKey.'#comment')
	                    }
	                    else {
	                        $XmlWriter.WriteWhitespace("")
	                    }
	                    $XmlWriter.WriteFullEndElement()
	                    
	                    # Create Answer nodes
	                    foreach ($Answer in $AnswerKey.Answer) {
	                        # Create AnswerFile/Vuln/AnswerKey/Answer node
	                        $XmlWriter.WriteStartElement("Answer")
	                        $XmlWriter.WriteAttributeString("Index", $Answer.Index)
	                        
	                        # Create AnswerFile/Vuln/AnswerKey/Answer/Comment element
	                        $XmlWriter.WriteStartElement("Comment")
	                        if ($Answer.'#comment' -notin @($null, "")) {
	                            $XmlWriter.WriteString($Answer.'#comment')
	                        }
	                        else {
	                            $XmlWriter.WriteWhitespace("")
	                        }
	                        $XmlWriter.WriteFullEndElement()
	                        
	                        foreach ($Item in @("ExpectedStatus", "Hostname", "Instance", "Database", "Site", "ResultHash", "ValidationCode", "ValidTrueStatus", "ValidTrueComment", "ValidFalseStatus", "ValidFalseComment")) {
	                            $XmlWriter.WriteStartElement($Item)
	                            if ($Answer.$Item -notin @($null, "")) {
	                                $XmlWriter.WriteString($Answer.$Item)
	                            }
	                            else {
	                                $XmlWriter.WriteWhitespace("")
	                            }
	                            $XmlWriter.WriteFullEndElement()
	                        }
	                        
	                        # Close Answer node
	                        $XmlWriter.WriteEndElement()
	                    }
	                    
	                    # Close AnswerKey node
	                    $XmlWriter.WriteEndElement()
	                }
	                
	                # Close Vuln node
	                $XmlWriter.WriteEndElement()
	            }
	            
	            # Close AnswerFile node
	            $XmlWriter.WriteEndElement()
	        }
	        
	        # Close AnswerFiles node
	        $XmlWriter.WriteEndElement()
	        
	        $XmlWriter.WriteEnddocument()
	        $XmlWriter.Flush()
	        $XmlWriter.Close()
	  
	        # Create export based on type selected
	        Switch ($ExportType) {
	            "HTML" {
	                $XsltPath = (Join-Path -Path $script:ESPath -ChildPath xml | Join-Path -ChildPath AnswerFileReport.xslt)
	                if (-Not (Test-Path -Path $XSLTPath)) {
	                    throw "'$($XsltPath)' not found."
	                }
	                $Xslt = New-Object System.Xml.Xsl.XslCompiledTransform
	                $XsltSettings = New-Object System.Xml.Xsl.XsltSettings
	                $XsltSettings.EnableScript = $true
	                $XsltSettings.EnableDocumentFunction = $true
	                $Resolver = New-Object System.Xml.XmlUrlResolver
	                $Xslt.Load($XsltPath, $XsltSettings, $Resolver)
	                $XmlReader = [System.Xml.XmlReader]::Create($TempFile)
	                
	                # Create HTML
	                $Stream = New-Object System.IO.StreamWriter($OutFile, $false, [System.Text.Encoding]::UTF8)
	                $Xslt.Transform($XmlReader, $null, $Stream)
	                $Stream.Close()
	                $XmlReader.Close()
	            }
	            "CSV" {
	                [xml]$XmlContent = Get-Content -Path $TempFile -Raw
	                
	                # Build an array object from XML
	                $CsvOutput = New-Object System.Collections.ArrayList
	                foreach ($AnswerFile in $XmlContent.AnswerFiles.AnswerFile) {
	                    foreach ($Vuln in $AnswerFile.Vuln) {
	                        foreach ($AnswerKey in $Vuln.AnswerKey) {
	                            foreach ($Answer in $AnswerKey.Answer) {
	                                $Record = [PSCustomObject]@{
	                                    # Data from the parent <AnswerFile> node
	                                    AnswerFile_FileName  = $AnswerFile.FileName
	                                    AnswerFile_Comment   = $AnswerFile.Comment.Trim()
	                                    AnswerFile_Path      = $AnswerFile.Path
	                                    AnswerFile_Modified  = $AnswerFile.Modified
	                                    AnswerFile_ShortName = $AnswerFile.ShortName
	                                    
	                                    # Data from the parent <Vuln> node
	                                    Vuln_ID              = $Vuln.ID
	                                    Vuln_Comment         = $Vuln.Comment.Trim()
	                                    
	                                    # Data from the parent <AnswerKey> node
	                                    AnswerKey_Name       = $AnswerKey.Name
	                                    AnswerKey_Comment    = $AnswerKey.Comment.Trim()
	                                    
	                                    # Data from the current <Answer> node
	                                    Answer_Index         = $Answer.Index
	                                    Answer_Comment       = $Answer.Comment.Trim()
	                                    ExpectedStatus       = $Answer.ExpectedStatus
	                                    Hostname             = $Answer.Hostname
	                                    Instance             = $Answer.Instance
	                                    Database             = $Answer.Database
	                                    Site                 = $Answer.Site
	                                    ResultHash           = $Answer.ResultHash
	                                    ValidationCode       = $Answer.ValidationCode.Trim()
	                                    ValidTrueStatus      = $Answer.ValidTrueStatus
	                                    ValidTrueComment     = $Answer.ValidTrueComment.Trim()
	                                    ValidFalseStatus     = $Answer.ValidFalseStatus
	                                    ValidFalseComment    = $Answer.ValidFalseComment.Trim()
	                                }
	                                $CsvOutput += $Record
	                            }
	                        }
	                    }
	                }
	                
	                # Create CSV
	                $CsvOutput | Export-Csv -Path $OutFile -NoTypeInformation -Encoding UTF8 -Force
	            }
	            "JSON" {
	                [xml]$XmlContent = Get-Content -Path $TempFile -Raw
	                
	                # Build a dictionary object from XML
	                $JsonOutput = [ordered]@{
	                }
	                $ArrAnswerFiles = New-Object System.Collections.ArrayList
	                foreach ($AnswerFile in $XmlContent.AnswerFiles.AnswerFile) {
	                    $ObjAnswerFile = [ordered]@{
	                        FileName  = $AnswerFile.FileName
	                        Comment   = $AnswerFile.Comment.Trim()
	                        Path      = $AnswerFile.Path
	                        Modified  = $AnswerFile.Modified
	                        ShortName = $AnswerFile.ShortName
	                    }
	                    $ArrVulns = New-Object System.Collections.ArrayList
	                    foreach ($Vuln in $AnswerFile.Vuln) {
	                        $ObjVuln = [ordered]@{
	                            ID      = $Vuln.ID
	                            Comment = $Vuln.Comment.Trim()
	                        }
	                        $ArrAnswerKeys = New-Object System.Collections.ArrayList
	                        foreach ($AnswerKey in $Vuln.AnswerKey) {
	                            $ObjAnswerKey = [ordered]@{
	                                Name    = $AnswerKey.Name
	                                Comment = $AnswerKey.Comment.Trim()
	                            }
	                            $ArrAnswers = New-Object System.Collections.ArrayList
	                            foreach ($Answer in $AnswerKey.Answer) {
	                                $ObjAnswer = [ordered]@{
	                                    Index             = $Answer.Index
	                                    Comment           = $Answer.Comment.Trim()
	                                    ExpectedStatus    = $Answer.ExpectedStatus
	                                    Hostname          = $Answer.Hostname
	                                    Instance          = $Answer.Instance
	                                    Database          = $Answer.Database
	                                    Site              = $Answer.Site
	                                    ResultHash        = $Answer.ResultHash
	                                    ValidationCode    = $Answer.ValidationCode.Trim()
	                                    ValidTrueStatus   = $Answer.ValidTrueStatus
	                                    ValidTrueComment  = $Answer.ValidTrueComment.Trim()
	                                    ValidFalseStatus  = $Answer.ValidFalseStatus
	                                    ValidFalseComment = $Answer.ValidFalseComment.Trim()
	                                }
	                                $null = $ArrAnswers.Add($ObjAnswer)
	                            }
	                            $ObjAnswerKey.Add("Answers", $ArrAnswers)
	                            $null = $ArrAnswerKeys.Add($ObjAnswerKey)
	                        }
	                        $ObjVuln.Add("AnswerKeys", $ArrAnswerKeys)
	                        $null = $ArrVulns.Add($ObjVuln)
	                    }
	                    $ObjAnswerFile.Add("Vulns", $ArrVulns)
	                    $null = $ArrAnswerFiles.Add($ObjAnswerFile)
	                }
	                $JsonOutput.Add("AnswerFiles", $ArrAnswerFiles)
	                
	                # Create JSON
	                ConvertTo-Json $JsonOutput -Depth 100 | Format-Json | Set-Content $OutFile -Encoding UTF8 -Force
	            }
	        }
	        
	        # Remove temp XML file
	        if (Test-Path $TempFile) {
	           Remove-Item -Path $TempFile -Force
	        }
	        
	        # Return log for display
	        $Content = [ordered]@{
	            Result  = "Success"
	            Message = "Created export file '$($Outfile)'"
	        }
	        $Log.Add("Create Export", $Content)
	        return $Log
	    }
	    catch {
	        # Return log for display
	        $Content = [ordered]@{
	            Result  = "Failed"
	            Message = $_.Exception.Message
	        }
	        $Log.Add("Create Export", $Content)
	        return $Log
	    }
	}
	
	function Format-Json {
	    <#
	    .SYNOPSIS
	        https://stackoverflow.com/questions/56322993/proper-formating-of-json-using-powershell/56324939#56324939
	        Prettifies JSON output.
	        Version January 3rd 2024
	        Fixes:
	            - empty [] or {} or in-line arrays as per https://stackoverflow.com/a/71664664/9898643
	              by Widlov (https://stackoverflow.com/users/1716283/widlov)
	            - Unicode Apostrophs \u0027 as written by ConvertTo-Json are replaced with regular single quotes "'"
	            - multiline empty [] or {} are converted into inline arrays or objects
	    .DESCRIPTION
	        Reformats a JSON string so the output looks better than what ConvertTo-Json outputs.
	    .PARAMETER Json
	        Required: [string] The JSON text to prettify.
	    .PARAMETER Minify
	        Optional: Returns the json string compressed.
	    .PARAMETER Indentation
	        Optional: The number of spaces (1..1024) to use for indentation. Defaults to 2.
	    .PARAMETER AsArray
	        Optional: If set, the output will be in the form of a string array, otherwise a single string is output.
	    .EXAMPLE
	        $json | ConvertTo-Json | Format-Json -Indentation 4
	    .OUTPUTS
	        System.String or System.String[] (the latter when parameter AsArray is set)
	    #>
	    [CmdletBinding(DefaultParameterSetName = 'Prettify')]
	    Param (
	        [Parameter(Mandatory = $true, Position = 0, ValueFromPipeline = $true)]
	        [string]$Json,
	        [Parameter(ParameterSetName = 'Minify')]
	        [switch]$Minify,
	        [Parameter(ParameterSetName = 'Prettify')]
	        [ValidateRange(1, 1024)]
	        [int]$Indentation = 2,
	        [Parameter(ParameterSetName = 'Prettify')]
	        [switch]$AsArray
	    )
	    
	    if ($PSCmdlet.ParameterSetName -eq 'Minify') {
	        return ($Json | ConvertFrom-Json) | ConvertTo-Json -Depth 100 -Compress
	    }
	    
	    # If the input JSON text has been created with ConvertTo-Json -Compress
	    # then we first need to reconvert it without compression
	    if ($Json -notmatch '\r?\n') {
	        $Json = ($Json | ConvertFrom-Json) | ConvertTo-Json -Depth 100
	    }
	    
	    $indent = 0
	    $regexUnlessQuoted = '(?=([^"]*"[^"]*")*[^"]*$)'
	    
	    $result = ($Json -split '\r?\n' | ForEach-Object {
	            # If the line contains a ] or } character, 
	            # we need to decrement the indentation level unless:
	            #   - it is inside quotes, AND
	            #   - it does not contain a [ or {
	            if (($_ -match "[}\]]$regexUnlessQuoted") -and ($_ -notmatch "[\{\[]$regexUnlessQuoted")) {
	                $indent = [Math]::Max($indent - $Indentation, 0)
	            }
	            
	            # Replace all colon-space combinations by ": " unless it is inside quotes.
	            $line = (' ' * $indent) + ($_.TrimStart() -replace ":\s+$regexUnlessQuoted", ': ')
	            
	            # If the line contains a [ or { character, 
	            # we need to increment the indentation level unless:
	            #   - it is inside quotes, AND
	            #   - it does not contain a ] or }
	            if (($_ -match "[\{\[]$regexUnlessQuoted") -and ($_ -notmatch "[}\]]$regexUnlessQuoted")) {
	                $indent += $Indentation
	            }
	            
	            # ConvertTo-Json returns all single-quote characters as Unicode Apostrophs \u0027
	            # see: https://stackoverflow.com/a/29312389/9898643
	            $line -replace '\\u0027', "'"
	            
	            # join the array with newlines and convert multiline empty [] or {} into inline arrays or objects
	        }) -join [Environment]::NewLine -replace '(\[)\s+(\])', '$1$2' -replace '(\{)\s+(\})', '$1$2'
	    
	    if ($AsArray) {
	        return, [string[]]($result -split '\r?\n')
	    }
	    $result
	}
	
	function Reset-AFConfiguredData {
	    foreach ($GroupBox in @($groupboxAF_ConfiguredData, $groupboxAF_Attributes)) {
	        foreach ($control in $GroupBox.Controls) {
	            if ($control -is [System.Windows.Forms.TextBox]) {
	                $control.Text = ""
	            }
	            elseif ($control -is [System.Windows.Forms.RichTextBox]) {
	                $control.Text = ""
	            }
	            elseif ($control -is [System.Windows.Forms.ListBox]) {
	                $control.Items.Clear()
	            }
	            elseif ($control -is [System.Windows.Forms.Button] -and $GroupBox -ne $groupboxAF_Attributes) {
	                $control.Enabled = $false
	            }
	        }
	        if ($GroupBox -eq $groupboxAF_Attributes) {
	            $groupboxAF_Attributes.Enabled = $false
	        }
	    }
	}
	
	function Test-IsModified {
	    if ($script:IsModified) {
	        $groupboxAF_Content.Enabled = $false
	        $labelSavedTrueFalse.Text = "True"; $labelSavedTrueFalse.ForeColor = 'Yellow'
	        $buttonAF_Save.Enabled = $true; $buttonAF_Save.BackColor = 'LightGreen'
	        $buttonAF_Discard.Enabled = $true; $buttonAF_Discard.BackColor = 'LightPink'
	    }
	    else {
	        $groupboxAF_Content.Enabled = $true
	        $labelSavedTrueFalse.Text = "False"; $labelSavedTrueFalse.ForeColor = 'White'
	        $buttonAF_Save.Enabled = $false; $buttonAF_Save.BackColor = 'Transparent'
	        $buttonAF_Discard.Enabled = $false; $buttonAF_Discard.BackColor = 'Transparent'
	    }
	}
	
	function Update-AFContentList {
	    param (
	        [Parameter(Mandatory = $false)]
	        [String]$Path,
	        
	        [Parameter(Mandatory = $true)]
	        [ValidateSet("XML", "STIG")]
	        [String]$Content
	    )
	    
	    $listboxAF_Content.Items.Clear()
	    $listboxAF_VulnID.Items.Clear()
	    $listboxAF_AnswerKeyName.Items.Clear()
	    $listboxAF_Index.Items.Clear()
	    
	    switch ($Content) {
	        "XML" {
	            if ($Path -and (Test-Path -Path $Path)) {
	                $XMLFiles = (Get-ChildItem -Path $Path -File -Filter "*.xml" | Where-Object Name -NE "Template_AnswerFile.xml" | Sort-Object Name)
	                if ($XMLFiles) {
	                    # Examine each file to ensure it is valid before adding to listbox
	                    foreach ($Item in $XMLFiles) {
	                        Update-ListBox -ListBox $listboxAF_Content -Items $Item.Name -Append
	                    }
	                }
	            }
	            $buttonAF_OpenCreate.Text = "Open"
	            $buttonAF_Validate.Visible = $true
	            $buttonAF_View.Visible = $true
	            $buttonAF_Maintain.Visible = $true
	            $buttonAF_ExportHTML.Visible = $true
	            $buttonAF_ExportCSV.Visible = $true
	            $buttonAF_ExportJSON.Visible = $true
	        }
	        "STIG" {
	            foreach ($Item in $script:STIGListObj.ShortName) {
	                Update-ListBox -ListBox $listboxAF_Content -Items $Item -Append
	            }
	            $buttonAF_OpenCreate.Text = "Create"
	            $buttonAF_Validate.Visible = $false
	            $buttonAF_View.Visible = $false
	            $buttonAF_Maintain.Visible = $false
	            $buttonAF_ExportHTML.Visible = $false
	            $buttonAF_ExportCSV.Visible = $false
	            $buttonAF_ExportJSON.Visible = $false
	        }
	    }
	}
	
	function Update-AnswerDataFields {
	    param (
	        [Parameter(Mandatory = $false)]
	        [String]$VulnID,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$AnswerKeyName,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$Index,
	        
	        [Parameter(Mandatory = $false)]
	        [Switch]$Clear
	    )
	    
	    $Fields = @($comboboxAF_ExpectedStatus, $textboxAF_Hostname, $textboxAF_Instance, $textboxAF_Database, $textboxAF_Site, $textboxAF_ResultHash, $richtextboxAF_ValidationCode, $comboboxAF_ValidTrueStatus, $textboxAF_ValidTrueComment, $comboboxAF_ValidFalseStatus, $textboxAF_ValidFalseComment)
	    foreach ($Field in $Fields) {
	        if ($Clear) {
	            $Field.Text = ""
	        }
	        else {
	            $AnswerData = $script:AFObject.$($script:STIGName).$($VulnID).$($AnswerKeyName).$($Index)
	            switch ($Field) {
	                $comboboxAF_ExpectedStatus {
	                    if ($AnswerData.ExpectedStatus -notin @($null, "")) {
	                        $comboboxAF_ExpectedStatus.SelectedItem = Convert-Status -InputObject $AnswerData.ExpectedStatus -Output $comboboxAF_FormatStatus.SelectedItem
	                    }
	                }
	                $textboxAF_Hostname {
	                    $textboxAF_Hostname.Text = $AnswerData.Hostname
	                }
	                $textboxAF_Instance {
	                    $textboxAF_Instance.Text = $AnswerData.Instance
	                }
	                $textboxAF_Database {
	                    $textboxAF_Database.Text = $AnswerData.Database
	                }
	                $textboxAF_Site {
	                    $textboxAF_Site.Text = $AnswerData.Site
	                }
	                $textboxAF_ResultHash {
	                    $textboxAF_ResultHash.Text = $AnswerData.ResultHash
	                }
	                $richtextboxAF_ValidationCode {
	                    $richtextboxAF_ValidationCode.Text = $AnswerData.ValidationCode
	                }
	                $comboboxAF_ValidTrueStatus {
	                    if ($AnswerData.ValidTrueStatus -notin @($null, "")) {
	                        $comboboxAF_ValidTrueStatus.SelectedItem = Convert-Status -InputObject $AnswerData.ValidTrueStatus -Output $comboboxAF_FormatStatus.SelectedItem
	                    }
	                    else {
	                        $comboboxAF_ValidTrueStatus.SelectedItem = ""
	                    }
	                }
	                $textboxAF_ValidTrueComment {
	                    $textboxAF_ValidTrueComment.Text = $AnswerData.ValidTrueComment
	                }
	                $comboboxAF_ValidFalseStatus {
	                    if ($AnswerData.ValidFalseStatus -notin @($null, "")) {
	                        $comboboxAF_ValidFalseStatus.SelectedItem = Convert-Status -InputObject $AnswerData.ValidFalseStatus -Output $comboboxAF_FormatStatus.SelectedItem
	                    }
	                    else {
	                        $comboboxAF_ValidFalseStatus.SelectedItem = ""
	                    }
	                }
	                $textboxAF_ValidFalseComment {
	                    $textboxAF_ValidFalseComment.Text = $AnswerData.ValidFalseComment
	                }
	            }
	        }
	    }
	}
	
	function Update-AFObject {
	    param (
	        [Parameter(Mandatory = $true)]
	        [String]$StatusFormat,
	        
	        [Parameter(Mandatory = $true)]
	        [ValidateSet("Add", "Remove", "Rename", "Reorder", "Update")]
	        [String]$Action,
	        
	        [Parameter(Mandatory = $true)]
	        [String]$STIG,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$VulnID,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$VulnIDComment,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$AnswerKeyName,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$AnswerKeyNameComment,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$Index,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$IndexComment,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$NewKeyName,
	        
	        [Parameter(Mandatory = $false)]
	        [String[]]$IndexOrder,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$ExpectedStatus,
	        
	        [Parameter(Mandatory = $false)]
	        [String[]]$Hostname,
	        
	        [Parameter(Mandatory = $false)]
	        [String[]]$Instance,
	        
	        [Parameter(Mandatory = $false)]
	        [String[]]$Database,
	        
	        [Parameter(Mandatory = $false)]
	        [String[]]$Site,
	        
	        [Parameter(Mandatory = $false)]
	        [String[]]$ResultHash,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$ValidationCode,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$ValidTrueStatus,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$ValidTrueComment,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$ValidFalseStatus,
	        
	        [Parameter(Mandatory = $false)]
	        [String]$ValidFalseComment
	    )
	 
	    switch ($Action) {
	        "Add" {
	            if ($Index) {
	                $IndexObj = [ordered]@{
	                    _Comment       = "" # Initialize Comment
	                    ExpectedStatus = (Convert-Status -InputObject "NR" -Output $StatusFormat) # Initialize ExpectedStatus
	                    Hostname       = "" # Initialize Hostname
	                    Instance       = "" # Initialize Instance
	                    Database       = "" # Initialize Database
	                    Site           = "" # Initialize Site
	                    ValidationCode = "" # Initialize ValidationCode
	                    ValidTrueStatus = "" # Initialize ValidTrueStatus
	                    ValidTrueComment = "" # Initialize ValidTrueComment
	                    ValidFalseStaus = "" # Initialize ValidFalseStaus
	                    ValidFalseComment = "" # Initialize ValidFalseComment
	                }
	                
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.Add($Index, $IndexObj)
	            }
	            elseif ($AnswerKeyName) {
	                $KeyNameObj = [ordered]@{
	                    _Comment = "" # Initialize Comment
	                }
	                
	                $script:AFObject.$STIG.$VulnID.Add($AnswerKeyName, $KeyNameObj)
	                
	                # Add default Index - required for XML validation
	                Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Add -STIG $STIG -VulnID $VulnID -AnswerKeyName $AnswerKeyName -Index "1"
	            }
	            elseif ($VulnID) {
	                $VulnObj = [ordered]@{
	                    _Comment = "" # Initialize Comment
	                }
	                
	                $script:AFObject.$STIG.Add($VulnID, $VulnObj)
	                
	                # Add default AnswerKeyName - required for XML validation
	                Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Add -STIG $STIG -VulnID $VulnID -AnswerKeyName $script:DefaultAFKey
	            }
	        }
	        "Remove" {
	            if ($Index) {
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.Remove($Index)
	            }
	            elseif ($AnswerKeyName) {
	                $script:AFObject.$STIG.$VulnID.Remove($AnswerKeyName)
	            }
	            elseif ($VulnID) {
	                $script:AFObject.$STIG.Remove($VulnID)
	            }
	        }
	        "Rename" {
	            if ($Index) {
	                # To preserve order, get the current order replacing the old key with new
	                $PreservedOrder = ($script:AFObject.$STIG.$VulnID.$AnswerKeyName.Keys) -replace $Index, $NewKeyName
	                
	                # Copy old key to new and then remove old key
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$NewKeyName = $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.Remove($Index)
	                
	                # Create new children object after rename to preserve original order
	                $NewChildren = [ordered]@{ }
	                foreach ($Key in $PreservedOrder) {
	                    $NewChildren.Add($Key, $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Key)
	                }
	                
	                # Remove current child objects
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.Clear()
	                
	                # Add new children object
	                foreach ($Key in $NewChildren.Keys) {
	                    $script:AFObject.$STIG.$VulnID.$AnswerKeyName.Add($Key, $NewChildren.$Key)
	                }
	            }
	            elseif ($AnswerKeyName) {
	                # To preserve order, get the current order replacing the old key with new
	                $PreservedOrder = ($script:AFObject.$STIG.$VulnID.Keys) -replace $AnswerKeyName, $NewKeyName
	                
	                # Copy old key to new and then remove old key
	                $script:AFObject.$STIG.$VulnID.$NewKeyName = $script:AFObject.$STIG.$VulnID.$AnswerKeyName
	                $script:AFObject.$STIG.$VulnID.Remove($AnswerKeyName)
	                
	                # Create new children object after rename to preserve original order
	                $NewChildren = [ordered]@{ }
	                foreach ($Key in $PreservedOrder) {
	                    $NewChildren.Add($Key, $script:AFObject.$STIG.$VulnID.$Key)
	                }
	                
	                # Remove current child objects
	                $script:AFObject.$STIG.$VulnID.Clear()
	                
	                # Add new children object
	                foreach ($Key in $NewChildren.Keys) {
	                    $script:AFObject.$STIG.$VulnID.Add($Key, $NewChildren.$Key)
	                }
	            }
	            elseif ($VulnID) {
	                # To preserve order, get the current order replacing the old key with new
	                $PreservedOrder = ($script:AFObject.$STIG.Keys) -replace $VulnID, $NewKeyName
	                
	                # Copy old key to new and then remove old key
	                $script:AFObject.$STIG.$NewKeyName = $script:AFObject.$STIG.$VulnID
	                $script:AFObject.$STIG.Remove($VulnID)
	                
	                # Create new children object after rename to preserve original order
	                $NewChildren = [ordered]@{ }
	                foreach ($Key in $PreservedOrder) {
	                    $NewChildren.Add($Key, $script:AFObject.$STIG.$Key)
	                }
	                
	                # Remove current child objects
	                $script:AFObject.$STIG.Clear()
	                
	                # Add new children object
	                foreach ($Key in $NewChildren.Keys) {
	                    $script:AFObject.$STIG.Add($Key, $NewChildren.$Key)
	                }
	            }
	            elseif ($STIG) {
	                # Copy old key to new and then remove old key
	                $script:AFObject.$NewKeyName = $script:AFObject.$STIG
	                $script:AFObject.Remove($STIG)
	            }
	        }
	        "Reorder" {
	            # Reorder Index
	            foreach ($Index in $IndexOrder) {
	                # Get the Index data
	                $IndexData = $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index
	                
	                # Remove the Index from $AFObject
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.Remove($Index)
	                
	                # Add the stored index data (places at bottom given $AnswerKeyName is an ordered hashtable)
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index = $IndexData
	            }
	        }
	        "Update" {
	            if ("VulnIDComment" -in $PSBoundParameters.Keys) {
	                $script:AFObject.$STIG.$VulnID._Comment = $VulnIDComment
	            }
	            elseif ("AnswerKeyNameComment" -in $PSBoundParameters.Keys) {
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName._Comment = $AnswerKeyNameComment
	            }
	            elseif ("IndexComment" -in $PSBoundParameters.Keys) {
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index._Comment = $IndexComment
	            }
	            elseif ("ExpectedStatus" -in $PSBoundParameters.Keys) {
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index.ExpectedStatus = (Convert-Status -InputObject $ExpectedStatus -Output $StatusFormat)
	            }
	            elseif ("Hostname" -in $PSBoundParameters.Keys) {
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index.Hostname = $Hostname
	            }
	            elseif ("Instance" -in $PSBoundParameters.Keys) {
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index.Instance = $Instance
	            }
	            elseif ("Database" -in $PSBoundParameters.Keys) {
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index.Database = $Database
	            }
	            elseif ("Site" -in $PSBoundParameters.Keys) {
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index.Site = $Site
	            }
	            elseif ("ResultHash" -in $PSBoundParameters.Keys) {
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index.ResultHash = $ResultHash
	            }
	            elseif ("ValidationCode" -in $PSBoundParameters.Keys) {
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index.ValidationCode = $ValidationCode
	            }
	            elseif ("ValidTrueStatus" -in $PSBoundParameters.Keys) {
	                if ($comboboxAF_ValidTrueStatus.SelectedItem -notin @($null, "")) {
	                    $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index.ValidTrueStatus = (Convert-Status -InputObject $ValidTrueStatus -Output $StatusFormat)
	                }
	                else {
	                    $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index.ValidTrueStatus = ""
	                }
	            }
	            elseif ("ValidTrueComment" -in $PSBoundParameters.Keys) {
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index.ValidTrueComment = $ValidTrueComment
	            }
	            elseif ("ValidFalseStatus" -in $PSBoundParameters.Keys) {
	                if ($comboboxAF_ValidFalseStatus.SelectedItem -notin @($null, "")) {
	                    $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index.ValidFalseStatus = (Convert-Status -InputObject $ValidFalseStatus -Output $StatusFormat)
	                }
	                else {
	                    $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index.ValidFalseStatus = ""
	                }
	            }
	            elseif ("ValidFalseComment" -in $PSBoundParameters.Keys) {
	                $script:AFObject.$STIG.$VulnID.$AnswerKeyName.$Index.ValidFalseComment = $ValidFalseComment
	            }
	        }
	    }
	}
	
	function Update-PreferencesTab {
	    # Remove change event handlers
	    foreach ($GroupBox in @($groupboxPref_EvaluateSTIG, $groupboxPref_OutputPayload, $groupboxPref_STIGManager, $groupboxPref_Splunk, $groupboxPref_ManageAnswerFiles)) {
	        foreach ($Control in $GroupBox.Controls) {
	            switch ($Control.GetType().Name) {
	                'TextBox'       {
	                    $Control.remove_TextChanged($onChange)
	                }
	                'CheckBox'      {
	                    $Control.remove_CheckedChanged($onChange)
	                }
	                'ComboBox'      {
	                    $Control.remove_SelectedIndexChanged($onChange)
	                }
	            }
	        }
	    }
	    
	    # Clear STIGMan and Splunk listbox selected items
	    $listboxPref_SM_SMImport_COLLECTION.SelectedItems.Clear()
	    $listboxPref_SK_Splunk_HECName.SelectedItems.Clear()
	    
	    # Update EvaluateSTIG groupbox controls
	    $ControlsToUpdate = $groupboxPref_EvaluateSTIG.Controls | Where-Object { $_.GetType().Name -in @("ComboBox", "NumericUpDown", "TextBox") }
	    foreach ($Key in @($script:PrefsObj.EvaluateSTIG.Keys)) {
	        $Control = $ControlsToUpdate | Where-Object { ($_.Name -split "Pref_ES_")[1] -eq $Key }
	        switch ($Control.GetType().Name) {
	            "ComboBox" {
	                if ($Key -in @("SMCollection", "SplunkHECName")) {
	                    Update-ComboBox -ComboBox $Control -Items ""
	                    switch ($Key) {
	                        "SMCollection" {
	                            foreach ($Item in $script:PrefsObj.STIGManager.Keys | Where-Object { $_ -notin @("SMImport_API_BASE", "SMImport_AUTHORITY") }) {
	                                if ($Item -notin @($Control.Items)) {
	                                    Update-ComboBox -ComboBox $Control -Items $Item -Append
	                                }
	                            }
	                        }
	                        "SplunkHECName" {
	                            foreach ($Item in $script:PrefsObj.Splunk.Keys | Where-Object { $_ -notin @("Splunk_URI") }) {
	                                if ($Item -notin @($Control.Items)) {
	                                    Update-ComboBox -ComboBox $Control -Items $Item -Append
	                                }
	                            }
	                        }
	                    }
	                    $Control.SelectedItem = $script:PrefsObj.EvaluateSTIG.$Key
	                }
	                else {
	                    $Control.SelectedItem = $script:PrefsObj.EvaluateSTIG.$Key
	                }
	            }
	            "NumericUpDown" {
	                $Control.Value = $script:PrefsObj.EvaluateSTIG.$Key
	            }
	            "TextBox" {
	                $Control.Text = $script:PrefsObj.EvaluateSTIG.$Key
	            }
	        }
	    }
	    
	    # Update OutputPayload groupbox controls
	    foreach ($Key in $script:PrefsObj.OutputPayload.Keys) {
	        $Control = $groupboxPref_OutputPayload.Controls | Where-Object { $_.GetType().Name -in @("ComboBox") -and ($_.Name -split "Pref_OP_")[1] -eq $Key }
	        switch ($Control.GetType().Name) {
	            "ComboBox" {
	                $Control.SelectedItem = $script:PrefsObj.OutputPayload.$Key
	            }
	        }
	    }
	    
	    # Update STIGManager groupbox controls
	    $listboxPref_SM_SMImport_COLLECTION.Items.Clear()
	    foreach ($Key in $script:PrefsObj.STIGManager.Keys) {
	        if ($Key -in @("SMImport_API_BASE", "SMImport_AUTHORITY")) {
	            $Control = $groupboxPref_STIGManager.Controls | Where-Object { $_.GetType().Name -in @("TextBox") -and ($_.Name -split "Pref_SM_")[1] -eq $Key }
	            $Control.Text = $script:PrefsObj.STIGManager.$Key
	        }
	        else {
	            if ($Key -eq "") {
	                $Key = "<placeholder>"
	            }
	            Update-ListBox -ListBox $listboxPref_SM_SMImport_COLLECTION -Items $Key -Append
	        }
	    }
	    $listboxPref_SM_SMImport_COLLECTION.Sorted = $true
	    
	    # Update Splunk groupbox controls
	    $listboxPref_SK_Splunk_HECName.Items.Clear()
	    foreach ($Key in $script:PrefsObj.Splunk.Keys) {
	        if ($Key -in @("Splunk_URI")) {
	            $Control = $groupboxPref_Splunk.Controls | Where-Object { $_.GetType().Name -in @("TextBox") -and ($_.Name -split "Pref_SK_")[1] -eq $Key }
	            $Control.Text = $script:PrefsObj.Splunk.$Key
	        }
	        else {
	            if ($Key -eq "") {
	                $Key = "<placeholder>"
	            }
	            Update-ListBox -ListBox $listboxPref_SK_Splunk_HECName -Items $Key -Append
	        }
	    }
	    $listboxPref_SK_Splunk_HECName.Sorted = $true
	    
	    # Update ManageAnswerFiles groupbox controls
	    foreach ($Key in $script:PrefsObj.ManageAnswerFiles.Keys) {
	        $Control = $groupboxPref_ManageAnswerFiles.Controls | Where-Object { $_.GetType().Name -in @("ComboBox", "TextBox") -and ($_.Name -split "Pref_AF_")[1] -eq $Key }
	        switch ($Control.GetType().Name) {
	            "ComboBox" {
	                $Control.SelectedItem = $script:PrefsObj.ManageAnswerFiles.$Key
	            }
	            "TextBox" {
	                $Control.Text = $script:PrefsObj.ManageAnswerFiles.$Key
	            }
	        }
	    }
	    
	    # Add change event handlers
	    foreach ($GroupBox in @($groupboxPref_EvaluateSTIG, $groupboxPref_OutputPayload, $groupboxPref_STIGManager, $groupboxPref_Splunk, $groupboxPref_ManageAnswerFiles)) {
	        foreach ($Control in $GroupBox.Controls) {
	            switch ($Control.GetType().Name) {
	                'TextBox'       {
	                    $Control.add_TextChanged($onChange)
	                }
	                'CheckBox'      {
	                    $Control.add_CheckedChanged($onChange)
	                }
	                'ComboBox'      {
	                    $Control.add_SelectedIndexChanged($onChange)
	                }
	            }
	        }
	    }
	}
	
	function Save-PreferencesObject {
	    param (
	        [Parameter(Mandatory = $true)]
	        [psobject]$PrefObject
	    )
	    
	    # ==========================================================
	    # Begin Write XML
	    # ==========================================================
	    $STIG = $AFObject.Keys | Select-Object -First 1
	    $Encoding = [System.Text.Encoding]::UTF8
	    $XmlWriter = New-Object System.Xml.XmlTextWriter((Join-Path -Path $script:ESPath -ChildPath Preferences.xml), $Encoding)
	    $XmlWriter.Formatting = "Indented"
	    $XmlWriter.Indentation = 2
	    
	    $XmlWriter.WriteStartDocument()
	    
	    # Add Comment section
	    $XmlWriter.WriteComment('Evaluate-STIG Preferences')
	    
	    # Create Preferences node
	    $XmlWriter.WriteStartElement("Preferences")
	    
	    # Create EvaluateSTIG node
	    $XmlWriter.WriteStartElement("EvaluateSTIG")
	    $XmlWriter.WriteComment('*************************************************************************************
        The following Evaluate-STIG parameters may be configured to customize your scan.
        Any parameter called out on the command line will override the same parameter configured
        here.

          ScanType                "Unclassified" or "Classified". [default: "Unclassified"]
          Marking                 Text to add to Marking field in STIG Viewer. [default: blank]
          TargetComments          Text to add to Target Comments field in STIG Viewer. [default: blank]
          VulnTimeout             Maximum time in minutes to allow a single check to run. [default: "15"]
          FileSearchTimeout       Maximum time in minutes to allow a file type searching to run. [default: "240"]
          AnswerKey               Answer Key to use from answer files [default: "DEFAULT"]
          AFPath                  Alternate path to search for answer files. [default: blank]
          Output                  "Console"|"CKL"|"CKLB"|"CSV"|"XCCDF"|"CombinedCKL"|"CombinedCKLB"|"CombinedCSV"|"OQE"|"Summary"|"STIGManager"|"Splunk". Use comma separation for multiple. If none, output to console. [default: "Console"]
          JSON                    "true" or "false". [default: "false"] Output Console Object in JSON Format using OutputPayload Options
          OutputPath              Alternate path to save results. [default: blank]
          PreviousToKeep          If -Output is outputting files, maximum number of previous scan results to retain. [default: "1"]
          AllowDeprecated         "true" or "false". [default: "false"]
          AllowSeverityOverride   "true" or "false". [default: "false"]
          ExcludeSTIG             Shortname(s) of STIGs to exclude from scan. Use comma separation to specify multple. [default: blank]
          ExcludeVuln             Vuln IDs (V-1234 format) to exclude from scan. Use comma separation to specify multple. [default: blank]
          ApplyTattoo             "true" or "false". [default: "false"]
          SMCollection            STIG Manager Collection name to use from STIGManager section in this file. [default: blank]
          SplunkHECName           Name for the HTTP Event Collector token to use from Splunk section in this file. [default: blank]
        **************************************************************************************')
	    
	    # Create EvaluateSTIG subnodes
	    foreach ($Key in $script:PrefsObj.EvaluateSTIG.Keys) {
	        $XmlWriter.WriteStartElement($Key)
	        if ($script:PrefsObj.EvaluateSTIG.$($Key) -notin @($null, "")) {
	            $XmlWriter.WriteString($script:PrefsObj.EvaluateSTIG.$($Key))
	        }
	        else {
	            $XmlWriter.WriteWhitespace("")
	        }
	        $XmlWriter.WriteFullEndElement()
	    }
	    # Close EvaluateSTIG node
	    $XmlWriter.WriteEndElement()
	    
	    # Create OutputPayload node
	    $XmlWriter.WriteStartElement("OutputPayload")
	    $XmlWriter.WriteComment('*************************************************************************************
        Enable/disable fields to be output when using -Output CSV|CombinedCSV|Splunk or -JSON.
        All are boolean and must be lowercase "true" or "false".
        If -OutputPayload is called on the command line, these values are ignored.
        **************************************************************************************')
	    
	    # Create OutputPayload subnodes
	    foreach ($Key in $script:PrefsObj.OutputPayload.Keys) {
	        $XmlWriter.WriteStartElement($Key)
	        if ($script:PrefsObj.OutputPayload.$($Key) -notin @($null, "")) {
	            $XmlWriter.WriteString($script:PrefsObj.OutputPayload.$($Key))
	        }
	        else {
	            $XmlWriter.WriteWhitespace("")
	        }
	        $XmlWriter.WriteFullEndElement()
	    }
	    # Close OutputPayload node
	    $XmlWriter.WriteEndElement()
	    
	    # Create STIGManager node
	    $XmlWriter.WriteStartElement("STIGManager")
	    $XmlWriter.WriteComment('*************************************************************************************
        STIG Manager

        https://stig-manager.readthedocs.io/en/latest/index.html
        https://github.com/NUWCDIVNPT/stigman-watcher

        "SMImport" emulates STIGMAN Watcher one-shot functionality

        SMImport_API_BASE=             Required. Base URL of the STIG Manager API service. The default value is your STIGManager instances'' FQDN with "/api" appended. This is defined within your STIG Manager''s settings via "STIGMAN_CLIENT_API_BASE".
        SMImport_AUTHORITY=            Required. Base URL of the OIDC authentication service that issues OAuth2 tokens for the API. This should match the value set for "STIGMAN_CLIENT_OIDC_PROVIDER" within STIG Manager''s configuration.
          SMImport_COLLECTION Name=      Required. Name for the SMImport collection settings section that is called from "-SMCollection". Recommend this match your collection name within STIG Manager. Multiple SMImport_COLLECTION sections may be configured.
          SMImport_CLIENT_ID=          Required. OIDC clientId to authenticate. This should be created within your STIG Manager''s backend OIDC Provider. The default provider used by STIG Manager is KeyCloak, though your configuration may vary.
          SMImport_CLIENT_CERT=        Required. Filename of PEM encoded client certificate. An unencrypted private key may be included within this file so that you do not have to pass "-SMPassphrase", though this configuration is not recommended. File must exist in Certificates directory.
          SMImport_CLIENT_CERT_KEY=    * Filename of PEM encoded encrypted private key. Required if SM_Import_CLIENT_CERT does not contain a plaintext private key. File must exist in Certificates directory.
          SMImport_COLLECTION_ID=      Required. The collectionID of your desired collection. This can be found by a user with Manage permissions on the collection. After selecting to manage the collection, reference the "ID" value in the Collection Properties window.

        * Note: Defining SMImport_CLIENT_CERT_KEY will require the use of the "-SMPassphrase" parameter to decrypt the private key.

        EXAMPLE CONFIGURATION BELOW:

        <SMImport_API_BASE>https://my.stig.manager.mil/api</SMImport_API_BASE>
        <SMImport_AUTHORITY>https://my.stig.manager.mil/kc/realms/stigman</SMImport_AUTHORITY>
        <SMImport_COLLECTION Name="MyCollection">
          <SMImport_CLIENT_ID>evaluate-stig</SMImport_CLIENT_ID>
          <SMImport_CLIENT_CERT>evaluate-stig-crt.pem</SMImport_CLIENT_CERT>
          <SMImport_CLIENT_CERT_KEY>evaluate-stig-key.pem</SMImport_CLIENT_CERT_KEY>
          <SMImport_COLLECTION_ID>1</SMImport_COLLECTION>
        </SMImport_COLLECTION>

        This collection would be used when running:
        Evaluate-STIG.ps1 -Output STIGManager -SMCollection MyCollection -SMPassphrase <myDecryptionPasswordHere>

        **************************************************************************************')
	    
	    # Create STIGManager subnodes
	    foreach ($Key in $script:PrefsObj.STIGManager.Keys | Where-Object { $_ -in @("SMImport_API_BASE", "SMImport_AUTHORITY") }) {
	        $XmlWriter.WriteStartElement($Key)
	        if ($script:PrefsObj.STIGManager.$($Key) -notin @($null, "")) {
	            $XmlWriter.WriteString($script:PrefsObj.STIGManager.$($Key))
	        }
	        else {
	            $XmlWriter.WriteWhitespace("")
	        }
	        $XmlWriter.WriteFullEndElement()
	    }
	    # Create SMImport_COLLECTION nodes
	    if (($script:PrefsObj.STIGManager.Keys | Where-Object { $_ -notin @("SMImport_API_BASE", "SMImport_AUTHORITY") } | Measure-Object).Count -eq 0) {
	        # No Collection keys exist.  Create a blank placeholder to ensure schema adherence
	        $XmlWriter.WriteStartElement("SMImport_COLLECTION")
	        $XmlWriter.WriteAttributeString("Name", "")
	        foreach ($Item in @("SMImport_CLIENT_ID", "SMImport_CLIENT_CERT", "SMImport_CLIENT_CERT_KEY", "SMImport_COLLECTION_ID")) {
	            $XmlWriter.WriteStartElement($Item)
	            $XmlWriter.WriteWhitespace("")
	            # Close $Item node
	            $XmlWriter.WriteFullEndElement()
	        }
	        # Close SMImport_COLLECTION node
	        $XmlWriter.WriteFullEndElement()
	    }
	    else {
	        foreach ($Key in $script:PrefsObj.STIGManager.Keys | Where-Object { $_ -notin @("SMImport_API_BASE", "SMImport_AUTHORITY") } | Sort-Object) {
	            $XmlWriter.WriteStartElement("SMImport_COLLECTION")
	            $XmlWriter.WriteAttributeString("Name", $Key)
	            # Create Collection subnodes
	            foreach ($SubKey in $script:PrefsObj.STIGManager.$($Key).Keys) {
	                $XmlWriter.WriteStartElement($SubKey)
	                if ($script:PrefsObj.STIGManager.$($Key).$($SubKey) -notin @($null, "")) {
	                    $XmlWriter.WriteString($script:PrefsObj.STIGManager.$($Key).$($SubKey))
	                }
	                else {
	                    $XmlWriter.WriteWhitespace("")
	                }
	                # Close subnode
	                $XmlWriter.WriteFullEndElement()
	            }
	            # Close SMImport_COLLECTION node
	            $XmlWriter.WriteFullEndElement()
	        }
	    }
	    # Close STIGManager node
	    $XmlWriter.WriteEndElement()
	    
	    # Create Splunk node
	    $XmlWriter.WriteStartElement("Splunk")
	    $XmlWriter.WriteComment('*************************************************************************************
        Splunk

        Splunk_URI=               Required. Base URL of the Splunk instance. The default value is your Splunk instances'' FQDN, port 8088, with "/services/collector/event" appended.
          Splunk_HECName Name=      Required. Name for the HTTP Event Collector token. Multiple Splunk_HECName sections may be configured.
          Splunk_token=           Required. HEC Token value. This should be created within your Splunk instance.
          Splunk_index=           Optional. The name of the index by which the event data is to be indexed. The index you specify here must be within the list of allowed indexes if the token has the indexes parameter set.
          Splunk_source=          Optional. The source value to assign to the event data.
          Splunk_sourcetype=      Optional. The sourcetype value to assign to the event data.

          EXAMPLE CONFIGURATION BELOW:

          <Splunk_URI>https://my.splunk.mil:8088/services/collector/event</Splunk_URI>
          <Splunk_HECName Name="MyHECName">
          <Splunk_token>1cea9f66-a7c9-4fcd-a20f-0b2c17d5d426</Splunk_token>
          <Splunk_index>es_events</Splunk_index>
          <Splunk_source>evaluate-stig</Splunk_source>
          <Splunk_sourcetype>weekly_scan</Splunk_sourcetype>
          </Splunk_HECName>

          This HECName would be used when running:
          Evaluate-STIG.ps1 -Output Splunk -SplunkHECName MyHECName

        	**************************************************************************************')
	    
	    # Create Splunk subnodes
	    foreach ($Key in $script:PrefsObj.Splunk.Keys) {
	        if ($Key -in @("Splunk_URI")) {
	            $XmlWriter.WriteStartElement($Key)
	            if ($script:PrefsObj.Splunk.$($Key) -notin @($null, "")) {
	                $XmlWriter.WriteString($script:PrefsObj.Splunk.$($Key))
	            }
	            else {
	                $XmlWriter.WriteWhitespace("")
	            }
	            $XmlWriter.WriteFullEndElement()
	        }
	    }
	    if (($script:PrefsObj.Splunk.Keys | Where-Object { $_ -notin @("Splunk_URI") } | Measure-Object).Count -eq 0) {
	        # No HECName keys exist.  Create a blank placeholder to ensure schema adherence
	        $XmlWriter.WriteStartElement("Splunk_HECName")
	        $XmlWriter.WriteAttributeString("Name", "")
	        foreach ($Item in @("Splunk_token", "Splunk_index", "Splunk_source", "Splunk_sourcetype")) {
	            $XmlWriter.WriteStartElement($Item)
	            $XmlWriter.WriteWhitespace("")
	            # Close $Item node
	            $XmlWriter.WriteFullEndElement()
	        }
	        # Close Splunk_HECName node
	        $XmlWriter.WriteFullEndElement()
	    }
	    else {
	        foreach ($Key in $script:PrefsObj.Splunk.Keys | Where-Object { $_ -notin @("Splunk_URI") } | Sort-Object) {
	            # Create Splunk_HECName node
	            $XmlWriter.WriteStartElement("Splunk_HECName")
	            $XmlWriter.WriteAttributeString("Name", $Key)
	            # Create Collection subnodes
	            foreach ($SubKey in $script:PrefsObj.Splunk.$($Key).Keys) {
	                $XmlWriter.WriteStartElement($SubKey)
	                if ($script:PrefsObj.Splunk.$($Key).$($SubKey) -notin @($null, "")) {
	                    $XmlWriter.WriteString($script:PrefsObj.Splunk.$($Key).$($SubKey))
	                }
	                else {
	                    $XmlWriter.WriteWhitespace("")
	                }
	                # Close subnode
	                $XmlWriter.WriteFullEndElement()
	            }
	            # Close Splunk_HECName node
	            $XmlWriter.WriteFullEndElement()
	        }
	    }
	    # Close Splunk node
	    $XmlWriter.WriteEndElement()
	    
	    # Create ManageAnswerFiles node
	    $XmlWriter.WriteStartElement("ManageAnswerFiles")
	    
	    # Create ManageAnswerFiles subnodes
	    foreach ($Key in $script:PrefsObj.ManageAnswerFiles.Keys) {
	        $XmlWriter.WriteStartElement($Key)
	        if ($script:PrefsObj.ManageAnswerFiles.$($Key) -notin @($null, "")) {
	            $XmlWriter.WriteString($script:PrefsObj.ManageAnswerFiles.$($Key))
	        }
	        else {
	            $XmlWriter.WriteWhitespace("")
	        }
	        $XmlWriter.WriteFullEndElement()
	    }
	    # Close ManageAnswerFiles node
	    $XmlWriter.WriteEndElement()
	    
	    # Close Preferences node
	    $XmlWriter.WriteEndElement()
	    
	    $XmlWriter.WriteEnddocument()
	    $XmlWriter.Flush()
	    $XmlWriter.Close()
	}
	
	function Write-ViewVulnData {
	    param (
	        [Parameter(Mandatory = $false)]
	        [psobject]$Line,
	        
	        [Parameter(Mandatory = $false)]
	        [Switch]$AsBold,
	        
	        [Parameter(Mandatory = $false)]
	        [Switch]$AddCRLF
	    )
	    
	    if ($AsBold) {
	        $VulnData_AF_RichTextBox.SelectionFont = New-Object System.Drawing.Font($VulnData_AF_RichTextBox.Font.FontFamily, $VulnData_AF_RichTextBox.Font.Size, [System.Drawing.FontStyle]::Bold)
	    }
	    else {
	        $VulnData_AF_RichTextBox.SelectionFont = New-Object System.Drawing.Font($VulnData_AF_RichTextBox.Font.FontFamily, $VulnData_AF_RichTextBox.Font.Size, [System.Drawing.FontStyle]::Regular)
	    }
	    
	    $VulnData_AF_RichTextBox.AppendText($Line)
	    
	    if ($AddCRLF) {
	        $VulnData_AF_RichTextBox.AppendText("`r`n")
	    }
	}
