	$textboxSMPassphrase_TextChanged = {
	    # Store the current selection start and length to maintain cursor position
	    $selectionStart = $textboxSMPassphrase.SelectionStart
	    $selectionLength = $textboxSMPassphrase.SelectionLength
	    
	    # Remove all space characters from the text
	    $newText = $textboxSMPassphrase.Text -replace '\s', ''
	    
	    # If the text has changed (meaning spaces were removed), update the textbox
	    if ($newText -ne $textboxSMPassphrase.Text) {
	        $textboxSMPassphrase.Text = $newText
	        
	        # Adjust cursor position after text modification
	        if ($selectionStart -gt $textboxSMPassphrase.Text.Length) {
	            $textboxSMPassphrase.SelectionStart = $textboxSMPassphrase.Text.Length
	        }
	        else {
	            $textboxSMPassphrase.SelectionStart = $selectionStart
	        }
	        $textboxSMPassphrase.SelectionLength = $selectionLength
	    }
	    
	    Get-Arguments
	}
	
