	$checkboxAllowDeprecated_CheckedChanged = {
	    if (-Not ($checkboxAllowDeprecated.Checked)) {
	        # Update SelectSTIG listbox to remove deprecated STIGs
	        if ($textboxSelectSTIG.Text -notin @($null, "")) {
	            $SelectedSTIGs = $textboxSelectSTIG.Text -split ","
	            $RefreshedSelectedSTIGs = @()
	            foreach ($Item in $SelectedSTIGs) {
	                if ($Item -notin ($script:STIGListObj | Where-Object DisaStatus -eq "Deprecated").ShortName) {
	                    $RefreshedSelectedSTIGs += $Item
	                }
	            }
	            $textboxSelectSTIG.Text = $RefreshedSelectedSTIGs -join ","
	        }
	        
	        # Update ExcludeSTIG listbox to remove deprecated STIGs
	        if ($textboxExcludeSTIG.Text -notin @($null, "")) {
	            $SelectedSTIGs = $textboxExcludeSTIG.Text -split ","
	            $RefreshedSelectedSTIGs = @()
	            foreach ($Item in $SelectedSTIGs) {
	                if ($Item -notin ($script:STIGListObj | Where-Object DisaStatus -eq "Deprecated").ShortName) {
	                    $RefreshedSelectedSTIGs += $Item
	                }
	            }
	            $textboxExcludeSTIG.Text = $RefreshedSelectedSTIGs -join ","
	        }
	        
	        # Update ForceSTIG listbox to remove deprecated STIGs
	        if ($textboxForceSTIG.Text -notin @($null, "")) {
	            $SelectedSTIGs = $textboxForceSTIG.Text -split ","
	            $RefreshedSelectedSTIGs = @()
	            foreach ($Item in $SelectedSTIGs) {
	                if ($Item -notin ($script:STIGListObj | Where-Object DisaStatus -eq "Deprecated").ShortName) {
	                    $RefreshedSelectedSTIGs += $Item
	                }
	            }
	            $textboxForceSTIG.Text = $RefreshedSelectedSTIGs -join ","
	        }
	    }
	    
	    Get-Arguments
	}
	
	$checkboxSelectSTIG_CheckedChanged = {
	    if ($checkboxSelectSTIG.Checked) {
	        $checkboxExcludeSTIG.Checked = $false # Uncheck ExcludeSTIG.  Only SelectSTIG OR ExcludeSTIG may be selected - not both.
	        Set-ParamControlState -ParamControl SelectSTIG -Enabled $true
	        if ($textboxSelectSTIG.Text -notin @($null, "")) {
	            # Disable ApplyTattoo as it's ignored when using SelectSTIG
	            Set-ParamControlState -ParamControl ApplyTattoo -Enabled $false
	
	            $SelectedSTIGs = $textboxSelectSTIG.Text -split ","
	            # Set SelectVuln control state
	            $checkboxSelectVuln.Enabled = $true
	            if ($checkboxSelectVuln.Checked) {
	                $SelectVulnEnabled = $true
	            }
	            else {
	                $SelectVulnEnabled = $false
	            }
	            Set-ParamControlState -ParamControl SelectVuln -Enabled $SelectVulnEnabled
	            
	            # Set ExcludeVuln control state
	            $checkboxExcludeVuln.Enabled = $true
	            if ($checkboxExcludeVuln.Checked) {
	                $ExcludeVulnEnabled = $true
	            }
	            else {
	                $ExcludeVulnEnabled = $false
	            }
	            Set-ParamControlState -ParamControl ExcludeVuln -Enabled $ExcludeVulnEnabled
	        }
	        else {
	            Set-ParamControlState -ParamControl SelectVuln -Enabled $false
	            Set-ParamControlState -ParamControl ExcludeVuln -Enabled $false
	        }
	    }
	    else {
	        Set-ParamControlState -ParamControl SelectSTIG -Enabled $false
	        
	        # Enable ApplyTattoo
	        Set-ParamControlState -ParamControl ApplyTattoo -Enabled $true
	        
	        $checkboxSelectVuln.Enabled = $false
	        Set-ParamControlState -ParamControl SelectVuln -Enabled $false
	        
	        $checkboxExcludeVuln.Enabled = $false
	        Set-ParamControlState -ParamControl ExcludeVuln -Enabled $false
	    }
	    
	    Get-Arguments
	}
	
	$buttonSelectEdit_Click = {
	    $SourceList = @()
	    # Get STIGs based on context
	    if ($radiobuttonCiscoConfig.Enabled -and $radiobuttonCiscoConfig.Checked) {
	        $PlatformSTIGs = $script:STIGListObj | Where-Object {$_.AssetType -eq "Cisco" -and $_.Support -eq "EvalSTIG"}
	    }
	    else {
	        $PlatformSTIGs = $script:STIGListObj | Where-Object {$_.AssetType -ne "Cisco" -and $_.Support -eq "EvalSTIG"}
	    }
	    
	    # Add active STIGs
	    foreach ($Item in ($PlatformSTIGs | Where-Object DisaStatus -ne "Deprecated")) {
	        $SourceList += $Item.ShortName
	    }
	    
	    if ($checkboxAllowDeprecated.Checked) {
	        # Add deprecated STIGs
	        foreach ($Item in ($PlatformSTIGs | Where-Object DisaStatus -eq "Deprecated")) {
	            $SourceList += $Item.ShortName
	        }
	    }
	
	    # Sort current SourceList
	    $SourceList = $SourceList | Sort-Object
	    
	    if ($script:STIGListObj | Where-Object Support -eq "Manual") {
	        # Add manual STIGs last to ensure they are listed last
	        foreach ($Item in ($script:STIGListObj | Where-Object Support -eq "Manual" | Sort-Object ShortName)) {
	            $SourceList += $Item.ShortName
	        }
	    }
	    $CurrentList = $textboxSelectSTIG.Text -split ","
	    
	    if ((Show-ListboxCustomSort_psf -FormTitle "Edit -SelectSTIG" -SourceList $SourceList -CurrentList $CurrentList) -eq 'OK') {
	        if (($script:SortedListboxOutput | Measure-Object).Count -gt 0) {
	            $textboxSelectSTIG.Text = ($script:SortedListboxOutput | Sort-Object) -join ","
	            
	            # Disable ApplyTattoo as it's ignored when using SelectSTIG
	            Set-ParamControlState -ParamControl ApplyTattoo -Enabled $false
	            
	            # Set SelectVuln control state
	            $checkboxSelectVuln.Enabled = $true
	            if ($checkboxSelectVuln.Checked) {
	                $SelectVulnEnabled = $true
	            }
	            else {
	                $SelectVulnEnabled = $false
	            }
	            Set-ParamControlState -ParamControl SelectVuln -Enabled $SelectVulnEnabled
	            
	            # Set ExcludeVuln control state
	            $checkboxExcludeVuln.Enabled = $true
	            if ($checkboxExcludeVuln.Checked) {
	                $ExcludeVulnEnabled = $true
	            }
	            else {
	                $ExcludeVulnEnabled = $false
	            }
	            Set-ParamControlState -ParamControl ExcludeVuln -Enabled $ExcludeVulnEnabled
	        }
	        else {
	            $checkboxSelectSTIG.Checked = $false
	            $textboxSelectSTIG.Text = ""
	        }
	        
	        Test-OutputTypes
	        Get-Arguments
	    }
	}
	
