	$buttonRemoteConfigImport_Click = {
	    if ($radiobuttonComputerName.Checked) {
	        $BrowserTitle = "Select files containing computer names:"
	        
	        $SelectedFiles = Invoke-FileBrowser -Action Open -Title $BrowserTitle -AllowMultiSelect -Filter "Text files (*.txt)|*.txt"
	        if ($SelectedFiles) {
	            $ValidEntries = @()
	            $InvalidEntries = @()
	            foreach ($File in $SelectedFiles) {
	                $Invalid = $false
	                foreach ($Line in (Get-Content -Path $File)) {
	                    if ($Line.Trim() -in @($null, "") -or $Line.Trim() -match "\s") {
	                        $Invalid = $true
	                    }
	                    else {
	                        $ValidEntries += $Line.Trim()
	                    }
	                }
	                if ($Invalid) {
	                    $InvalidEntries += $File
	                }
	            }
	            
	            if (($ValidEntries | Measure-Object).Count -gt 0) {
	                foreach ($Item in ($ValidEntries | Select-Object -Unique)) {
	                    if ($Item -notin $listboxRemote.Items) {
	                        $listboxRemote.Items.Add($Item)
	                        $Index = $listboxRemote.FindStringExact($Item)
	                        $listboxRemote.SetSelected($Index, $true)
	                    }
	                    
	                }
	                $listboxRemote.Sorted = $true
	            }
	            
	            if (($InvalidEntries | Measure-Object).Count -gt 0) {
	                $ErrMsg = "Invalid entries detected in files:`r`n"
	                $ErrMsg += $InvalidEntries -join "`r`n"
	                [System.Windows.Forms.MessageBox]::Show($ErrMsg, 'Warning', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning)
	            }
	        }
	    }
	    elseif ($radiobuttonCiscoConfig.Checked) {
	        $BrowserTitle = "Select folder containing Cisco config files:"
	        
	        $SelectedFolder = Invoke-FolderBrowser -Description $BrowserTitle
	        if ($SelectedFolder) {
	            if ($SelectedFolder -notin $listboxRemote.Items) {
	                $listboxRemote.Items.Add($SelectedFolder)
	                $Index = $listboxRemote.FindStringExact($SelectedFolder)
	                $listboxRemote.SetSelected($Index, $true)
	            }
	            
	            $listboxRemote.Sorted = $true
	        }
	    }
	}
	
