	$comboboxAF_FormatStatus_SelectedIndexChanged = {
	    if ($listboxAF_Index.SelectedItem -notin @($null, "")) {
	        # Get current Status values
	        $SelectedExpectedStatus = $comboboxAF_ExpectedStatus.SelectedItem
	        $SelectedValidTrueStatus = $comboboxAF_ValidTrueStatus.SelectedItem
	        $SelectedValidFalseStatus = $comboboxAF_ValidFalseStatus.SelectedItem
	    }
	    
	    # Update valid Status entries
	    foreach ($Obj in @($comboboxAF_ExpectedStatus, $comboboxAF_ValidTrueStatus, $comboboxAF_ValidFalseStatus)) {
	        $Obj.Items.Clear()
	        switch ($Obj) {
	            $comboboxAF_ExpectedStatus {
	                foreach ($Status in $script:ValidStatus) {
	                    Update-ComboBox -ComboBox $Obj -Items (Convert-Status -InputObject $Status -Output $comboboxAF_FormatStatus.SelectedItem) -Append
	                }
	            }
	            default {
	                Update-ComboBox -ComboBox $Obj -Items ""
	                foreach ($Status in $script:ValidStatus) {
	                    Update-ComboBox -ComboBox $Obj -Items (Convert-Status -InputObject $Status -Output $comboboxAF_FormatStatus.SelectedItem) -Append
	                }
	            }
	        }
	    }
	    
	    # Reselect previous Status values
	    $comboboxAF_ExpectedStatus.SelectedItem = $SelectedExpectedStatus
	    $comboboxAF_ValidTrueStatus.SelectedItem = $SelectedValidTrueStatus
	    $comboboxAF_ValidFalseStatus.SelectedItem = $SelectedValidFalseStatus
	    
	    # Update configuration data fields
	    Update-AnswerDataFields -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem -Index $listboxAF_Index.SelectedItem
	}
	
	$textboxAF_DefaultAFKey_Validating = [System.ComponentModel.CancelEventHandler]{
