	$listboxAF_Content_MouseDoubleClick = [System.Windows.Forms.MouseEventHandler]{
	    # Double click listboxAF_VulnID invokes the buttonAF_OpenCreate click
	    if ($listboxAF_Content.SelectedIndex -ne -1) {
	        $buttonAF_OpenCreate_Click.Invoke($null, $null)
	    }
