	$buttonAF_OpenCreate_Click = {
	    if ($radiobuttonAF_DisplayXMLContent.Checked) {
	        Reset-AFConfiguredData
	        $Result = Test-XmlAgainstSchema -XmlFile (Join-Path -Path $textboxAF_AFPath.Text -ChildPath $listboxAF_Content.SelectedItem) -SchemaInput (Join-Path -Path $script:ESPath -ChildPath xml | Join-Path -ChildPath Schema_AnswerFile.xsd)
	        if ($Result -ne $true) {
	            [System.Windows.Forms.MessageBox]::Show("$($listboxAF_Content.SelectedItem) failed schema validation.", 'Error', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
	        }
	        else {
	            $script:AFXmlFile = Get-ChildItem -Path (Join-Path -Path $textboxAF_AFPath.Text -ChildPath $listboxAF_Content.SelectedItem)
	            $script:AFObject = Convert-AnswerFileToObject -XmlFile $script:AFXmlFile -StatusFormat $comboboxAF_FormatStatus.SelectedItem
	            $script:STIGName = $script:AFObject.Keys | Select-Object -First 1
	            $STIGContent = ($script:STIGListObj | Where-Object { $_.Name -eq $script:STIGName -or $_.ShortName -eq $script:STIGName }).StigContent
	            $textboxAF_STIGCommentsName.Text = $script:STIGName
	            if (-Not ($STIGContent)) {
	                [System.Windows.Forms.MessageBox]::Show("STIGComments Name not found in STIGList.xml.", 'Warning', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning)
	                $script:XccdfContent = ""
	            }
	            else {
	                switch (($script:STIGListObj | Where-Object { $_.Name -eq $script:STIGName -or $_.ShortName -eq $script:STIGName }).Support) {
	                    "EvalSTIG" {
	                        $script:XccdfFile = (Join-Path -Path $script:ESPath -ChildPath StigContent | Join-Path -ChildPath $(($script:STIGListObj | Where-Object { $_.Name -eq $script:STIGName -or $_.ShortName -eq $script:STIGName }).StigContent))
	                    }
	                    "Manual" {
	                        $script:XccdfFile = (Join-Path -Path $script:ESPath -ChildPath StigContent | Join-Path -ChildPath Manual | Join-Path -ChildPath $(($script:STIGListObj | Where-Object { $_.Name -eq $script:STIGName -or $_.ShortName -eq $script:STIGName }).StigContent))
	                    }
	                }
	                $script:XccdfContent = [XML](Get-Content -Path $script:XccdfFile -Raw)
	            }
	            $buttonAF_VulnIDAdd.Enabled = $true
	            foreach ($Item in ($script:AFObject.$($script:STIGName).Keys)) {
	                if ($Item -ne "_Comment") {
	                    Update-ListBox -ListBox $listboxAF_VulnID -Items $Item -Append
	                }
	            }
	            $listboxAF_VulnID.Sorted = $true
	            
	            if ($listboxAF_VulnID.Items.Count -eq 1) {
	                # Only one entry exists to select it to reduce unnecessary clicks
	                $listboxAF_VulnID.SelectedIndex = 0
	            }
	            
	            if ($listboxAF_Index.Items.Count -eq 1) {
	                # Only one entry exists to select it to reduce unnecessary clicks
	                $listboxAF_Index.SelectedIndex = 0
	            }
	        }
	    }
	    elseif ($radiobuttonAF_DisplaySTIGContent.Checked) {
	        switch (($script:STIGListObj | Where-Object { $_.ShortName -eq $listboxAF_Content.SelectedItem }).Support) {
	            "EvalSTIG" {
	                $script:XccdfFile = (Join-Path -Path $script:ESPath -ChildPath StigContent | Join-Path -ChildPath $(($script:STIGListObj | Where-Object { $_.ShortName -eq $listboxAF_Content.SelectedItem }).StigContent))
	            }
	            "Manual" {
	                $script:XccdfFile = (Join-Path -Path $script:ESPath -ChildPath StigContent | Join-Path -ChildPath Manual | Join-Path -ChildPath $(($script:STIGListObj | Where-Object { $_.ShortName -eq $listboxAF_Content.SelectedItem }).StigContent))
	            }
	        }
	        $script:XccdfContent = [XML](Get-Content -Path $script:XccdfFile -Raw)
	        $STIGData = Convert-XccdfToHashTable -InputObject $script:XccdfContent
	        
	        if ((Show-NewAnswerFile_psf -AFPath $textboxAF_AFPath.Text -ShortName $listboxAF_Content.SelectedItem -STIGData $STIGData -StatusFormat $comboboxAF_FormatStatus.SelectedItem) -eq 'OK') {
	            # Open the new answer file for editing
	            $radiobuttonAF_DisplayXMLContent.Checked = $true
	            $listboxAF_Content.SelectedItem = $script:NewFileName
	            $buttonAF_OpenCreate.PerformClick()
	        }
	    }
	}
	
	$buttonAF_View_Click = {
	    Show-ScriptOutput_psf -Content (Get-Content -Path (Join-Path -Path $textboxAF_AFPath.Text -ChildPath $listboxAF_Content.SelectedItem) -Raw) -ContentType AFView -Title $listboxAF_Content.SelectedItem
	}
	
	$buttonAF_Validate_Click = {
	    $TestResult = [ordered]@{ }
	    
	    foreach ($Item in $listboxAF_Content.SelectedItems) {
	        $Content = [ordered]@{
	            Result  = ""
	            Message = ""
	        }
	        # Check legacy schema first
	        $LegacyResult = Test-XmlAgainstSchema -XmlFile (Join-Path -Path $textboxAF_AFPath.Text -ChildPath $Item) -SchemaInput $script:LegacyAFSchema -IsSchemaString
	        if ($LegacyResult -eq $true) {
	            $Content.Result = "Failed"
	            $Content.Message = "Legacy answer file.  Please migrate with the 'Maintain' button."
	        }
	        else {
	            $Result = Test-XmlAgainstSchema -XmlFile (Join-Path -Path $textboxAF_AFPath.Text -ChildPath $Item) -SchemaInput (Join-Path -Path $script:ESPath -ChildPath xml | Join-Path -ChildPath Schema_AnswerFile.xsd)
	            if ($Result -eq $true) {
	                $Content.Result = "Passed"
	                $Content.Message = $Result.Message
	            }
	            else {
	                $Content.Result = "Failed"
	                $Content.Message = $Result.Message
	            }
	        }
	        $TestResult.Add($Item, $Content)
	    }
	    Show-ScriptOutput_psf -Content $TestResult -ContentType AFValidationOutput
	}
	
	$buttonAF_Maintain_Click = {
	    if ((Show-AF_Maintain_psf -AnswerFiles @($listboxAF_Content.SelectedItems) -AFPath $textboxAF_AFPath.Text -StatusFormat $comboboxAF_FormatStatus.SelectedItem) -eq 'OK') {
	        Reset-AFConfiguredData
	        $listboxAF_Content.SelectedItems.Clear()
	    }
	}
	
	$buttonAF_ExportHTML_Click = {
	    $ExportFilePath = Invoke-FileBrowser -Action Save -Title "Export File Name:" -InitialDirectory $script:AFReportPath -Filter "HTML files (*.html)|*.html" -FileName "ES_AnswerFile_Export_$(Get-Date -Format yyyyMMdd-HHmmss)"
	    if ($ExportFilePath) {
	        # Update $script:AFReportPath with chosen path
	        $script:AFReportPath = Split-Path -Path $ExportFilePath -Parent
	
	        # Create the export file
	        $ExportResult = Create-AnswerFileExport -SelectedItems $listboxAF_Content.SelectedItems -AFPath $textboxAF_AFPath.Text -ExportType HTML -OutFile $ExportFilePath
	        
	        # Display the log
	        Show-ScriptOutput_psf -Content $ExportResult -ContentType AFExport $ExportFilePath
	    }
	}
	
