	$textboxAF_STIGCommentsName_TextChanged = {
	    if ($textboxAF_STIGCommentsName.Text -notin @($null, "")) {
	        $groupboxAF_ConfiguredData.Enabled = $true
	    }
	    else {
	        $groupboxAF_ConfiguredData.Enabled = $false
	    }
	}
	
	$listboxAF_VulnID_SelectedIndexChanged = {
	    # Clear AnswerKeyName and Index listboxes and disable Attributes groupbox
	    $listboxAF_AnswerKeyName.Items.Clear()
	    $listboxAF_Index.Items.Clear()
	    $groupboxAF_Attributes.Enabled = $false
	    
	    Update-AnswerDataFields -Clear
	    if ($listboxAF_VulnID.SelectedItem -notin @($null, "")) {
	        # Disable all child Create|Update|Delete buttons
	        $buttonAF_AnswerKeyNameAdd.Enabled = $false
	        $buttonAF_AnswerKeyNameEdit.Enabled = $false
	        $buttonAF_AnswerKeyNameRemove.Enabled = $false
	        $buttonAF_IndexAdd.Enabled = $false
	        $buttonAF_IndexEdit.Enabled = $false
	        $buttonAF_IndexRemove.Enabled = $false
	        $buttonAF_IndexUp.Enabled = $false
	        $buttonAF_IndexDown.Enabled = $false
	        $buttonAF_ImportResult.Enabled = $false
	        
	        # Enable self View|Convert|Remove and first child Create buttons
	        $buttonVulnData.Enabled = $true
	        $buttonAF_VulnIDConvert.Enabled = $true
	        $buttonAF_VulnIDRemove.Enabled = $true
	        $buttonAF_AnswerKeyNameAdd.Enabled = $true
	        
	        # Get Vuln data for the selected item
	        $VulnData = $script:XccdfContent.Benchmark.Group | Where-Object { $_.id -eq $listboxAF_VulnID.SelectedItem -or $_.Rule.id -eq $listboxAF_VulnID.SelectedItem }
	        $VulnData_GroupID = ""
	        $VulnData_RuleID = ""
	        $VulnData_STIGID = ""
	        $VulnData_Severity = ""
	        $VulnData_GroupTitle = ""
	        $VulnData_RuleTitle = ""
	        $VulnData_Discussion = ""
	        $VulnData_CheckText = ""
	        $VulnData_FixText = ""
	        if ($VulnData) {
	            $VulnData_GroupID = ($VulnData.id).Trim()
	            $VulnData_RuleID = ($VulnData.Rule.id).Trim()
	            $VulnData_STIGID = ($VulnData.Rule.version).Trim()
	            switch ($VulnData.Rule.severity) {
	                "high" {
	                    $VulnData_Severity = "CAT I"
	                }
	                "medium" {
	                    $VulnData_Severity = "CAT II"
	                }
	                "low" {
	                    $VulnData_Severity = "CAT III"
	                }
	            }
	            $VulnData_GroupTitle = ($VulnData.title).Trim()
	            $VulnData_RuleTitle = ($VulnData.Rule.title).Trim()
	            $VulnData_Discussion = (($VulnData.Rule.description -split "<VulnDiscussion>")[1] -split "</VulnDiscussion>")[0] -split "`n"
	            $VulnData_CheckText = ($VulnData.Rule.check.'check-content').Trim() -split "`n"
	            $VulnData_FixText = ($VulnData.Rule.fixtext.'#text').Trim() -split "`n"
	        }
	        else {
	            $VulnData_GroupID = "Selected item not found in STIG"
	        }
	        
	        # Populate $VulnData_AF_RichTextBox
	        $VulnData_AF_RichTextBox.Clear()
	        #----------------------------------
	        # Append Group ID
	        Write-ViewVulnData -Line "Group ID:" -AsBold
	        Write-ViewVulnData -Line " $($VulnData_GroupID)" -AddCRLF
	        
	        # Append Rule ID
	        Write-ViewVulnData -Line "Rule ID:" -AsBold
	        Write-ViewVulnData -Line "  $($VulnData_RuleID)" -AddCRLF
	        
	        # Append STIG ID
	        Write-ViewVulnData -Line "STIG ID:" -AsBold
	        Write-ViewVulnData -Line "  $($VulnData_STIGID)" -AddCRLF
	        
	        # Append Severity
	        Write-ViewVulnData -Line "Severity:" -AsBold
	        Write-ViewVulnData -Line " $($VulnData_Severity)" -AddCRLF
	        
	        # Append Group Title
	        Write-ViewVulnData -Line "" -AddCRLF
	        Write-ViewVulnData -Line "Group Title:" -AsBold
	        Write-ViewVulnData -Line " $($VulnData_GroupTitle)" -AddCRLF
	        
	        # Append Rule Title
	        Write-ViewVulnData -Line "" -AddCRLF
	        Write-ViewVulnData -Line "Rule Title:" -AsBold
	        Write-ViewVulnData -Line " $($VulnData_RuleTitle)" -AddCRLF
	        
	        # Append Discussion
	        Write-ViewVulnData -Line "" -AddCRLF
	        Write-ViewVulnData -Line "Discussion:" -AsBold
	        foreach ($Line in $VulnData_Discussion) {
	            Write-ViewVulnData -Line " $($Line)" -AddCRLF
	        }
	        
	        # Append Check Text
	        Write-ViewVulnData -Line "" -AddCRLF
	        Write-ViewVulnData -Line "Check Text:" -AsBold
	        foreach ($Line in $VulnData_CheckText) {
	            Write-ViewVulnData -Line " $($Line)" -AddCRLF
	        }
	        
	        # Append Fix Text
	        Write-ViewVulnData -Line "" -AddCRLF
	        Write-ViewVulnData -Line "Fix Text:" -AsBold
	        foreach ($Line in $VulnData_FixText) {
	            Write-ViewVulnData -Line " $($Line)" -AddCRLF
	        }
	        #----------------------------------
	        
	        # Update child listbox
	        foreach ($Item in ($script:AFObject.$($script:STIGName).$($listboxAF_VulnID.SelectedItem).Keys)) {
	            if ($Item -ne "_Comment") {
	                Update-ListBox -ListBox $listboxAF_AnswerKeyName -Items $Item -Append
	            }
	        }
	        
	        if ($listboxAF_AnswerKeyName.Items.Count -eq 1) {
	            # Only one entry exists to select it to reduce unnecessary clicks
	            $listboxAF_AnswerKeyName.SelectedIndex = 0
	        }
	        
	        if ($listboxAF_Index.Items.Count -eq 1) {
	            # Only one entry exists to select it to reduce unnecessary clicks
	            $listboxAF_Index.SelectedIndex = 0
	        }
	    }
	}
	
	$listboxAF_VulnID_MouseDoubleClick = [System.Windows.Forms.MouseEventHandler]{
	    # Double click listboxAF_VulnID invokes the buttonVulnData click
	    if ($listboxAF_VulnID.SelectedIndex -ne -1) {
	        $buttonVulnData_Click.Invoke($null, $null)
	    }
	}
	
	$buttonVulnData_Click = {
	    if (-Not ($VulnData_AF_RichTextBox.Visible)) {
	        $buttonVulnData.Text = "Hide"
	        
	        # Hide Options and Content groupbox controls
	        $groupboxAF_Options.Visible = $false
	        $groupboxAF_Content.Visible = $false
	        
	        # Unhide VulnData richtextbox control
	        $VulnData_AF_RichTextBox.Visible = $true
	    }
	    else {
	        $buttonVulnData.Text = "View"
	        
	        # Unhide Options and Content groupbox controls
	        $groupboxAF_Options.Visible = $true
	        $groupboxAF_Content.Visible = $true
	        
	        # Hide VulnData richtextbox control
	        $VulnData_AF_RichTextBox.Visible = $false
	    }
	}
	
	$buttonAF_VulnIDAdd_Click = {
	    $STIGItem = ($script:STIGListObj | Where-Object { $_.Name -eq $script:STIGName -or $_.ShortName -eq $script:STIGName })
	    if (-Not ($STIGItem)) {
	        [System.Windows.Forms.MessageBox]::Show("$($script:STIGName) is not a supported STIG.", 'Warning', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning)
	    }
	    else {
	        if ((Show-STIGCheckPicker_psf -ShortName $STIGItem.ShortName) -eq 'OK') {
	            # Confirm STIG check is not already in answer file
	            if ($listboxAF_VulnID.Items -contains $script:Result.VulnID -or $listboxAF_VulnID.Items -contains $script:Result.RuleID) {
	                $Conflict = $listboxAF_VulnID.Items | Where-Object { $_ -in @($script:Result.VulnID, $script:Result.RuleID) }
	                [System.Windows.Forms.MessageBox]::Show("$($script:Result.Value) is already in the answer file as $($Conflict)", 'Warning', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning)
	            }
	            else {
	                $NewItem = $script:Result.Value
	                $NewComment = $script:Result.Comment
	                if ($NewItem -notin @($null, "")) {
	                    # Add key
	                    Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Add -STIG $textboxAF_STIGCommentsName.Text -VulnID $NewItem
	                    
	                    # Add to listbox
	                    Update-ListBox -ListBox $listboxAF_VulnID -Items $NewItem -Append
	                    $listboxAF_VulnID.Sorted = $true
	                    
	                    # Select new listbox item to reload data
	                    $NewIndex = $listboxAF_VulnID.Items.IndexOf($NewItem)
	                    $listboxAF_VulnID.SetSelected($NewIndex, $true)
	                    
	                    # Set $IsModified to $true
	                    $script:IsModified = $true
	                    Test-IsModified
	                }
	                if ($NewComment -ne ($script:AFObject.$($textboxAF_STIGCommentsName.Text).$($listboxAF_VulnID.SelectedItem)._Comment)) {
	                    # Update comment
	                    Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Update -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -VulnIDComment $NewComment
	                    
	                    # Set $IsModified to $true
	                    $script:IsModified = $true
	                    Test-IsModified
	                }
	            }
	        }
	    }
	}
	
	$buttonAF_VulnIDConvert_Click = {
	    if ($script:XccdfContent.Benchmark.Group) {
	        $Duplicate = $false
	        $Proceed = $true
	        
	        # Switch between GroupID and RuleID formats
	        if ($listboxAF_VulnID.SelectedItem -match "^V-") {
	            # Current format is GroupID.  Change to RuleID
	            $NewItem = ($script:XccdfContent.Benchmark.Group | Where-Object id -eq $listboxAF_VulnID.SelectedItem).Rule.id
	            if (@($listboxAF_VulnID.Items) -match ($NewItem -split "r")[0]) {
	                # RuleID already exists
	                $Duplicate = @(@($listboxAF_VulnID.Items) | Where-Object { $_ -match "^$(($NewItem -split 'r')[0])" })
	                if ([System.Windows.Forms.MessageBox]::Show("An item for $(($NewItem -split 'r')[0]) already exists.  Replace it with this one?", 'Warning', [System.Windows.Forms.MessageBoxButtons]::OKCancel, [System.Windows.Forms.MessageBoxIcon]::Warning) -ne "OK") {
	                    $Proceed = $false
	                }
	            }
	        }
	        elseif ($listboxAF_VulnID.SelectedItem -match "^SV-") {
	            # Current format is RuleID.  Change to GroupID
	            $NewItem = ($script:XccdfContent.Benchmark.Group | Where-Object { $_.Rule.id -match ($listboxAF_VulnID.SelectedItem -split "r")[0] }).id
	            if ($NewItem -in @($listboxAF_VulnID.Items) -or (@($listboxAF_VulnID.Items) -match "^$(($listboxAF_VulnID.SelectedItem -split 'r')[0])" | Where-Object { $_ -ne $listboxAF_VulnID.SelectedItem })) {
	                # GroupID already exists
	                $Duplicate = @()
	                foreach ($Item in @($listboxAF_VulnID.Items)) {
	                    if ($Item -eq $NewItem -or ($Item -match "^$(($listboxAF_VulnID.SelectedItem -split 'r')[0])" -and $Item -ne $listboxAF_VulnID.SelectedItem)) {
	                        $Duplicate += $Item
	                    }
	                }
	                if ([System.Windows.Forms.MessageBox]::Show("An item for $NewItem already exists.  Replace it with this one?", 'Warning', [System.Windows.Forms.MessageBoxButtons]::OKCancel, [System.Windows.Forms.MessageBoxIcon]::Warning) -ne "OK") {
	                    $Proceed = $false
	                }
	            }
	        }
	        
	        if ($Proceed -eq $true) {
	            if ($Duplicate -ne $false) {
	                # Remove already existing item
	                foreach ($Dup in $Duplicate) {
	                    Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Remove -STIG $textboxAF_STIGCommentsName.Text -VulnID $Dup
	                    
	                    # Remove from listbox
	                    $listboxAF_VulnID.Items.Remove($Dup)
	                }
	            }
	            $CurrentItem = $listboxAF_VulnID.SelectedItem
	            $CurrentIndex = $listboxAF_VulnID.SelectedIndex
	            if ($listboxAF_AnswerKeyName.SelectedItem -notin @($null, "")) {
	                # Get the currently selected AnswerKeyName so we can reselect it
	                $SelectedAFAnswerKeyName = $listboxAF_AnswerKeyName.SelectedItem
	            }
	            if ($listboxAF_Index.SelectedItem -notin @($null, "")) {
	                # Get the currently selected Index so we can reselect it
	                $SelectedAFIndex = $listboxAF_Index.SelectedItem
	            }
	            
	            # Rename key
	            Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Rename -STIG $textboxAF_STIGCommentsName.Text -VulnID $CurrentItem -NewKeyName $NewItem
	            
	            # Select renamed listbox item to reload data
	            $listboxAF_VulnID.Items[$CurrentIndex] = $NewItem
	            $NewIndex = $listboxAF_VulnID.Items.IndexOf($NewItem)
	            $listboxAF_VulnID.SetSelected($NewIndex, $true)
	            
	            if ($SelectedAFIndex) {
	                # Reselect the previously selected AnswerKeyName
	                $listboxAF_AnswerKeyName.SelectedItem = $SelectedAFAnswerKeyName
	            }
	            if ($SelectedAFIndex) {
	                # Reselect the previously selected Index
	                $listboxAF_Index.SelectedItem = $SelectedAFIndex
	            }
	            
	            # Set $IsModified to $true
	            $script:IsModified = $true
	            Test-IsModified
	        }
	    }    
	}
	
	$buttonAF_VulnIDRemove_Click = {
	    # Update NewAFObject
	    if ($listboxAF_VulnID.Items.Count -eq 1) {
	        # TODO: Do nothing for now
	    }
	    else {
	        # More than one AnswerKeyName exists so just remove the selected AnswerKeyName
	        $SelectedIndex = $listboxAF_VulnID.SelectedIndex
	    }
	    Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Remove -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem
	    
	    # Remove from listbox
	    $listboxAF_VulnID.Items.Remove($listboxAF_VulnID.SelectedItem)
	    
	    # Select previous item in list
	    if ($null -ne $SelectedIndex) {
	        if ($SelectedIndex -gt 0) {
	            if ($SelectedIndex -gt ($listboxAF_VulnID.Items.Count - 1)) {
	                # Select the last index in the listbox
	                $listboxAF_VulnID.SetSelected(($listboxAF_VulnID.Items.Count - 1), $true)
	            }
	            else {
	                $listboxAF_VulnID.SetSelected(($SelectedIndex), $true)
	            }
	        }
	        else {
	            $listboxAF_VulnID.SetSelected(0, $true)
	        }
	    }
	    
	    # Set $IsModified to $true
	    $script:IsModified = $true
	    Test-IsModified
	}
	
	$listboxAF_AnswerKeyName_SelectedIndexChanged = {
	    # Clear Index listbox and disable Attributes groupbox
	    $listboxAF_Index.Items.Clear()
	    $groupboxAF_Attributes.Enabled = $false
	    
	    Update-AnswerDataFields -Clear
	    if ($listboxAF_AnswerKeyName.SelectedItem -notin @($null, "")) {
	        # Disable all child Add|Edit|Delete|Up|Down buttons
	        $buttonAF_IndexAdd.Enabled = $false
	        $buttonAF_IndexEdit.Enabled = $false
	        $buttonAF_IndexRemove.Enabled = $false
	        $buttonAF_IndexUp.Enabled = $false
	        $buttonAF_IndexDown.Enabled = $false
	        $buttonAF_ImportResult.Enabled = $false
	        
	        # Enable self Update|Delete and first child Create buttons
	        $buttonAF_AnswerKeyNameEdit.Enabled = $true
	        $buttonAF_AnswerKeyNameRemove.Enabled = $true
	        $buttonAF_IndexAdd.Enabled = $true
	        
	        # Update child listbox
	        foreach ($Item in ($script:AFObject.$($script:STIGName).$($listboxAF_VulnID.SelectedItem).$($listboxAF_AnswerKeyName.SelectedItem).Keys)) {
	            if ($Item -ne "_Comment") {
	                Update-ListBox -ListBox $listboxAF_Index -Items $Item -Append
	            }
	        }
	        
	        if ($listboxAF_Index.Items.Count -eq 1) {
	            # Only one entry exists to select it to reduce unnecessary clicks
	            $listboxAF_Index.SelectedIndex = 0
	        }
	    }
	}
	
	$buttonAF_AnswerKeyNameAdd_Click = {
	    # Prepopulate child form with DefaultAFKey if not already configured
	    if ($script:DefaultAFKey -notin @($listboxAF_AnswerKeyName.Items)) {
	        $CurrentValue = $script:DefaultAFKey
	    }
	    else {
	        $CurrentValue = ""
	    }
	    
	    if ((Show-AF_EditAttribute_psf -FormTitle "Add AnswerKey Name" -CurrentValue $CurrentValue) -eq 'OK') {
	        # Set new key name
	        if ($script:Result.Value -notin @($null, "")) {
	            $NewItem = $script:Result.Value
	        }
	        else {
	            $NewItem = $script:DefaultAFKey
	        }
	        
	        if ($NewItem -in @($listboxAF_AnswerKeyName.Items)) {
	            [System.Windows.Forms.MessageBox]::Show("AnswerKey Name $($NewItem) already exists.", 'Warning', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning)
	        }
	        else {
	            # Add key
	            Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Add -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $NewItem
	            
	            # Add to listbox
	            Update-ListBox -ListBox $listboxAF_AnswerKeyName -Items $NewItem -Append
	            
	            # Select new listbox item to reload data
	            $NewIndex = $listboxAF_AnswerKeyName.Items.IndexOf($NewItem)
	            $listboxAF_AnswerKeyName.SetSelected($NewIndex, $true)
	            
	            # Set $IsModified to $true
	            $script:IsModified = $true
	            Test-IsModified
	            
	            # Add comment to new key
	            $NewComment = $script:Result.Comment
	            if ($NewComment -ne ($script:AFObject.$($textboxAF_STIGCommentsName.Text).$($listboxAF_VulnID.SelectedItem).$($listboxAF_AnswerKeyName.SelectedItem)._Comment)) {
	                # Update comment
	                Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Update -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem -AnswerKeyNameComment $NewComment
	                
	                # Set $IsModified to $true
	                $script:IsModified = $true
	                Test-IsModified
	            }
	        }
	    }
	}
	
	$buttonAF_AnswerKeyNameEdit_Click = {
	    $CurrentItem = $listboxAF_AnswerKeyName.SelectedItem
	    $CurrentIndex = $listboxAF_AnswerKeyName.SelectedIndex
	    if ($listboxAF_Index.SelectedItem -notin @($null, "")) {
	        # Get the currently selected Index so we can reselect it
	        $SelectedAFIndex = $listboxAF_Index.SelectedItem
	    }
	    
	    if ((Show-AF_EditAttribute_psf -FormTitle "Edit AnswerKey Name" -CurrentValue $listboxAF_AnswerKeyName.SelectedItem -CurrentComment $script:AFObject.$($textboxAF_STIGCommentsName.Text).$($listboxAF_VulnID.SelectedItem).$($listboxAF_AnswerKeyName.SelectedItem)._Comment) -eq 'OK') {
	        $NewItem = $script:Result.Value
	        $NewComment = $script:Result.Comment
	        if ($NewItem -ne $CurrentItem) {
	            # Rename key
	            Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Rename -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $CurrentItem -NewKeyName $NewItem
	            
	            # Select renamed listbox item to reload data
	            $listboxAF_AnswerKeyName.Items[$CurrentIndex] = $NewItem
	            $NewIndex = $listboxAF_AnswerKeyName.Items.IndexOf($NewItem)
	            $listboxAF_AnswerKeyName.SetSelected($NewIndex, $true)
	            
	            if ($SelectedAFIndex) {
	                # Reselect the previously selected Index
	                $listboxAF_Index.SelectedItem = $SelectedAFIndex
	            }
	            
	            # Set $IsModified to $true
	            $script:IsModified = $true
	            Test-IsModified
	        }
	        if ($NewComment -ne ($script:AFObject.$($textboxAF_STIGCommentsName.Text).$($listboxAF_VulnID.SelectedItem).$($listboxAF_AnswerKeyName.SelectedItem)._Comment)) {
	            # Update comment
	            Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Update -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem -AnswerKeyNameComment $NewComment
	            
	            # Set $IsModified to $true
	            $script:IsModified = $true
	            Test-IsModified
	        }
	    }
	}
	
	$buttonAF_AnswerKeyNameRemove_Click = {
	    # Update NewAFObject
	    if ($listboxAF_AnswerKeyName.Items.Count -eq 1) {
	        # Last AnswerKeyName item so remove the VulnID
	        Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Remove -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem
	        $buttonAF_VulnIDRemove.PerformClick()
	    }
	    else {
	        # More than one AnswerKeyName exists so just remove the selected AnswerKeyName
	        $SelectedIndex = $listboxAF_AnswerKeyName.SelectedIndex
	        Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Remove -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem
	    }
	    
	    # Remove from listbox
	    $listboxAF_AnswerKeyName.Items.Remove($listboxAF_AnswerKeyName.SelectedItem)
	    
	    # Select previous item in list
	    if ($null -ne $SelectedIndex) {
	        if ($SelectedIndex -gt 0) {
	            if ($SelectedIndex -gt ($listboxAF_AnswerKeyName.Items.Count - 1)) {
	                # Select the last index in the listbox
	                $listboxAF_AnswerKeyName.SetSelected(($listboxAF_AnswerKeyName.Items.Count - 1), $true)
	            }
	            else {
	                $listboxAF_AnswerKeyName.SetSelected(($SelectedIndex), $true)
	            }
	        }
	        else {
	            $listboxAF_AnswerKeyName.SetSelected(0, $true)
	        }
	    }
	    
	    # Set $IsModified to $true
	    $script:IsModified = $true
	    Test-IsModified
	}
	
	$listboxAF_Index_SelectedIndexChanged = {
	    if ($listboxAF_Index.SelectedItem -notin @($null, "")) {
	        # Enable self Edit|Delete|Up|Down buttons
	        $buttonAF_IndexEdit.Enabled = $true
	        $buttonAF_IndexRemove.Enabled = $true
	        $buttonAF_IndexUp.Enabled = $true
	        $buttonAF_IndexDown.Enabled = $true
	        $buttonAF_ImportResult.Enabled = $true
	        $groupboxAF_Attributes.Enabled = $true
	        
	        # Update valid Status entries
	        foreach ($Obj in @($comboboxAF_ExpectedStatus, $comboboxAF_ValidTrueStatus, $comboboxAF_ValidFalseStatus)) {
	            $Obj.Items.Clear()
	            switch ($Obj) {
	                $comboboxAF_ExpectedStatus {
	                    foreach ($Status in $script:ValidStatus) {
	                        Update-ComboBox -ComboBox $Obj -Items (Convert-Status -InputObject $Status -Output $comboboxAF_FormatStatus.SelectedItem) -Append
	                    }
	                }
	                default {
	                    Update-ComboBox -ComboBox $Obj -Items ""
	                    foreach ($Status in $script:ValidStatus) {
	                        Update-ComboBox -ComboBox $Obj -Items (Convert-Status -InputObject $Status -Output $comboboxAF_FormatStatus.SelectedItem) -Append
	                    }
	                }
	            }
	        }
	        
	        # Update configuration data fields
	        Update-AnswerDataFields -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem -Index $listboxAF_Index.SelectedItem
	    }
	    else {
	        $groupboxAF_Attributes.Enabled = $false
	    }
	}
	
