	            # Update comment
	            Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Update -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem -Index $CurrentItem -IndexComment $NewComment
	            
