	$buttonAF_IndexRemove_Click = {
	    # Update NewAFObject
	    if ($listboxAF_Index.Items.Count -eq 1) {
	        # Last Index item so remove the AnswerKeyName
	        Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Remove -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem
	        $buttonAF_AnswerKeyNameRemove.PerformClick()
	    }
	    else {
	        # More than one Index exists so just remove the selected Index
	        $SelectedIndex = $listboxAF_Index.SelectedIndex
	        Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Remove -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem -Index $listboxAF_Index.SelectedItem
	    }
	    
	    # Remove from listbox and update datafields
	    $listboxAF_Index.Items.Remove($listboxAF_Index.SelectedItem)
	    Update-AnswerDataFields -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem -Index $listboxAF_Index.SelectedItem
	    
	    # Select previous item in list
	    if ($null -ne $SelectedIndex) {
	        if ($SelectedIndex -gt 0) {
	            if ($SelectedIndex -gt ($listboxAF_Index.Items.Count - 1)) {
	                # Select the last index in the listbox
	                $listboxAF_Index.SetSelected(($listboxAF_Index.Items.Count - 1), $true)
	            }
	            else {
	                $listboxAF_Index.SetSelected(($SelectedIndex), $true)
	            }
	        }
	        else {
	            $listboxAF_Index.SetSelected(0, $true)
	        }
	    }
	    
	    # Set $IsModified to $true
	    $script:IsModified = $true
	    Test-IsModified
	}
	
	$buttonAF_IndexUp_Click = {
	    $NewSelectedIndices = @()
	    
	    while ($listboxAF_Index.SelectedItems.Count -gt 0) {
	        # Get the item you want to move (e.g., the currently selected item)
	        $ItemToMove = $listboxAF_Index.SelectedItem
	        
	        # Get the current index of the item
	        $CurrentIndex = $listboxAF_Index.SelectedIndex
	        
	        # Specify the desired new index (e.g., move it up one position)
	        $NewIndex = $CurrentIndex - 1
	        
	        # Ensure the new index is valid (within the range of the list)
	        if ($NewIndex -ge 0 -and $NewIndex -notin $NewSelectedIndices) {
	            $NewSelectedIndices += $NewIndex
	            
	            # Remove the item from its current position
	            $listboxAF_Index.Items.RemoveAt($CurrentIndex)
	            
	            # Insert the item at the new position
	            $listboxAF_Index.Items.Insert($NewIndex, $ItemToMove)
	        }
	        else {
	            $NewSelectedIndices += $CurrentIndex
	            $listboxAF_Index.SetSelected($CurrentIndex, $false)
	        }
	    }
	    
	    foreach ($NewIndex in $NewSelectedIndices) {
	        $listboxAF_Index.SetSelected($NewIndex, $true)
	    }
	    
	    # Reorder Index items
	    Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Reorder -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem -IndexOrder @($listboxAF_Index.Items)
	    
	    # Set $IsModified to $true
	    $script:IsModified = $true
	    Test-IsModified
	}
	
	$buttonAF_IndexDown_Click = {
	    $NewSelectedIndices = @()
	    
	    while ($listboxAF_Index.SelectedItem.Count -gt 0) {
	        # Get the item you want to move (e.g., the currently selected item)
	        $ItemToMove = $listboxAF_Index.SelectedItems | Select-Object -Last 1
	        
	        # Get the current index of the item
	        $CurrentIndex = $listboxAF_Index.SelectedIndices | Select-Object -Last 1
	        
	        # Specify the desired new index (e.g., move it up one position)
	        $NewIndex = $CurrentIndex + 1
	        
	        # Ensure the new index is valid (within the range of the list)
	        if ($NewIndex -le ($listboxAF_Index.Items.Count - 1) -and $NewIndex -notin $NewSelectedIndices) {
	            $NewSelectedIndices += $NewIndex
	            
	            # Remove the item from its current position
	            $listboxAF_Index.Items.RemoveAt($CurrentIndex)
	            
	            # Insert the item at the new position
	            $listboxAF_Index.Items.Insert($NewIndex, $ItemToMove)
	        }
	        else {
	            $NewSelectedIndices += $CurrentIndex
	            $listboxAF_Index.SetSelected($CurrentIndex, $false)
	        }
	    }
	    
	    foreach ($NewIndex in $NewSelectedIndices) {
	        $listboxAF_Index.SetSelected($NewIndex, $true)
	    }
	    
	    # Reorder Index items
	    Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Reorder -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem -IndexOrder @($listboxAF_Index.Items)
	    
	    # Set $IsModified to $true
	    $script:IsModified = $true
	    Test-IsModified
	}
	
	$buttonAF_ImportResult_Click = {
	    if ($textboxAF_ResultSource.Text -in @($null, "")) {
	        # Result Source not set.  Set it now.
	        $BrowserTitle = "Select checklist file:"
	        
	        $SelectedFile = Invoke-FileBrowser -Action Open -Title $BrowserTitle -InitialDirectory $script:ESResultsPath -Filter "Checklist Files (*.ckl,*.cklb)|*.ckl;*.cklb"
	    }
	    else {
	        if (Test-Path $textboxAF_ResultSource.Text) {
	            $SelectedFile = $textboxAF_ResultSource.Text
	        }
	        else {
	            # Result Source does not exist.  Prompt for file.
	            $BrowserTitle = "Select checklist file:"
	            
	            $SelectedFile = Invoke-FileBrowser -Action Open -Title $BrowserTitle -InitialDirectory $script:ESResultsPath -Filter "Checklist Files (*.ckl,*.cklb)|*.ckl;*.cklb"
	        }
	    }
	    
	    if ($SelectedFile) {
	        $labelGUIState.Text = "Parsing..."; $labelGUIState.ForeColor = 'Yellow'
	        $formEvaluateSTIG.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
	        Start-Sleep -Milliseconds 50
	        
	        $STIGID = $script:XccdfContent.Benchmark.id
	        $STIGReleaseInfo = ($script:XccdfContent.Benchmark.'plain-text' | Where-Object { $_.id -eq "release-info" }).'#text'
	        switch ([System.IO.Path]::GetExtension($SelectedFile)) {
	            ".ckl" {
	                $CheckListData = Convert-ChecklistToHashTable -InputObject ([XML](Get-Content $SelectedFile -Raw)) -InputType CKL
	            }
	            ".cklb" {
	                $CheckListData = Convert-ChecklistToHashTable -InputObject (Get-Content $SelectedFile -Raw | ConvertFrom-Json) -InputType CKLB
	            }
	        }
	        
	        $labelGUIState.Text = "Idle"; $labelGUIState.ForeColor = 'White'
	        $formEvaluateSTIG.Cursor = [System.Windows.Forms.Cursors]::Default
	        Start-Sleep -Milliseconds 50
	        
	        # Check that the desired STIG is in the checklist
	        if ($STIGID -in $CheckListData.Keys) {
	            $STIGKey = $CheckListData.$STIGID
	            # Check that the ReleaseInfo match
	            if ($STIGKey.ReleaseInfo -ne $STIGReleaseInfo) {
	                # ReleaseInfo mismatch
	                [System.Windows.Forms.MessageBox]::Show("Checklist version does not match STIG version.`r`n`r`nSTIG:`t$($STIGReleaseInfo)`r`nFile:`t$($STIGKey.ReleaseInfo)", "Warning", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning)
	            }
	            
	            # Check if Result Source is set.  If not, set it now.
	            if ($textboxAF_ResultSource.Text -in @($null, "") -or (-Not(Test-Path $textboxAF_ResultSource.Text))) {
	                $textboxAF_ResultSource.Text = $SelectedFile
	            }
	
	            # Check that the desired Vuln is in the checklist
	            foreach ($Vuln in $STIGKey.GroupIDs.Keys) {
	                if ($listboxAF_VulnID.SelectedItem -in $STIGKey.GroupIDs.$($Vuln).GroupID -or $listboxAF_VulnID.SelectedItem -in $STIGKey.GroupIDs.$($Vuln).RuleID) {
	                    $VulnData = $STIGKey.GroupIDs.$($Vuln)
	                    break
	                }
	            }
	            if ($VulnData) {
	                if ((Show-AF_VulnResult_psf -VulnData $VulnData) -eq 'OK') {
	                    if (($script:VulnImport.Keys | Measure-Object).Count -ne 0) {
	                        foreach ($Key in $script:VulnImport.Keys) {
	                            switch ($Key) {
	                                "ExpectedStatus" {
	                                    $comboboxAF_ExpectedStatus.SelectedItem = (Convert-Status -InputObject $script:VulnImport.$($Key) -Output $comboboxAF_FormatStatus.SelectedItem)
	                                    if ($script:AFObject.$($textboxAF_STIGCommentsName.Text).$($listboxAF_VulnID.SelectedItem).$($listboxAF_AnswerKeyName.SelectedItem).$($listboxAF_Index.SelectedItem).ExpectedStatus -ne $comboboxAF_ExpectedStatus.SelectedItem) {
	                                        Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Update -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem -Index $listboxAF_Index.SelectedItem -ExpectedStatus $comboboxAF_ExpectedStatus.SelectedItem
	                                        
	                                        # Set $IsModified to $true
	                                        $script:IsModified = $true
	                                        Test-IsModified
	                                    }
	                                }
	                                "Instance" {
	                                    $Data = @($textboxAF_Instance.Text -split "," | Where-Object { $_ -ne "" })
	                                    if ($script:VulnImport.$($Key) -notin $Data) {
	                                        $Data += $script:VulnImport.$($Key)
	                                        $textboxAF_Instance.Text = $Data -join ","
	                                    }
	                                    if ($script:AFObject.$($textboxAF_STIGCommentsName.Text).$($listboxAF_VulnID.SelectedItem).$($listboxAF_AnswerKeyName.SelectedItem).$($listboxAF_Index.SelectedItem).Instance -ne $textboxAF_Instance.Text) {
	                                        Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Update -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem -Index $listboxAF_Index.SelectedItem -Instance $textboxAF_Instance.Text
	                                        
	                                        # Set $IsModified to $true
	                                        $script:IsModified = $true
	                                        Test-IsModified
	                                    }
	                                }
	                                "Database" {
	                                    $Data = @($textboxAF_Database.Text -split "," | Where-Object { $_ -ne "" })
	                                    if ($script:VulnImport.$($Key) -notin $Data) {
	                                        $Data += $script:VulnImport.$($Key)
	                                        $textboxAF_Database.Text = $Data -join ","
	                                    }
	                                    if ($script:AFObject.$($textboxAF_STIGCommentsName.Text).$($listboxAF_VulnID.SelectedItem).$($listboxAF_AnswerKeyName.SelectedItem).$($listboxAF_Index.SelectedItem).Database -ne $textboxAF_Database.Text) {
	                                        Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Update -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem -Index $listboxAF_Index.SelectedItem -Database $textboxAF_Database.Text
	                                        
	                                        # Set $IsModified to $true
	                                        $script:IsModified = $true
	                                        Test-IsModified
	                                    }
	                                }
	                                "Site" {
	                                    $Data = @($textboxAF_Site.Text -split "," | Where-Object { $_ -ne "" })
	                                    if ($script:VulnImport.$($Key) -notin $Data) {
	                                        $Data += $script:VulnImport.$($Key)
	                                        $textboxAF_Site.Text = $Data -join ","
	                                    }
	                                    if ($script:AFObject.$($textboxAF_STIGCommentsName.Text).$($listboxAF_VulnID.SelectedItem).$($listboxAF_AnswerKeyName.SelectedItem).$($listboxAF_Index.SelectedItem).Site -ne $textboxAF_Site.Text) {
	                                        Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Update -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem -Index $listboxAF_Index.SelectedItem -Site $textboxAF_Site.Text
	                                        
	                                        # Set $IsModified to $true
	                                        $script:IsModified = $true
	                                        Test-IsModified
	                                    }
	                                }
	                                "ResultHash" {
	                                    $Data = @($textboxAF_ResultHash.Text -split "," | Where-Object { $_ -ne "" })
	                                    if ($script:VulnImport.$($Key) -notin $Data) {
	                                        $Data += $script:VulnImport.$($Key)
	                                        $textboxAF_ResultHash.Text = $Data -join ","
	                                    }
	                                    if ($script:AFObject.$($textboxAF_STIGCommentsName.Text).$($listboxAF_VulnID.SelectedItem).$($listboxAF_AnswerKeyName.SelectedItem).$($listboxAF_Index.SelectedItem).ResultHash -ne $textboxAF_ResultHash.Text) {
	                                        Update-AFObject -StatusFormat $comboboxAF_FormatStatus.SelectedItem -Action Update -STIG $textboxAF_STIGCommentsName.Text -VulnID $listboxAF_VulnID.SelectedItem -AnswerKeyName $listboxAF_AnswerKeyName.SelectedItem -Index $listboxAF_Index.SelectedItem -ResultHash $textboxAF_ResultHash.Text
	                                        
	                                        # Set $IsModified to $true
	                                        $script:IsModified = $true
	                                        Test-IsModified
	                                    }
	                                }
	                            }
	                        }
	                    }
	                }
	            }
	            else {
	                # Vuln not in checklist
	                [System.Windows.Forms.MessageBox]::Show("'$($listboxAF_VulnID.SelectedItem)' not found in checklist file'.", "Error", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
	            }
	        }
	        else {
	            # Checklist does not contain the desired STIG
	            [System.Windows.Forms.MessageBox]::Show("$($SelectedFile) does not contain a result for STIG '$($STIGID)'.", "Error", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
	        }
	    }
	}
	
	$comboboxAF_ExpectedStatus_SelectedIndexChanged = {
	    if ($listboxAF_Index.SelectedItem -notin @($null, "")) {
	        if ((Convert-Status -InputObject $script:AFObject.$($textboxAF_STIGCommentsName.Text).$($listboxAF_VulnID.SelectedItem).$($listboxAF_AnswerKeyName.SelectedItem).$($listboxAF_Index.SelectedItem).ExpectedStatus -Output $comboboxAF_FormatStatus.SelectedItem) -ne (Convert-Status -InputObject $comboboxAF_ExpectedStatus.SelectedItem -Output $comboboxAF_FormatStatus.SelectedItem)) {
