	$richtextboxAF_ValidationCode.Add_KeyDown({
	    if ($_.Control -and $_.KeyCode -eq 'V') {
	        # Prevent default paste behavior
	        $_.SuppressKeyPress = $true
	        
	        # Get text from clipboard
	        $pasteText = [System.Windows.Forms.Clipboard]::GetText()
	        
	        # Remove leading and trailing spaces
	        $pasteText = $pasteText.Trim()
	        
	        # Insert the cleaned text at the current cursor position
	        $richtextboxAF_ValidationCode.SelectedText = $pasteText
	    }
	})
	
