	        elseif ((Convert-Status -InputObject $script:AFObject.$($textboxAF_STIGCommentsName.Text).$($listboxAF_VulnID.SelectedItem).$($listboxAF_AnswerKeyName.SelectedItem).$($listboxAF_Index.SelectedItem).ValidTrueStatus -Output $comboboxAF_FormatStatus.SelectedItem) -ne (Convert-Status -InputObject $comboboxAF_ValidTrueStatus.SelectedItem -Output $comboboxAF_FormatStatus.SelectedItem)) {
