	$buttonAF_Discard_Click = {
	    if ([System.Windows.Forms.MessageBox]::Show("Discard changes to answer file?", 'Warning', [System.Windows.Forms.MessageBoxButtons]::OKCancel, [System.Windows.Forms.MessageBoxIcon]::Warning) -eq "OK") {
	        $VulnDataOpen = $false
	        if ($VulnData_AF_RichTextBox.Visible) {
	            $VulnDataOpen = $true
	            # Reset VulnData view
	            $buttonVulnData.Text = "View"
	            
	            # Unhide Options and Content groupbox controls
	            $groupboxAF_Options.Visible = $true
	            $groupboxAF_Content.Visible = $true
	            
	            # Hide VulnData richtextbox control
	            $VulnData_AF_RichTextBox.Visible = $false
	        }        
	        
	        # Get currently selected items
	        if ($listboxAF_VulnID.SelectedItem -notin @($null, "")) {
	            $SelectedVulnIndex = $listboxAF_VulnID.SelectedIndex
	        }
	        if ($listboxAF_AnswerKeyName.SelectedItem -notin @($null, "")) {
	            $SelectedAnswerIndex = $listboxAF_AnswerKeyName.SelectedIndex
	        }
	        if ($listboxAF_Index.SelectedItem -notin @($null, "")) {
	            $SelectedIndexIndex = $listboxAF_Index.SelectedIndex
	        }
	        
	        # Set $IsModified to $false
	        $script:IsModified = $false
	        Test-IsModified
	        
	        Reset-AFConfiguredData
	        
	        # Reopen the file and set previously selected items except Index as Status format can interfere
	        $buttonAF_OpenCreate.PerformClick()
	        
	        if ($null -ne $SelectedVulnIndex -and ($SelectedVulnIndex -ge 0 -and $SelectedVulnIndex -lt $listboxAF_VulnID.Items.Count)) {
	            $listboxAF_VulnID.SetSelected($SelectedVulnIndex, $true)
	        }
	        if ($null -ne $SelectedAnswerIndex -and ($SelectedAnswerIndex -ge 0 -and $SelectedAnswerIndex -lt $listboxAF_AnswerKeyName.Items.Count)) {
	            $listboxAF_AnswerKeyName.SetSelected($SelectedAnswerIndex, $true)
	        }
	        if ($null -ne $SelectedIndexIndex -and ($SelectedIndexIndex -ge 0 -and $SelectedIndexIndex -lt $listboxAF_Index.Items.Count)) {
	            $listboxAF_Index.SetSelected($SelectedIndexIndex, $true)
	        }
	        
	        if ($VulnDataOpen) {
	            $buttonVulnData.Text = "Hide"
	            
	            # Hide Options and Content groupbox controls
	            $groupboxAF_Options.Visible = $false
	            $groupboxAF_Content.Visible = $false
	            
	            # Unhide VulnData richtextbox control
	            $VulnData_AF_RichTextBox.Visible = $true
	        }
	    }
	}
	
