	$buttonPref_SM_SMImport_COLLECTIONAdd_Click = {
	    if ((Show-Prefs_AddEditSTIGMan_psf -Operation Add) -eq 'OK') {
	        $NewObj = [ordered]@{
	            SMImport_CLIENT_ID       = $script:Result.ClientID
	            SMImport_CLIENT_CERT     = $script:Result.ClientCert
	            SMImport_CLIENT_CERT_KEY = $script:Result.ClientCertKey
	            SMImport_COLLECTION_ID   = $script:Result.CollectionID
	        }
	        $script:PrefsObj.STIGManager.Add($script:Result.CollectionName, $NewObj)
	        Update-ListBox -ListBox $listboxPref_SM_SMImport_COLLECTION -Items $script:Result.CollectionName -Append
	        $listboxPref_SM_SMImport_COLLECTION.Sorted = $true
	        
	        # Select new item
	        $i = 0
	        foreach ($Item in @($listboxPref_SM_SMImport_COLLECTION.Items)) {
	            if ($Item -eq $script:Result.CollectionName) {
	                $listboxPref_SM_SMImport_COLLECTION.SelectedIndex = $i
	                break
	            }
	            else {
	                $i++
	            }
	        }
	
	        # Update $comboboxPref_ES_SMCollection
	        $CurrentItem = $comboboxPref_ES_SMCollection.SelectedItem
	        $comboboxPref_ES_SMCollection.Items.Clear()
	        Update-ComboBox -ComboBox $comboboxPref_ES_SMCollection -Items ""
	        foreach ($Item in @($listboxPref_SM_SMImport_COLLECTION.Items)) {
	            if ($Item -eq "<placeholder>") {
	                $Item = ""
	            }
	            if ($Item -notin @($comboboxPref_ES_SMCollection.Items)) {
	                Update-ComboBox -ComboBox $comboboxPref_ES_SMCollection -Items $Item -Append
	            }
	        }
	        
	        # Preserve $comboboxPref_ES_SMCollection original setting
	        $i = 0
	        foreach ($Item in @($comboboxPref_ES_SMCollection.Items)) {
	            if ($Item -eq $CurrentItem) {
	                $comboboxPref_ES_SMCollection.SelectedIndex = $i
	                break
	            }
	            else {
	                $i++
	            }
	        }
	        $script:PrefsObj.EvaluateSTIG.SMCollection = $comboboxPref_ES_SMCollection.SelectedItem
	        
	        # Set $PrefsModified to $true
	        $script:PrefsModified = $true
	        Test-PrefsModified
	        
	        # Set focus to listbox
	        $listboxPref_SM_SMImport_COLLECTION.Focus()
	    }
	}
	
	$buttonPref_SM_SMImport_COLLECTIONEdit_Click = {
	    $Name = $listboxPref_SM_SMImport_COLLECTION.SelectedItem
	    if ($Name -eq "<placeholder>") {
	        $Name = ""
	    }
	    $ClientID = $script:PrefsObj.STIGManager.$Name.SMImport_CLIENT_ID
	    $ClientCert = $script:PrefsObj.STIGManager.$Name.SMImport_CLIENT_CERT
	    $ClientCertKey = $script:PrefsObj.STIGManager.$Name.SMImport_CLIENT_CERT_KEY
	    $CollectionID = $script:PrefsObj.STIGManager.$Name.SMImport_COLLECTION_ID
	    
	    if ((Show-Prefs_AddEditSTIGMan_psf -Operation Edit -CollectionName $Name -ClientID $ClientID -ClientCert $ClientCert -ClientCertKey $ClientCertKey -CollectionID $CollectionID) -eq 'OK') {
	        if ($script:Result.CollectionName -in $script:PrefsObj.STIGManager.Keys) {
	            # Key value unmodified.  Update its subvalues only
	            $script:PrefsObj.STIGManager.$($script:Result.CollectionName).SMImport_CLIENT_ID = $script:Result.ClientID
	            $script:PrefsObj.STIGManager.$($script:Result.CollectionName).SMImport_CLIENT_CERT = $script:Result.ClientCert
	            $script:PrefsObj.STIGManager.$($script:Result.CollectionName).SMImport_CLIENT_CERT_KEY = $script:Result.ClientCertKey
	            $script:PrefsObj.STIGManager.$($script:Result.CollectionName).SMImport_COLLECTION_ID = $script:Result.CollectionID
	        }
	        else {
	            # Key value changed.  Add new and remove current.
	            $NewObj = [ordered]@{
	                SMImport_CLIENT_ID       = $script:Result.ClientID
