	    if ($Name -eq "<placeholder>") {
	        $Name = ""
	    }
	    $Token = $script:PrefsObj.Splunk.$Name.Splunk_token
	    $Index = $script:PrefsObj.Splunk.$Name.Splunk_index
	    $Source = $script:PrefsObj.Splunk.$Name.Splunk_source
	    $SourceType = $script:PrefsObj.Splunk.$Name.Splunk_sourcetype
	    
	    if ((Show-Prefs_AddEditSplunk_psf -Operation Edit -HECName $Name -Token $Token -Index $Index -Source $Source -SourceType $SourceType) -eq 'OK') {
	        if ($script:Result.HECName -in $script:PrefsObj.Splunk.Keys) {
	            # Key value unmodified.  Update its subvalues only
	            $script:PrefsObj.Splunk.$($script:Result.HECName).Splunk_token = $script:Result.Token
	            $script:PrefsObj.Splunk.$($script:Result.HECName).Splunk_index = $script:Result.Index
	            $script:PrefsObj.Splunk.$($script:Result.HECName).Splunk_source = $script:Result.Source
	            $script:PrefsObj.Splunk.$($script:Result.HECName).Splunk_sourcetype = $script:Result.SourceType
	        }
	        else {
	            # Key value changed.  Add new and remove current.
	            $NewObj = [ordered]@{
	                Splunk_token      = $script:Result.Token
	                Splunk_index      = $script:Result.Index
	                Splunk_source     = $script:Result.Source
	                Splunk_sourcetype = $script:Result.SourceType
	            }
