	            if ($Name -eq "") {
	                $listboxPref_SK_Splunk_HECName.Items.Remove("<placeholder>")
	            }
	            else {
	                $listboxPref_SK_Splunk_HECName.Items.Remove($Name)
	            }
	            
	            # Update listbox with new item
	            Update-ListBox -ListBox $listboxPref_SK_Splunk_HECName -Items $script:Result.HECName -Append
