	                    $listboxPref_SK_Splunk_HECName.SelectedIndex = $i
	                    break
	                }
	                else {
	                    $i++
	                }
	            }
	        }
	        
	        # Update $comboboxPref_ES_SplunkHECName
	        $CurrentItem = $comboboxPref_ES_SplunkHECName.SelectedItem
	        $comboboxPref_ES_SplunkHECName.Items.Clear()
	        Update-ComboBox -ComboBox $comboboxPref_ES_SplunkHECName -Items ""
