	$buttonPref_AF_EvaluateSTIG_ResultsBrowse_Click = {
	    $BrowserDescription = "Select folder containing Evaluate-STIG results:"
	    if ($textboxPref_AF_EvaluateSTIG_Results.Text -notin @($null, "")) {
	        $BrowserSelectedPath = $textboxPref_AF_EvaluateSTIG_Results.Text
	    }
	    else {
	        $BrowserSelectedPath = $(Join-Path -Path $script:ESPath -ChildPath AnswerFiles)
	    }
	    
	    $SelectedPath = Invoke-FolderBrowser -Description $BrowserDescription -SelectedPath $BrowserSelectedPath
	    if ($SelectedPath) {
	        $textboxPref_AF_EvaluateSTIG_Results.Text = $SelectedPath
	    }
