	$buttonPref_Save_Click = {
	    Save-PreferencesObject -PrefObject $script:PrefsObj
	    
	    $script:PrefsModified = $false
	    Test-PrefsModified
	    
	    [System.Windows.Forms.MessageBox]::Show("You must close and reopen the GUI for the changes to take affect.", 'Preferences updated', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
	}
	
	$buttonPref_Discard_Click = {
	    if ([System.Windows.Forms.MessageBox]::Show("Discard changes to Preferences?", 'Warning', [System.Windows.Forms.MessageBoxButtons]::OKCancel, [System.Windows.Forms.MessageBoxIcon]::Warning) -eq "OK") {
	        # Reset PrefsObj from Preferences.xml
	        $script:PrefsObj = Convert-PreferencesToObject
	        
	        # Update PreferencesTab controls
	        Update-PreferencesTab
	        
	        # Set $PrefsModified to $false
	        $script:PrefsModified = $false
	        Test-PrefsModified
	    }
	}
	
	$formEvaluateSTIG_FormClosing = [System.Windows.Forms.FormClosingEventHandler]{
	    $ModifiedMsg = ""
	    if ($script:IsModified) {
	        $ModifiedMsg += "  - Answer file change pending" | Out-String
	    }
	    if ($script:PrefsModified) {
	        $ModifiedMsg += "  - Preferences change pending" | Out-String
	    }
	    
	    if ($ModifiedMsg -notin @($null, "")) {
	        $WarnMsg = "Exit without saving changes?`r`n`r`n$($ModifiedMsg)"
	        if ([System.Windows.Forms.MessageBox]::Show("$WarnMsg", 'Warning', [System.Windows.Forms.MessageBoxButtons]::OKCancel, [System.Windows.Forms.MessageBoxIcon]::Warning) -ne "OK") {
	            $_.Cancel = $true
	        }
	    }
	}
	
