param
(
    [Parameter(Mandatory = $true)]
    [PSObject]$Content,
    
    [Parameter(Mandatory = $true)]
    [ValidateSet("SupportedSTIGOutput", "ApplicableSTIGOutput", "HelpOutput", "AFView", "AFValidationOutput", "AFMaintainOutput", "AFExport")]
    [String]$ContentType,
    
    [Parameter(Mandatory = $false)]
    [String]$Title
)

	#----------------------------------------------
	#region Import the Assemblies
	#----------------------------------------------
	[void][reflection.assembly]::Load('System.Drawing, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b03f5f7f11d50a3a')
	[void][reflection.assembly]::Load('System.Windows.Forms, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089')
	[void][reflection.assembly]::Load('System.Data, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089')
	[void][reflection.assembly]::Load('PresentationFramework, Version=4.0.0.0, Culture=neutral, PublicKeyToken=31bf3856ad364e35')
	#endregion Import Assemblies

	#----------------------------------------------
	#region Generated Form Objects
	#----------------------------------------------
	[System.Windows.Forms.Application]::EnableVisualStyles()
	$formScriptOutput = New-Object 'System.Windows.Forms.Form'
	$richtextboxContent = New-Object 'System.Windows.Forms.RichTextBox'
	$buttonOK = New-Object 'System.Windows.Forms.Button'
	$InitialFormWindowState = New-Object 'System.Windows.Forms.FormWindowState'
	#endregion Generated Form Objects

	#----------------------------------------------
	# User Generated Script
	#----------------------------------------------
	
	
	$formScriptOutput_Load = {
	    switch ($ContentType) {
	        { $_ -in @("SupportedSTIGOutput", "ApplicableSTIGOutput") } {
	            if ($_ -eq "SupportedSTIGOutput") {
	                $formScriptOutput.Text = "Supported STIGs"
	            }
	            Else {
	                $formScriptOutput.Text = "Applicable STIGs"
	            }
	            
	            $richtextboxContent.Text = ($Content | Format-Table | Out-String).Trim()
	        }
	        "HelpOutput" {
	            $formScriptOutput.Text = "Evaluate-STIG Help"
	            $richtextboxContent.Text = ($Content | Out-String).Trim()
	        }
	        "AFView" {
	            $formScriptOutput.Text = $Title
	            $richtextboxContent.Text = ($Content | Out-String).Trim()
	        }
	        { $_ -in @("AFValidationOutput", "AFMaintainOutput", "AFExport") } {
	            $RegularText = New-Object System.Drawing.Font($richtextboxContent.SelectionFont.FontFamily, $richtextboxContent.SelectionFont.Size, [System.Drawing.FontStyle]::Regular)
	            $BoldText = New-Object System.Drawing.Font($richtextboxContent.SelectionFont.FontFamily, $richtextboxContent.SelectionFont.Size, [System.Drawing.FontStyle]::Bold)
	            
	            if ($_ -eq "AFValidationOutput") {
	                $formScriptOutput.Text = "Answer File Validation Results"
	            }
	            elseif ($_ -eq "AFMaintainOutput") {
	                $formScriptOutput.Text = "Answer File Maintenance Results"
	            }
	            elseif ($_ -eq "AFExport") {
	                $formScriptOutput.Text = "Answer File Export Results"
	            }
	            
	            foreach ($Key in $Content.Keys) {
	                if ($Key -ne "Info") {
	                    $richtextboxContent.SelectionFont = $BoldText; $richtextboxContent.AppendText($Key); $richtextboxContent.SelectionFont = $RegularText
	                    
	                    switch ($Content.$($Key).Result) {
	                        "Passed" {
	                            $richtextboxContent.AppendText(" : ")
	                            $richtextboxContent.SelectionColor = [System.Drawing.Color]::Green; $richtextboxContent.AppendText("$($Content.$($Key).Result)`n"); $richtextboxContent.SelectionColor = $richtextboxContent.ForeColor
	                        }
	                        "Success" {
	                            $richtextboxContent.AppendText(" : ")
	                            $richtextboxContent.SelectionColor = [System.Drawing.Color]::Green; $richtextboxContent.AppendText("$($Content.$($Key).Result)`n"); $richtextboxContent.SelectionColor = $richtextboxContent.ForeColor
	                        }
	                        "Failed" {
	                            $richtextboxContent.AppendText(" : ")
	                            $richtextboxContent.SelectionColor = [System.Drawing.Color]::Red; $richtextboxContent.AppendText("$($Content.$($Key).Result)`n"); $richtextboxContent.SelectionColor = $richtextboxContent.ForeColor
	                        }
	                    }
	                    
	                    foreach ($Line in $Content.$($Key).Message) {
	                        if ($Line.Trim() -match "^\*{2} Excluded from export \*{2}$") {
	                            # Messages enclosed in '**' are considered failures.
	                            $richtextboxContent.SelectionColor = [System.Drawing.Color]::Red; $richtextboxContent.AppendText("$($Line)`n"); $richtextboxContent.SelectionColor = $richtextboxContent.ForeColor
	                        }
	                        else {
	                            $richtextboxContent.AppendText("$($Line)`n")
	                        }
	                    }
	                }
	                else {
	                    foreach ($Line in $Content.$($Key).Message) {
	                        $richtextboxContent.AppendText("$($Line)`n")
	                    }
	                }
	                
	                $richtextboxContent.AppendText("`n")
	            }
	        }
	    }
	}
	
	# Begin Escape key handler to close form
	$formScriptOutput.Add_KeyDown({
	        param ($sender,
	            
	            $e)
	        
	        # Check if the pressed key is the Escape key
	        if ($e.KeyCode -eq [System.Windows.Forms.Keys]::Escape) {
	            # Close the form
	            $formScriptOutput.Close()
	        }
	    })
	# End Escape key handler to close form
	
	# --End User Generated Script--
	#----------------------------------------------
	#region Generated Events
	#----------------------------------------------
	
	$Form_StateCorrection_Load=
	{
		#Correct the initial state of the form to prevent the .Net maximized form issue
		$formScriptOutput.WindowState = $InitialFormWindowState
	}
	
	$Form_StoreValues_Closing=
	{
		#Store the control values
		$script:ScriptOutput_richtextboxContent = $richtextboxContent.Text
	}

	
	$Form_Cleanup_FormClosed=
	{
		#Remove all event handlers from the controls
		try
		{
			$formScriptOutput.remove_Load($formScriptOutput_Load)
			$formScriptOutput.remove_Load($Form_StateCorrection_Load)
			$formScriptOutput.remove_Closing($Form_StoreValues_Closing)
			$formScriptOutput.remove_FormClosed($Form_Cleanup_FormClosed)
		}
		catch { Out-Null <# Prevent PSScriptAnalyzer warning #> }
		$formScriptOutput.Dispose()
		$richtextboxContent.Dispose()
		$buttonOK.Dispose()
	}
	#endregion Generated Events

	#----------------------------------------------
	#region Generated Form Code
	#----------------------------------------------
	$formScriptOutput.SuspendLayout()
	#
	# formScriptOutput
	#
	$formScriptOutput.Controls.Add($richtextboxContent)
	$formScriptOutput.Controls.Add($buttonOK)
	$formScriptOutput.AcceptButton = $buttonOK
	$formScriptOutput.AutoScaleDimensions = New-Object System.Drawing.SizeF(96, 96)
	$formScriptOutput.AutoScaleMode = 'Dpi'
	$formScriptOutput.AutoSizeMode = 'GrowAndShrink'
	$formScriptOutput.ClientSize = New-Object System.Drawing.Size(984, 571)
	$formScriptOutput.FormBorderStyle = 'FixedSingle'
	$formScriptOutput.KeyPreview = $True
	$formScriptOutput.MaximizeBox = $False
	$formScriptOutput.MinimizeBox = $False
	$formScriptOutput.Name = 'formScriptOutput'
	$formScriptOutput.ShowIcon = $False
	$formScriptOutput.ShowInTaskbar = $False
	$formScriptOutput.StartPosition = 'CenterParent'
	$formScriptOutput.add_Load($formScriptOutput_Load)
	#
	# richtextboxContent
	#
	$richtextboxContent.BackColor = [System.Drawing.SystemColors]::Window 
	$richtextboxContent.Font = [System.Drawing.Font]::new('Consolas', '9.75')
	$richtextboxContent.Location = New-Object System.Drawing.Point(12, 12)
	$richtextboxContent.Margin = '10, 10, 10, 10'
	$richtextboxContent.Name = 'richtextboxContent'
	$richtextboxContent.ReadOnly = $True
	$richtextboxContent.Size = New-Object System.Drawing.Size(960, 510)
	$richtextboxContent.TabIndex = 6
	$richtextboxContent.TabStop = $False
	$richtextboxContent.Text = ''
	$richtextboxContent.WordWrap = $False
	#
	# buttonOK
	#
	$buttonOK.DialogResult = 'OK'
	$buttonOK.Location = New-Object System.Drawing.Point(897, 535)
	$buttonOK.Name = 'buttonOK'
	$buttonOK.Size = New-Object System.Drawing.Size(75, 23)
	$buttonOK.TabIndex = 5
	$buttonOK.Text = 'OK'
	$buttonOK.UseVisualStyleBackColor = $True
	$formScriptOutput.ResumeLayout()
	#endregion Generated Form Code

	#----------------------------------------------

	#Save the initial state of the form
	$InitialFormWindowState = $formScriptOutput.WindowState
	#Init the OnLoad event to correct the initial state of the form
	$formScriptOutput.add_Load($Form_StateCorrection_Load)
	#Clean up the control events
	$formScriptOutput.add_FormClosed($Form_Cleanup_FormClosed)
	#Store the control values when form is closing
	$formScriptOutput.add_Closing($Form_StoreValues_Closing)
	#Show the Form
	return $formScriptOutput.ShowDialog()

}
