param
(
    [Parameter(Mandatory = $false)]
    [String]$FormTitle,
    
    [Parameter(Mandatory = $false)]
    [Switch]$AllowSort,
    
    [Parameter(Mandatory = $true)]
    [String[]]$SourceList,
    
    [Parameter(Mandatory = $false)]
    [String[]]$CurrentList
)

	#----------------------------------------------
	#region Import the Assemblies
	#----------------------------------------------
	[void][reflection.assembly]::Load('System.Drawing, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b03f5f7f11d50a3a')
	[void][reflection.assembly]::Load('System.Windows.Forms, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089')
	[void][reflection.assembly]::Load('System.Data, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089')
	[void][reflection.assembly]::Load('PresentationFramework, Version=4.0.0.0, Culture=neutral, PublicKeyToken=31bf3856ad364e35')
	#endregion Import Assemblies

	#----------------------------------------------
	#region Generated Form Objects
	#----------------------------------------------
	[System.Windows.Forms.Application]::EnableVisualStyles()
	$formListboxCustomSort = New-Object 'System.Windows.Forms.Form'
	$buttonOK = New-Object 'System.Windows.Forms.Button'
	$buttonCancel = New-Object 'System.Windows.Forms.Button'
	$labelSelectedItems = New-Object 'System.Windows.Forms.Label'
	$labelAvailableItems = New-Object 'System.Windows.Forms.Label'
	$listboxSelected = New-Object 'System.Windows.Forms.ListBox'
	$buttonMoveDown = New-Object 'System.Windows.Forms.Button'
	$buttonMoveUp = New-Object 'System.Windows.Forms.Button'
	$buttonLeft = New-Object 'System.Windows.Forms.Button'
	$buttonRight = New-Object 'System.Windows.Forms.Button'
	$listboxAvailable = New-Object 'System.Windows.Forms.ListBox'
	$InitialFormWindowState = New-Object 'System.Windows.Forms.FormWindowState'
	#endregion Generated Form Objects

	#----------------------------------------------
	# User Generated Script
	#----------------------------------------------
	
	
	$formListboxCustomSort_Load = {
	    If ($FormTitle) {
	        $formListboxCustomSort.Text = $FormTitle
	    }
	    
	    If (-Not ($AllowSort)) {
	        # Hide the Move Up/Move Down buttons
	        $buttonMoveDown.Hide()
	        $buttonMoveUp.Hide()
	    }
	    
	    # Build Available Items list
	    foreach ($Item in $SourceList) {
	        If ($Item -notin $CurrentList) {
	            $listboxAvailable.Items.Add($Item)
	        }
	    }
	    
	    # Build Selected Items list
	    If ($CurrentList) {
	        foreach ($Item in $CurrentList) {
	            $listboxSelected.Items.Add($Item)
	        }
	    }
	}
	
	#region Control Helper Functions
	function Update-ListBox {
	<#
		.SYNOPSIS
			This functions helps you load items into a ListBox or CheckedListBox.
		
		.DESCRIPTION
			Use this function to dynamically load items into the ListBox control.
		
		.PARAMETER ListBox
			The ListBox control you want to add items to.
		
		.PARAMETER Items
			The object or objects you wish to load into the ListBox's Items collection.
		
		.PARAMETER DisplayMember
			Indicates the property to display for the items in this control.
			
		.PARAMETER ValueMember
			Indicates the property to use for the value of the control.
		
		.PARAMETER Append
			Adds the item(s) to the ListBox without clearing the Items collection.
		
		.EXAMPLE
			Update-ListBox $ListBox1 "Red", "White", "Blue"
		
		.EXAMPLE
			Update-ListBox $listBox1 "Red" -Append
			Update-ListBox $listBox1 "White" -Append
			Update-ListBox $listBox1 "Blue" -Append
		
		.EXAMPLE
			Update-ListBox $listBox1 (Get-Process) "ProcessName"
		
		.NOTES
			Additional information about the function.
	#>
	    
	    param
	    (
	        [Parameter(Mandatory = $true)]
	        [ValidateNotNull()]
	        [System.Windows.Forms.ListBox]$ListBox,
	        
	        [Parameter(Mandatory = $true)]
	        [ValidateNotNull()]
	        $Items,
	        
	        [Parameter(Mandatory = $false)]
	        [string]$DisplayMember,
	        
	        [Parameter(Mandatory = $false)]
	        [string]$ValueMember,
	        
	        [switch]$Append
	    )
	    
	    if (-not $Append) {
	        $ListBox.Items.Clear()
	    }
	    
	    if ($Items -is [System.Windows.Forms.ListBox+ObjectCollection] -or $Items -is [System.Collections.ICollection]) {
	        $ListBox.Items.AddRange($Items)
	    }
	    elseif ($Items -is [System.Collections.IEnumerable]) {
	        $ListBox.BeginUpdate()
	        foreach ($obj in $Items) {
	            $ListBox.Items.Add($obj)
	        }
	        $ListBox.EndUpdate()
	    }
	    else {
	        $ListBox.Items.Add($Items)
	    }
	    
	    if ($DisplayMember) {
	        $ListBox.DisplayMember = $DisplayMember
	    }
	    if ($ValueMember) {
	        $ListBox.ValueMember = $ValueMember
	    }
	}
	
	
	#endregion
	
	$listboxAvailable_MouseDoubleClick = [System.Windows.Forms.MouseEventHandler]{
	    if ($listboxAvailable.SelectedIndex -ne -1) {
	        $buttonRight_Click.Invoke($null, $null)
	    }
	}
	
	$buttonRight_Click = {
	    $selectedItemsToMove = @($listboxAvailable.SelectedItems)
	    foreach ($item in $selectedItemsToMove) {
	        # Add the item to the destination ListBox
	        [void]$listboxSelected.Items.Add($item)
	        # Remove the item from the source ListBox
	        [void]$listboxAvailable.Items.Remove($item)
	    }
	}
	
	$listboxSelected_MouseDoubleClick = [System.Windows.Forms.MouseEventHandler]{
	    if ($listboxSelected.SelectedIndex -ne -1) {
	        $buttonLeft_Click.Invoke($null, $null)
	    }
	}
	
	$buttonLeft_Click = {
	    $selectedItemsToMove = @($listboxSelected.SelectedItems)
	    
	    # Remove from Selected list
	    while ($listboxSelected.SelectedItems.Count -gt 0) {
	        $listboxSelected.Items.RemoveAt($listboxSelected.SelectedIndex)
	    }
	    
	    # Add to Available list and preserve initial order
	    $listboxAvailable.Items.Clear()
	    ForEach ($Item in $SourceList) {
	        If ($Item -notin $listboxSelected.Items) {
	            Update-ListBox -ListBox $listboxAvailable -Items $Item -Append
	        }
	    }
	}
	
	$buttonMoveUp_Click = {
	    $NewSelectedIndices = @()
	    
	    while ($listboxSelected.SelectedItems.Count -gt 0) {
	        # Get the item you want to move (e.g., the currently selected item)
	        $ItemToMove = $listboxSelected.SelectedItem
	        
	        # Get the current index of the item
	        $CurrentIndex = $listboxSelected.SelectedIndex
	        
	        # Specify the desired new index (e.g., move it up one position)
	        $NewIndex = $CurrentIndex - 1
	        
	        # Ensure the new index is valid (within the range of the list)
	        if ($NewIndex -ge 0 -and $NewIndex -notin $NewSelectedIndices) {
	            $NewSelectedIndices += $NewIndex
	            
	            # Remove the item from its current position
	            $listboxSelected.Items.RemoveAt($CurrentIndex)
	            
	            # Insert the item at the new position
	            $listboxSelected.Items.Insert($NewIndex, $ItemToMove)
	        }
	        else {
	            $NewSelectedIndices += $CurrentIndex
	            $listboxSelected.SetSelected($CurrentIndex, $false)
	        }
	    }
	    
	    foreach ($NewIndex in $NewSelectedIndices) {
	        $listboxSelected.SetSelected($NewIndex, $true)
	    }
	}
	
	$buttonMoveDown_Click = {
	    $NewSelectedIndices = @()
	    
	    while ($listboxSelected.SelectedItem.Count -gt 0) {
	        # Get the item you want to move (e.g., the currently selected item)
	        $ItemToMove = $listboxSelected.SelectedItems | Select-Object -Last 1
	        
	        # Get the current index of the item
	        $CurrentIndex = $listboxSelected.SelectedIndices | Select-Object -Last 1
	        
	        # Specify the desired new index (e.g., move it up one position)
	        $NewIndex = $CurrentIndex + 1
	        
	        # Ensure the new index is valid (within the range of the list)
	        if ($NewIndex -le ($listboxSelected.Items.Count - 1) -and $NewIndex -notin $NewSelectedIndices) {
	            $NewSelectedIndices += $NewIndex
	            
	            # Remove the item from its current position
	            $listboxSelected.Items.RemoveAt($CurrentIndex)
	            
	            # Insert the item at the new position
	            $listboxSelected.Items.Insert($NewIndex, $ItemToMove)
	        }
	        else {
	            $NewSelectedIndices += $CurrentIndex
	            $listboxSelected.SetSelected($CurrentIndex, $false)
	        }
	    }
	    
	    foreach ($NewIndex in $NewSelectedIndices) {
	        $listboxSelected.SetSelected($NewIndex, $true)
	    }
	}
	
	
	$buttonOK_Click = {
	    $script:SortedListboxOutput = @()
	    foreach ($Item in $listboxSelected.Items) {
	        $script:SortedListboxOutput += $Item
	    }
	}
	
	
	# --End User Generated Script--
	#----------------------------------------------
	#region Generated Events
	#----------------------------------------------
	
	$Form_StateCorrection_Load=
	{
		#Correct the initial state of the form to prevent the .Net maximized form issue
		$formListboxCustomSort.WindowState = $InitialFormWindowState
	}
	
	$Form_StoreValues_Closing=
	{
		#Store the control values
		$script:ListboxCustomSort_listboxSelected = $listboxSelected.SelectedItems
		$script:ListboxCustomSort_listboxAvailable = $listboxAvailable.SelectedItems
	}

	
	$Form_Cleanup_FormClosed=
	{
		#Remove all event handlers from the controls
		try
		{
			$buttonOK.remove_Click($buttonOK_Click)
			$listboxSelected.remove_MouseDoubleClick($listboxSelected_MouseDoubleClick)
			$buttonMoveDown.remove_Click($buttonMoveDown_Click)
			$buttonMoveUp.remove_Click($buttonMoveUp_Click)
			$buttonLeft.remove_Click($buttonLeft_Click)
			$buttonRight.remove_Click($buttonRight_Click)
			$listboxAvailable.remove_MouseDoubleClick($listboxAvailable_MouseDoubleClick)
			$formListboxCustomSort.remove_Load($formListboxCustomSort_Load)
			$formListboxCustomSort.remove_Load($Form_StateCorrection_Load)
			$formListboxCustomSort.remove_Closing($Form_StoreValues_Closing)
			$formListboxCustomSort.remove_FormClosed($Form_Cleanup_FormClosed)
