	        $textboxInstance.Text = ($Extracted -split "Instance:")[1].Trim()
	    }
	    
	    # Extract Database if it exists
	    $Extracted = $VulnData.FindingDetails -split "`r?`n" | Where-Object { $_ -match '^Database:' }
	    If ($Extracted) {
	        $checkboxDatabase.Enabled = $true
