	$NewAnswerFile_Load = {
	    # Update STIGData with Status and Finding Details
	    foreach ($Key in $STIGData.GroupIDs.Keys) {
	        # Initialize $Status and $FindingDetails variables
	        $Status = "NR"
	        $FindingDetails = ""
	        
	        # Add Status and Finding Details to key
	        $STIGData.GroupIDs.$($Key).Add("Status", $Status)
	        $STIGData.GroupIDs.$($Key).Add("FindingDetails", $FindingDetails)
	    }
	    
	    $textboxAFPath.Text = $AFPath
	    $textboxFileName.Text = "$($ShortName)_AnswerFile"
	    $groupboxShortName.Text = $ShortName
	    $radiobuttonGroupID.Checked = $true
	    $checkboxNR.Checked = $true
	    $checkboxOpen.Checked = $true
	    
	    # Populate $checkedlistboxVulns
	    Update-STIGData -STIGData $STIGData
	    
	    # Set import states based on last import
	    $checkboxExpectedStatus.Checked = $script:AFImportExpectedStatus
	    $checkboxInstance.Checked = $script:AFImportInstance
	    $checkboxDatabase.Checked = $script:AFImportDatabase
	    $checkboxSite.Checked = $script:AFImportSite
	    $checkboxResultHash.Checked = $script:AFImportResultHash
	}
	
	
	#region Control Helper Functions
	function Update-ListBox {
	<#
		.SYNOPSIS
			This functions helps you load items into a ListBox or CheckedListBox.
		
		.DESCRIPTION
			Use this function to dynamically load items into the ListBox control.
		
		.PARAMETER ListBox
			The ListBox control you want to add items to.
		
		.PARAMETER Items
			The object or objects you wish to load into the ListBox's Items collection.
		
		.PARAMETER DisplayMember
			Indicates the property to display for the items in this control.
			
		.PARAMETER ValueMember
			Indicates the property to use for the value of the control.
		
		.PARAMETER Append
			Adds the item(s) to the ListBox without clearing the Items collection.
		
		.EXAMPLE
			Update-ListBox $ListBox1 "Red", "White", "Blue"
		
		.EXAMPLE
			Update-ListBox $listBox1 "Red" -Append
			Update-ListBox $listBox1 "White" -Append
			Update-ListBox $listBox1 "Blue" -Append
		
		.EXAMPLE
			Update-ListBox $listBox1 (Get-Process) "ProcessName"
		
		.NOTES
			Additional information about the function.
	#>
	    
	    param
	    (
	        [Parameter(Mandatory = $true)]
	        [ValidateNotNull()]
	        [System.Windows.Forms.ListBox]$ListBox,
	        
	        [Parameter(Mandatory = $true)]
	        [ValidateNotNull()]
	        $Items,
	        
	        [Parameter(Mandatory = $false)]
	        [string]$DisplayMember,
	        
	        [Parameter(Mandatory = $false)]
	        [string]$ValueMember,
	        
	        [switch]$Append
	    )
	    
	    if (-not $Append) {
	        $ListBox.Items.Clear()
	    }
	    
	    if ($Items -is [System.Windows.Forms.ListBox+ObjectCollection] -or $Items -is [System.Collections.ICollection]) {
	        $ListBox.Items.AddRange($Items)
	    }
	    elseif ($Items -is [System.Collections.IEnumerable]) {
	        $ListBox.BeginUpdate()
	        foreach ($obj in $Items) {
	            $ListBox.Items.Add($obj)
	        }
	        $ListBox.EndUpdate()
	    }
	    else {
	        $ListBox.Items.Add($Items)
	    }
	    
	    if ($DisplayMember) {
	        $ListBox.DisplayMember = $DisplayMember
	    }
	    if ($ValueMember) {
	        $ListBox.ValueMember = $ValueMember
	    }
	}
	
	
	#endregion
	
	
	function Create-AnswerFile {
	    # Create ordered hashtable of answer file data
	    $TempObj = [ordered]@{
	        $ShortName = [ordered]@{
	            _Comment = "Evaluate-STIG answer file for $($STIGData.STIGID -replace '_', ' ')"
	        }
	    }
	    
	    foreach ($Vuln in $checkedlistboxVulns.CheckedItems) {
	        $VulnID = ($Vuln -split ":")[0].Trim()
	        
	        # Initialize attributes
	        $ExpectedStatus = "NR"
	        $Hostname = ""
	        $Instance = ""
	        $Database = ""
	        $Site = ""
	        $ResultHash = ""
	        
	        foreach ($Key in $STIGData.GroupIDs.Keys) {
	            if ($radiobuttonGroupID.Checked) {
	                if ($STIGData.GroupIDs.$($Key).GroupID -eq $VulnID) {
	                    $CheckItem = $STIGData.GroupIDs.$($Key)
	                    break
	                }
	            }
	            elseif ($radiobuttonRuleID.Checked) {
	                if ($STIGData.GroupIDs.$($Key).RuleID -eq $VulnID) {
	                    $CheckItem = $STIGData.GroupIDs.$($Key)
	                    break
	                }
	            }
	        }
	        
	        $VulnObj = [ordered]@{
	            # Add the RuleTitle as the comment
	            _Comment = "RuleTitle: $($CheckItem.RuleTitle)"
	        }
	        
	        $KeyNameObj = [ordered]@{
	            # Add default comment for AnswerKey
	            _Comment = "AnswerKey created by Evaluate-STIG_GUI.ps1"
	        }
	        
	        # Update ExpectedStatus if selected for import
	        If ($checkboxExpectedStatus.Checked) {
	            $ExpectedStatus = $CheckItem.Status
	        }
	        
	        # Update Instance if selected for import
	        If ($checkboxInstance.Checked) {
	            # Extract Instance if it exists
	            $Extracted = $CheckItem.FindingDetails -split "`r?`n" | Where-Object { $_ -match '^Instance:' }
	            If ($Extracted) {
	                $Instance = ($Extracted -split "Instance:")[1].Trim()
	            }
	        }
	        
	        # Update Database if selected for import
	        If ($checkboxDatabase.Checked) {
	            # Extract Database if it exists
	            $Extracted = $CheckItem.FindingDetails -split "`r?`n" | Where-Object { $_ -match '^Database:' }
	            If ($Extracted) {
	                $Database = ($Extracted -split "Database:")[1].Trim()
	            }
	        }
	        
	        # Update Site if selected for import
	        If ($checkboxSite.Checked) {
	            # Extract Site if it exists
	            $Extracted = $CheckItem.FindingDetails -split "`r?`n" | Where-Object { $_ -match '^Site:' }
	            If ($Extracted) {
	                $Site = ($Extracted -split "Site:")[1].Trim()
	            }
	        }
	        
	        # Update ResultHash if selected for import
	        If ($checkboxResultHash.Checked) {
	            # Extract ResultHash if it exists
	            $Extracted = $CheckItem.FindingDetails -split "`r?`n" | Where-Object { $_ -match '^ResultHash:' }
	            If ($Extracted) {
	                $ResultHash = ($Extracted -split "ResultHash:")[1].Trim()
	            }
	        }
	        
	        # Build the Index object
	        $IndexObj = [ordered]@{
	            _Comment       = "Index created by Evaluate-STIG_GUI.ps1"
	            ExpectedStatus = (Convert-Status -InputObject $ExpectedStatus -Output $StatusFormat)
	            Hostname       = $Hostname
	            Instance       = $Instance
	            Database       = $Database
	            Site           = $Site
	            ResultHash     = $ResultHash
	            ValidationCode = ""
	            ValidTrueStatus = ""
	            ValidTrueComment = ""
	            ValidFalseStatus = ""
	            ValidFalseComment = ""
	        }
	        
	        $KeyNameObj.Add("1", $IndexObj) # Create Index subobject for Answer element
	        $VulnObj.Add($script:DefaultAFKey, $KeyNameObj) # Create Name subobject for AnswerKey element
	        
	        # Add $VulnObj to $TempObj
	        $TempObj.$($ShortName).Add($VulnID, $VulnObj)
	    }
	    
	    # Save $TempObj to answer file
	    $FilePath = "$(Join-Path -Path $textboxAFPath.Text -ChildPath $textboxFileName.Text).xml"
	    if (Test-Path $FilePath) {
	        if ([System.Windows.Forms.MessageBox]::Show("'$($FilePath)' already exists.  Overwrite?", 'Warning', [System.Windows.Forms.MessageBoxButtons]::OKCancel, [System.Windows.Forms.MessageBoxIcon]::Warning) -eq "OK") {
	            Save-AnswerFileObject -AFObject $TempObj -Path $FilePath
	            $script:NewFileName = "$($textboxFileName.Text).xml"
	            $NewAnswerFile.DialogResult = [System.Windows.Forms.DialogResult]::OK
	            $NewAnswerFile.Close()
	        }
	    }
	    else {
	        Save-AnswerFileObject -AFObject $TempObj -Path $FilePath
	        $script:NewFileName = "$($textboxFileName.Text).xml"
	        $NewAnswerFile.DialogResult = [System.Windows.Forms.DialogResult]::OK
	        $NewAnswerFile.Close()
	    }
	}
	
	function Update-STIGData {
	    param (
	        [Parameter(Mandatory = $true)]
	        [psobject]$STIGData,
	        
	        [Parameter(Mandatory = $false)]
	        [psobject]$ResultData
	    )
	    
	    if ($ResultData) {
	        # Update STIGData with Status and Finding Details
	        foreach ($Key in $STIGData.GroupIDs.Keys) {
	            # Initialize $Status and $FindingDetails variables
	            $Status = "NR"
	            $FindingDetails = ""
	            if ($Key -in $ResultData[0].GroupIDs.Keys) {
	                $Status = (Convert-Status -InputObject $ResultData[0].GroupIDs.$($Key).Status -Output EvalSTIG)
	                $FindingDetails = $ResultData[0].GroupIDs.$($Key).FindingDetails
	            }
	            
	            # Update Status and Finding Details
	            $STIGData.GroupIDs.$($Key)."Status" = $Status
	            $STIGData.GroupIDs.$($Key)."FindingDetails" = $FindingDetails
	        }
	    }
	    
	    Update-VulnList -STIGData $STIGData
	}
	
	function Update-VulnList {
	    param (
	        [Parameter(Mandatory = $true)]
	        [psobject]$STIGData
	    )
	    
	    # Clear existing values
	    $textboxRuleTitle.Text = ""
	    $richtextboxCheckText.Text = ""
	    $richtextboxFindingDetails.Text = ""
	    
	    # Populate $checkedlistboxVulns
	    $checkedlistboxVulns.Items.Clear()
	    foreach ($Key in $STIGData.GroupIDs.Keys) {
	        # Initialize ToDisplay.  Only checks with matching Status box checked will be displayed.
	        $ToDisplay = $false
	        
	        if ($radiobuttonGroupID.Checked) {
	            # Display by GroupID
	            $CheckItem = $STIGData.GroupIDs.$($Key).GroupID
	        }
	        elseif ($radiobuttonRuleID.Checked) {
	            # Display by RuleID
	            $CheckItem = $STIGData.GroupIDs.$($Key).RuleID
	        }
	        
	        switch ($STIGData.GroupIDs.$($Key).Status) {
	            "NR" {
	                if ($checkboxNR.Checked) {
	                    $ToDisplay = $true
	                    $Status = $_
	                }
	            }
	            "O" {
	                if ($checkboxOpen.Checked) {
	                    $ToDisplay = $true
	                    $Status = $_
	                }
	            }
	            "NA" {
	                if ($checkboxNA.Checked) {
	                    $ToDisplay = $true
	                    $Status = $_
	                }
	            }
	            "NF" {
	                if ($checkboxNF.Checked) {
	                    $ToDisplay = $true
	                    $Status = $_
	                }
	            }
	        }
	        
	        if ($ToDisplay) {
	            Update-ListBox -ListBox $checkedlistboxVulns -Items "$($CheckItem) : ($($Status))" -Append
	        }
	    }
	}
	
	$buttonAF_ImportResult_Click = {
	    $BrowserTitle = "Select checklist file:"
	    $SelectedFile = Invoke-FileBrowser -Action Open -Title $BrowserTitle -InitialDirectory $script:ESResultsPath -Filter "Checklist Files (*.ckl,*.cklb)|*.ckl;*.cklb"
	    
	    if ($SelectedFile) {
	        $labelGUIState.Text = "Parsing..."; $labelGUIState.ForeColor = 'Yellow'
	        $formEvaluateSTIG.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
	        Start-Sleep -Milliseconds 50
	        
	        switch ([System.IO.Path]::GetExtension($SelectedFile)) {
	            ".ckl" {
	                $CheckListData = Convert-ChecklistToHashTable -InputObject ([XML](Get-Content $SelectedFile -Raw)) -InputType CKL
	            }
	            ".cklb" {
	                $CheckListData = Convert-ChecklistToHashTable -InputObject (Get-Content $SelectedFile -Raw | ConvertFrom-Json) -InputType CKLB
	            }
	        }
	        
	        $labelGUIState.Text = "Idle"; $labelGUIState.ForeColor = 'White'
	        $formEvaluateSTIG.Cursor = [System.Windows.Forms.Cursors]::Default
	        Start-Sleep -Milliseconds 50
	        
	        # Check that the desired STIG is in the checklist
	        if ($STIGData.STIGID -in $CheckListData.Keys) {
	            $STIGKey = $CheckListData.$($STIGData.STIGID)
	            # Check that the ReleaseInfo match
	            if ($STIGKey.ReleaseInfo -eq $STIGData.ReleaseInfo) {
	                Update-STIGData -STIGData $STIGData -ResultData $CheckListData
	            }
	            else {
	                # ReleaseInfo mismatch
	                [System.Windows.Forms.MessageBox]::Show("Checklist release does not match supported STIG.  Please run Evaluate-STIG $($script:evalSTIGVersionNumber.Trim() -replace '"') against the host to generate a new checklist for import.`r`n`r`nXCCDF:`t`t$($STIGData.ReleaseInfo)`r`nChecklist:`t$($STIGKey.ReleaseInfo)", "Error", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
            }
        }
        else {
            # Checklist does not contain the desired STIG
            [System.Windows.Forms.MessageBox]::Show("$($SelectedFile) does not contain a result for STIG '$($STIGData.STIGID)'.", "Error", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
        }
    }
}

