$buttonCheckAll_Click = {
    for ($i = 0; $i -lt $checkedlistboxVulns.Items.Count; $i++) {
        # Set the checked state of the current item to true
        $checkedlistboxVulns.SetItemChecked($i, $true)
    }
}

$buttonUncheckAll_Click = {
    for ($i = 0; $i -lt $checkedlistboxVulns.Items.Count; $i++) {
        # Set the checked state of the current item to true
        $checkedlistboxVulns.SetItemChecked($i, $false)
    }
}

$checkedlistboxVulns_SelectedIndexChanged = {
    foreach ($Key in $STIGData.GroupIDs.Keys) {
        if ($radiobuttonGroupID.Checked) {
            if ($STIGData.GroupIDs.$($Key).GroupID -eq ($checkedlistboxVulns.SelectedItem -split ":")[0].Trim()) {
                $textboxRuleTitle.Text = $STIGData.GroupIDs.$($Key).RuleTitle
                $richtextboxCheckText.Text = $STIGData.GroupIDs.$($Key).CheckText
                $richtextboxFindingDetails.Text = $STIGData.GroupIDs.$($Key).FindingDetails
                break
            }
        }
        elseif ($radiobuttonRuleID.Checked) {
            if ($STIGData.GroupIDs.$($Key).RuleID -eq ($checkedlistboxVulns.SelectedItem -split ":")[0].Trim()) {
                $textboxRuleTitle.Text = $STIGData.GroupIDs.$($Key).RuleTitle
                $richtextboxCheckText.Text = $STIGData.GroupIDs.$($Key).CheckText
                $richtextboxFindingDetails.Text = $STIGData.GroupIDs.$($Key).FindingDetails
                break
            }
        }
    }
}

