	        'ArcGIS Server 10.3'                            = 'ArcGIS'
	        'Cisco IOS XE Router NDM'                       = 'CiscoXERtrNDM'
	        'Cisco IOS XE Switch L2S'                       = 'CiscoXESwtchL2S'
	        'Cisco IOS XE Switch NDM'                       = 'CiscoXESwtchNDM'
	        'Citrix VAD 7.x Workspace App'                  = 'CitrixWorkspace'
