	$formPrefs_AddEditSTIGMan_Load = {
	    switch ($Operation) {
	        "Add" {
	            $formPrefs_AddEditSTIGMan.Text = "Add STIGManager Collection Configuration"
	        }
	        "Edit" {
	            $formPrefs_AddEditSTIGMan.Text = "Edit STIGManager Collection Configuration"
	        }
	    }
	    if ($CollectionName) {
	        $textboxSMImport_COLLECTION.Text = $CollectionName
	    }
	    
	    if ($ClientID) {
	        $textboxSMImport_CLIENT_ID.Text = $ClientID
	    }
	    
	    if ($ClientCert) {
	        $textboxSMImport_CLIENT_CERT.Text = $ClientCert
	    }
	    
	    if ($ClientCertKey) {
	        $textboxSMImport_CLIENT_CERT_KEY.Text = $ClientCertKey
	    }
	    
	    if ($CollectionID) {
	        $textboxSMImport_COLLECTION_ID.Text = $CollectionID
	    }
	}
	
	$formPrefs_AddEditSTIGMan_FormClosing = [System.Windows.Forms.FormClosingEventHandler]{
	    if ($formPrefs_AddEditSTIGMan.DialogResult -eq [System.Windows.Forms.DialogResult]::OK) {
	        switch ($Operation) {
	            "Add" {
	                if ($textboxSMImport_COLLECTION.Text -in @($null, "")) {
	                    $ErrMsg = "SMImport_COLLECTION Name cannot be empty."
	                }
	                elseif ($textboxSMImport_COLLECTION.Text -in $script:PrefsObj.STIGManager.Keys) {
	                    $ErrMsg = "'$($textboxSMImport_COLLECTION.Text)' already exists."
	                }
	            }
	            "Edit" {
	                if ($textboxSMImport_COLLECTION.Text -in @($null, "")) {
	                    $ErrMsg = "SMImport_COLLECTION Name cannot be empty."
	                }
	                elseif ($textboxSMImport_COLLECTION.Text -ne $CollectionName) {
	                    if ($textboxSMImport_COLLECTION.Text -in $script:PrefsObj.STIGManager.Keys) {
	                        $ErrMsg = "'$($textboxSMImport_COLLECTION.Text)' already exists."
	                    }
	                }
	            }
	        }
	        
	        if ($ErrMsg) {
	            [System.Windows.Forms.MessageBox]::Show($ErrMsg, 'Warning', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning)
	            $_.Cancel = $true
	        }
	    }
	}
	
	$buttonOK_Click = {
	    $script:Result = @{
	        CollectionName = $textboxSMImport_COLLECTION.Text
	        ClientID       = $textboxSMImport_CLIENT_ID.Text
	        ClientCert     = $textboxSMImport_CLIENT_CERT.Text
	        ClientCertKey  = $textboxSMImport_CLIENT_CERT_KEY.Text
	        CollectionID   = $textboxSMImport_COLLECTION_ID.Text
	    }
	}
	
	
